def seed_for(*parts):
    return int(np.random.SeedSequence([ACTIVE_SEED, *map(int, parts)])
               .generate_state(1)[0])


def oos_r2(y, pred):
    den = float(np.sum(np.square(y)))
    return float(1.0 - np.sum(np.square(y - pred)) / den) if den > 0 else np.nan


def wilson(k, n, alpha=0.05):
    if n == 0:
        return np.nan, np.nan
    z = norm.ppf(1 - alpha / 2)
    p = k / n
    den = 1 + z * z / n
    center = (p + z * z / (2 * n)) / den
    radius = z * np.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / den
    return max(0.0, center - radius), min(1.0, center + radius)


