# %% Cell 4: Data and prediction model
def make_sim_panel(rho, dgp, seed):
    rng = np.random.default_rng(seed)
    k, n = CFG["k"], CFG["n_assets"]
    nt = CFG["train_months"] + CFG["valid_months"] + CFG["test_months"]
    cov = (1 - rho) * np.eye(k) + rho * np.ones((k, k))
    chol = np.linalg.cholesky(cov)
    innovations = rng.standard_normal((nt, n, k)) @ chol.T
    x = np.empty_like(innovations)
    x[0] = innovations[0]
    for month in range(1, nt):
        x[month] = (CFG["x_ar"] * x[month - 1]
                    + np.sqrt(1 - CFG["x_ar"] ** 2) * innovations[month])
    flat = x.reshape(-1, k)
    signal = 0.7 * flat[:, 0] - 0.5 * flat[:, 1] + 0.35 * flat[:, 2]
    signal += 0.2 * flat[:, 3] - 0.15 * flat[:, 4] + 0.1 * flat[:, 5]
    if dgp == "Nonlinear":
        signal += (0.45 * np.sin(flat[:, 0])
                   + 0.3 * (flat[:, 2] ** 2 - 1)
                   + 0.35 * flat[:, 3] * flat[:, 4])
    noise = rng.standard_normal(len(flat)) * CFG["train_noise"]
    noise *= 0.7 + 0.3 * np.abs(flat[:, 0])
    frame = pd.DataFrame(flat, columns=[f"X{j + 1}" for j in range(k)])
    frame.insert(0, "id", np.tile(np.arange(n), nt))
    frame.insert(1, "date", np.repeat(np.arange(nt), n))
    frame["y"] = signal + noise
    return frame


class ReturnPredictor:
    """Expose every prediction and attribution in the original response units."""

    def __init__(self, estimator, kind, target_mean=0.0, target_scale=1.0):
        self.estimator, self.kind = estimator, kind
        self.target_mean, self.target_scale = target_mean, target_scale

    def predict(self, x):
        pred = np.asarray(self.estimator.predict(x), dtype=float)
        return self.target_mean + self.target_scale * pred


def new_xgb(trees, seed):
    return XGBRegressor(
        n_estimators=int(trees), max_depth=CFG["depth"],
        learning_rate=CFG["learning_rate"], objective="reg:squarederror",
        tree_method="hist", subsample=CFG["subsample"],
        colsample_bytree=CFG["colsample"], reg_lambda=1.0,
        random_state=seed, n_jobs=CFG["n_jobs"],
    )


def new_mlp(seed, n_rows):
    return MLPRegressor(
        hidden_layer_sizes=tuple(CFG["mlp_hidden"]), activation="relu",
        solver="adam", alpha=CFG["mlp_alpha"],
        learning_rate_init=CFG["mlp_learning_rate"],
        batch_size=min(int(CFG["mlp_batch_size"]), int(n_rows)),
        max_iter=1, shuffle=True, early_stopping=False, random_state=seed,
    )


def fit_predictor(kind, x_train, y_train, x_valid, y_valid, seed, tag):
    """Select XGB trees or MLP epochs on validation, then refit on pre-test X/y."""
    y_train, y_valid = np.asarray(y_train, float), np.asarray(y_valid, float)
    x_pretest = np.concatenate([x_train, x_valid])
    y_pretest = np.concatenate([y_train, y_valid])
    rows = []
    if kind == "LR":
        candidate = LinearRegression().fit(x_train, y_train)
        loss = float(mean_squared_error(y_valid, candidate.predict(x_valid)))
        rows.append({"case": tag, "model": kind, "parameter": "none",
                     "value": 0, "valid_mse": loss, "selected": True})
        final = ReturnPredictor(LinearRegression().fit(x_pretest, y_pretest), kind)
    elif kind == "XGB":
        for trees in CFG["trees"]:
            candidate = new_xgb(trees, seed).fit(x_train, y_train)
            loss = float(mean_squared_error(y_valid, candidate.predict(x_valid)))
            rows.append({"case": tag, "model": kind, "parameter": "trees",
                         "value": int(trees), "valid_mse": loss})
        best = min(range(len(rows)), key=lambda i: rows[i]["valid_mse"])
        for i, row in enumerate(rows):
            row["selected"] = i == best
        final = ReturnPredictor(
            new_xgb(rows[best]["value"], seed).fit(x_pretest, y_pretest), kind)
    elif kind == "MLP":
        epochs = sorted(set(int(value) for value in CFG["mlp_epochs"]))
        if not epochs or epochs[0] < 1:
            raise ValueError("MLP epoch candidates must be positive integers.")
        # Response scaling is fitted to training data during selection.
        location, scale = float(y_train.mean()), max(float(y_train.std()), 1e-12)
        candidate = new_mlp(seed, len(y_train))
        scaled_y = (y_train - location) / scale
        for epoch in range(1, epochs[-1] + 1):
            candidate.partial_fit(x_train, scaled_y)
            if epoch in epochs:
                prediction = location + scale * candidate.predict(x_valid)
                loss = float(mean_squared_error(y_valid, prediction))
                rows.append({"case": tag, "model": kind, "parameter": "epochs",
                             "value": epoch, "valid_mse": loss})
        best = min(range(len(rows)), key=lambda i: rows[i]["valid_mse"])
        for i, row in enumerate(rows):
            row["selected"] = i == best
        # Fresh fit: its target scaler uses training + validation only.
        location = float(y_pretest.mean())
        scale = max(float(y_pretest.std()), 1e-12)
        estimator = new_mlp(seed, len(y_pretest))
        for _ in range(rows[best]["value"]):
            estimator.partial_fit(x_pretest, (y_pretest - location) / scale)
        final = ReturnPredictor(estimator, kind, location, scale)
    else:
        raise ValueError(f"Unknown prediction model: {kind}")
    if not np.isfinite(final.predict(x_pretest)).all():
        raise FloatingPointError(f"Nonfinite fitted predictions: {tag}")
    selected = next(row for row in rows if row["selected"])
    log("Fit", f"{tag}: {selected['parameter']}={selected['value']}, "
        f"valid MSE={selected['valid_mse']:.4f}")
    return final, pd.DataFrame(rows)


def save_predictor(model, path, preprocessor, names, imputer=None):
    """Persist standard estimators and target scaling without a custom-class pickle."""
    joblib.dump({"model": model.kind, "estimator": model.estimator,
                 "target_mean": model.target_mean, "target_scale": model.target_scale,
                 "preprocessor": preprocessor, "imputer": imputer,
                 "features": list(names)}, path)
    if model.kind == "XGB":
        model.estimator.save_model(str(Path(path).with_suffix(".json")))

# %% Cell 5: Conditional reference and local explanations
class GaussianReference:
    """A pre-test Gaussian reference with shrinkage covariance."""

    def __init__(self, x_ref, predict, seed):
        self.predict = predict
        self.k = x_ref.shape[1]
        fitted = LedoitWolf().fit(x_ref)
        self.mean = fitted.location_.copy()
        self.cov = fitted.covariance_.copy()
        self.cache = {}
        rng = np.random.default_rng(seed)
        draws = rng.multivariate_normal(self.mean, self.cov, CFG["base_draws"])
        self.base = float(np.mean(predict(draws)))

    def conditional_params(self, mask):
        if mask in self.cache:
            return self.cache[mask]
        obs = np.array([j for j in range(self.k) if mask & (1 << j)], dtype=int)
        miss = np.array([j for j in range(self.k) if not mask & (1 << j)], dtype=int)
        if len(obs):
            oo = self.cov[np.ix_(obs, obs)]
            om = self.cov[np.ix_(obs, miss)]
            gain = np.linalg.solve(oo, om)
            cond_cov = self.cov[np.ix_(miss, miss)] - om.T @ gain
        else:
            gain = np.zeros((0, len(miss)))
            cond_cov = self.cov[np.ix_(miss, miss)]
        cond_cov = (cond_cov + cond_cov.T) / 2
        eigval, eigvec = np.linalg.eigh(cond_cov)
        root = eigvec @ np.diag(np.sqrt(np.maximum(eigval, 0.0)))
        self.cache[mask] = obs, miss, gain, root
        return self.cache[mask]

    def values(self, x, draws, seed, label="CE"):
        """Enumerate coalitions; approximate their conditional expectations."""
        k = self.k
        if k > 10:
            raise ValueError("Exact coalition enumeration requires K <= 10.")
        values = np.empty((len(x), 1 << k), dtype=float)
        values[:, 0] = self.base
        values[:, -1] = self.predict(x)
        rng = np.random.default_rng(seed)
        for mask in tqdm(range(1, (1 << k) - 1), desc=label, leave=False):
            obs, miss, gain, root = self.conditional_params(mask)
            half = (draws + 1) // 2
            z = rng.standard_normal((half, len(miss)))
            z = np.concatenate([z, -z], axis=0)[:draws] @ root.T
            for start in range(0, len(x), CFG["ce_batch"]):
                stop = min(start + CFG["ce_batch"], len(x))
                xb = x[start:stop]
                center = self.mean[miss] + (xb[:, obs] - self.mean[obs]) @ gain
                filled = np.broadcast_to(xb[:, None, :],
                                         (len(xb), draws, k)).copy()
                filled[:, :, miss] = center[:, None, :] + z[None, :, :]
                values[start:stop, mask] = self.predict(
                    filled.reshape(-1, k)).reshape(len(xb), draws).mean(axis=1)
        return values


def conditional_shap(values, k):
    """Exact Shapley coalition weights applied to estimated coalition values."""
    attr = np.zeros((len(values), k))
    for j in range(k):
        for mask in range(1 << k):
            if mask & (1 << j):
                continue
            size = int(mask).bit_count()
            weight = 1.0 / (k * math.comb(k - 1, size))
            attr[:, j] += weight * (values[:, mask | (1 << j)] - values[:, mask])
    return attr


def ordered_cola(values, k, order=None):
    order = list(range(k)) if order is None else list(order)
    attr = np.zeros((len(values), k))
    prefix = 0
    for j in order:
        nxt = prefix | (1 << j)
        attr[:, j] = values[:, nxt] - values[:, prefix]
        prefix = nxt
    return attr


def local_lime(x_ref, x, predict, seed, names):
    """Convert continuous LIME slopes to feature contributions in output units."""
    explainer = LimeTabularExplainer(
        x_ref, mode="regression", feature_names=names,
        discretize_continuous=False, feature_selection="none",
        sample_around_instance=True, random_state=seed,
    )
    attr = np.zeros_like(x, dtype=float)
    base = np.empty(len(x), dtype=float)
    score = np.empty(len(x), dtype=float)
    for i in tqdm(range(len(x)), desc="LIME", leave=False):
        explanation = explainer.explain_instance(
            x[i], predict, num_features=x.shape[1],
            num_samples=CFG["lime_samples"],
            model_regressor=Ridge(alpha=CFG["lime_ridge"]),
        )
        weights = np.zeros(x.shape[1])
        for feature, weight in explanation.local_exp[1]:
            weights[feature] = weight
        scaled = (x[i] - explainer.scaler.mean_) / explainer.scaler.scale_
        attr[i] = weights * scaled
        base[i] = float(explanation.intercept[1])
        raw_score = explanation.score
        score[i] = float(raw_score[0] if isinstance(raw_score, dict) else raw_score)
    return attr, base, score


def explain_all(x_ref, x, model, seed, names):
    started = time.perf_counter()
    predict = lambda arr: np.asarray(model.predict(arr), dtype=float)
    reference = GaussianReference(x_ref, predict, seed)
    values = reference.values(x, CFG["ce_draws"], seed + 1, "Attribution CE")
    common_base = np.full(len(x), reference.base)
    attrs = {"SHAP": conditional_shap(values, x.shape[1]),
             "COLA": ordered_cola(values, x.shape[1])}
    bases = {"SHAP": common_base.copy(), "COLA": common_base.copy()}
    pred = predict(x)
    ablation = np.empty_like(x)
    for j in range(x.shape[1]):
        replaced = x.copy()
        replaced[:, j] = x_ref[:, j].mean()
        ablation[:, j] = pred - predict(replaced)
    attrs["Ablation"] = ablation
    bases["Ablation"] = np.full(len(x), float(predict(x_ref.mean(axis=0)[None])[0]))
    attrs["LIME"], bases["LIME"], lime_score = local_lime(
        x_ref, x, predict, seed + 2, names)
    log("XAI", f"Rows={len(x)}, K={x.shape[1]}, "
        f"time={time.perf_counter() - started:.1f}s")
    return attrs, bases, reference, pred, lime_score

# %% Cell 6: Explanation diagnostics
def condition_number(a):
    centered = a - a.mean(axis=0)
    scale = centered.std(axis=0, ddof=0)
    if len(a) <= a.shape[1] or np.any(scale <= 1e-12):
        return np.inf
    z = centered / scale
    s = np.linalg.svd(z, compute_uv=False)
    if s[-1] <= CFG["rank_tol"] * s[0]:
        return np.inf
    return float(s[0] / s[-1])


def diagnose_explanations(attrs, bases, reference, x, pred, dates, seed, tag):
    rng = np.random.default_rng(seed)
    # Cover every month; preserve whole cross-sections during later resampling.
    month_ids = np.unique(dates)
    per_month = max(1, CFG["fidelity_rows"] // len(month_ids))
    selected = np.sort(np.concatenate([
        rng.choice(np.flatnonzero(dates == month),
                   min(per_month, int(np.sum(dates == month))), replace=False)
        for month in month_ids
    ]))
    # Independent conditional draws keep evaluation separate from attribution.
    v_eval = reference.values(x[selected], CFG["eval_draws"], seed + 1,
                             "Held-out CE")
    k = x.shape[1]
    masks = np.arange(1, (1 << k) - 1)
    removed = 1.0 - ((masks[:, None] >> np.arange(k)) & 1)
    delta = pred[selected, None] - v_eval[:, masks]
    denominator = float(np.mean(delta ** 2))
    if denominator <= 1e-16:
        raise ValueError("The model has insufficient output variation for fidelity.")
    # Keep arbitrary-subset deletion as the original primary fidelity score.
    # Add one common ordered-prefix task for all methods, using the fixed order.
    # The empty prefix includes full reconstruction; the full prefix is trivial.
    prefix_masks = (1 << np.arange(k)) - 1
    prefix_removed = 1.0 - ((prefix_masks[:, None] >> np.arange(k)) & 1)
    prefix_delta = pred[selected, None] - v_eval[:, prefix_masks]
    prefix_denominator = float(np.mean(prefix_delta ** 2))
    if prefix_denominator <= 1e-16:
        raise ValueError("The model has insufficient variation for prefix fidelity.")
    point_rows, month_rows, aux_rows = [], [], []
    for method in METHODS:
        explained_delta = attrs[method][selected] @ removed.T
        squared_error = np.mean((explained_delta - delta) ** 2, axis=1)
        squared_ref = np.mean(delta ** 2, axis=1)
        losses = squared_error / denominator
        explained_prefix = attrs[method][selected] @ prefix_removed.T
        prefix_error = np.mean((explained_prefix - prefix_delta) ** 2, axis=1)
        prefix_ref = np.mean(prefix_delta ** 2, axis=1)
        prefix_losses = prefix_error / prefix_denominator
        for pos, (row_id, loss) in enumerate(zip(selected, losses)):
            point_rows.append({"case": tag, "method": method,
                               "row": int(row_id), "date": dates[row_id],
                               "err": float(squared_error[pos]),
                               "ref": float(squared_ref[pos]), "infid": float(loss),
                               "prefix_err": float(prefix_error[pos]),
                               "prefix_ref": float(prefix_ref[pos]),
                               "prefix_infid": float(prefix_losses[pos])})
        for month in np.unique(dates):
            keep = dates == month
            month_rows.append({"case": tag, "method": method, "date": month,
                               "n": int(keep.sum()),
                               "kappa": condition_number(attrs[method][keep])})
        residual = pred - bases[method] - attrs[method].sum(axis=1)
        scale = max(float(np.std(pred)), 1e-12)
        aux_rows.append({"case": tag, "method": method,
                         "recon_nrmse": float(np.sqrt(np.mean(residual ** 2)) / scale),
                         "mean_base": float(np.mean(bases[method]))})
    return pd.DataFrame(point_rows), pd.DataFrame(month_rows), pd.DataFrame(aux_rows)


def explanation_frame(attrs, bases, pred, meta, tag):
    frames = []
    for method in METHODS:
        block = meta.reset_index(drop=True).copy()
        block.insert(0, "case", tag)
        block.insert(1, "method", method)
        block["pred"] = pred
        block["base"] = bases[method]
        for j in range(attrs[method].shape[1]):
            block[f"A{j + 1}"] = attrs[method][:, j]
        frames.append(block)
    return pd.concat(frames, ignore_index=True)

# %% Cell 7: Shared-response conditional Fama-MacBeth experiment
def prepare_designs(attrs, dates):
    """Use identical full-rank months across all four methods."""
    designs, diagnostics = {m: {} for m in METHODS}, []
    for month in np.unique(dates):
        ix = np.flatnonzero(dates == month)
        for method in METHODS:
            a = attrs[method][ix]
            scale = a.std(axis=0, ddof=0)
            ok = len(ix) > a.shape[1] + 2 and np.all(scale > 1e-12)
            weights = None
            if ok:
                z = (a - a.mean(axis=0)) / scale
                d = np.column_stack([np.ones(len(z)), z])
                singular = np.linalg.svd(d, compute_uv=False)
                ok = singular[-1] > CFG["rank_tol"] * singular[0]
                if ok:
                    # A full-rank OLS map, obtained by a stable least-squares solve.
                    weights = np.linalg.lstsq(d, np.eye(len(d)),
                                              rcond=CFG["rank_tol"])[0]
                    designs[method][month] = {"ix": ix, "z": z, "weights": weights}
            diagnostics.append({"date": month, "method": method, "n": len(ix),
                                "valid": bool(ok), "kappa": condition_number(a)})
    common = sorted(set.intersection(*(set(designs[m]) for m in METHODS)))
    return designs, common, pd.DataFrame(diagnostics)


def generate_errors(x_panel, n_reps, seed):
    """Heteroskedastic errors with asset AR terms and a common AR factor."""
    rng = np.random.default_rng(seed)
    nt, n, _ = x_panel.shape
    ar, far = CFG["noise_ar"], CFG["factor_ar"]
    eps = rng.standard_normal((n_reps, nt, n))
    factor = rng.standard_normal((n_reps, nt))
    for month in range(1, nt):
        eps[:, month] = ar * eps[:, month - 1] + np.sqrt(1 - ar * ar) * eps[:, month]
        factor[:, month] = (far * factor[:, month - 1]
                           + np.sqrt(1 - far * far) * factor[:, month])
    scale = 0.7 + 0.3 * np.abs(x_panel[:, :, 0])
    loading = 0.4 * x_panel[:, :, 1]
    return eps * scale[None] + factor[:, :, None] * loading[None]


def hac_mean_se(coefs):
    """Nominal Bartlett HAC diagnostic; finite-sample calibration is separate."""
    nt = coefs.shape[1]
    centered = coefs - coefs.mean(axis=1, keepdims=True)
    long_run = np.mean(centered ** 2, axis=1)
    max_lag = min(CFG["hac_lags"], nt - 1)
    for lag in range(1, max_lag + 1):
        gamma = np.sum(centered[:, lag:] * centered[:, :-lag], axis=1) / nt
        long_run += 2 * (1 - lag / (max_lag + 1)) * gamma
    return np.sqrt(np.maximum(long_run * nt / (nt - 1) / nt, 1e-24))


def simulate_fmb(attrs, dates, x, seed, tag, common_months=None):
    designs, months, validity = prepare_designs(attrs, dates)
    validity.insert(0, "case", tag)
    if common_months is not None:
        months = sorted(set(months).intersection(common_months))
    validity["used_for_inference"] = validity["date"].isin(months)
    if len(months) < CFG["min_months"]:
        raise ValueError(f"Only {len(months)} common valid months for {tag}.")
    sizes = [len(designs["SHAP"][month]["ix"]) for month in months]
    if len(set(sizes)) != 1:
        raise ValueError("The simulation inference panel must be balanced.")
    if not np.all(np.diff(np.asarray(months, dtype=int)) == 1):
        raise ValueError("Inference months must be consecutive; inspect validity.csv.")
    index = np.stack([designs["SHAP"][month]["ix"] for month in months])
    x_panel = x[index]
    target = CFG["target"]
    # Define one response equation from the common original inputs, before any
    # method-specific projection: y(delta) = nuisance_mean + delta * signal + eps.
    # Within-month standardization gives delta the same input-signal units for
    # every prediction model and explanation method.
    x_scale = x_panel.std(axis=1, keepdims=True, ddof=0)
    if np.any(x_scale <= 1e-12):
        raise ValueError("The shared-response inputs need within-month variation.")
    source_z = (x_panel - x_panel.mean(axis=1, keepdims=True)) / x_scale
    signal = source_z[:, :, target]
    nuisance_columns = [j for j in range(CFG["k"]) if j != target]
    nuisance_mean = CFG["nuisance"] * source_z[:, :, nuisance_columns].sum(axis=2)
    maps = {m: np.stack([designs[m][month]["weights"][target + 1]
                         for month in months]) for m in METHODS}
    # The exact finite-panel OLS projection truth is available in a simulation.
    # A coordinate slope has a method-specific baseline and signal loading.
    # Report delta_hat = (mean_slope - null_truth) / signal_loading, so all
    # methods estimate the same imposed original-input effect delta.
    null_monthly = {m: np.einsum("tn,tn->t", maps[m], nuisance_mean)
                    for m in METHODS}
    effect_monthly = {m: np.einsum("tn,tn->t", maps[m], signal)
                      for m in METHODS}
    null_truth = {m: float(null_monthly[m].mean()) for m in METHODS}
    loading = {m: float(effect_monthly[m].mean()) for m in METHODS}
    for method in METHODS:
        if not np.isfinite(loading[method]) or abs(loading[method]) <= CFG["effect_loading_tol"]:
            raise ValueError(
                f"The common effect is unidentified in {tag}/{method}: "
                f"mean projection loading={loading[method]}. "
                "Inspect the fixed coordinate; no alternative feature is selected.")
        keep = validity["method"] == method
        validity.loc[keep, "null_truth"] = null_truth[method]
        validity.loc[keep, "signal_loading"] = loading[method]

    def draws(count, draw_seed):
        collected = {m: [] for m in METHODS}
        for start in range(0, count, CFG["mc_batch"]):
            batch = min(CFG["mc_batch"], count - start)
            eps = generate_errors(x_panel, batch, seed_for(draw_seed, start))
            for method in METHODS:
                collected[method].append(np.einsum("tn,btn->bt", maps[method], eps))
        return {m: np.concatenate(collected[m], axis=0) for m in METHODS}

    def statistics(noise, method, delta):
        # Recompute the HAC denominator for each alternative. The projected
        # signal loading and nuisance projection can vary across months.
        coefficients = (null_monthly[method][None, :]
                        + delta * effect_monthly[method][None, :] + noise)
        coefficient_mean = coefficients.mean(axis=1)
        coefficient_se = hac_mean_se(coefficients)
        estimate = (coefficient_mean - null_truth[method]) / loading[method]
        se = coefficient_se / abs(loading[method])
        return estimate, se, coefficient_mean, coefficient_se

    # This is an explicit known-DGP calibration benchmark. Nominal HAC results
    # remain visible; calibration does not establish a feasible empirical test.
    calibration = draws(CFG["cal_reps"], seed + 10)
    evaluation = draws(CFG["null_reps"], seed + 20)
    nominal_crit = float(student_t.ppf(1 - CFG["alpha"] / 2, len(months) - 1))
    summary_rows, power_rows, raw_rows, sample_rows = [], [], [], []
    # One response realization is reused by every method and prediction model.
    eps_one = generate_errors(x_panel, 1, seed_for(seed, 900))[0]
    y_null = nuisance_mean + eps_one
    for method in METHODS:
        cal_estimate, cal_se, _, _ = statistics(calibration[method], method, 0.0)
        crit = float(np.quantile(np.abs(cal_estimate / cal_se),
                                  1 - CFG["alpha"], method="higher"))
        estimate, se, coefficient_mean, coefficient_se = statistics(
            evaluation[method], method, 0.0)
        t_null = estimate / se
        rejected = np.abs(t_null) > nominal_crit
        calibrated_rejected = np.abs(t_null) > crit
        lo, hi = wilson(int(rejected.sum()), len(rejected), CFG["alpha"])
        adj_lo, adj_hi = wilson(int(calibrated_rejected.sum()), len(rejected), CFG["alpha"])
        rate, adj_rate = float(rejected.mean()), float(calibrated_rejected.mean())
        summary_rows.append({
            "case": tag, "method": method, "months": len(months),
            "size": rate, "size_lo": lo, "size_hi": hi,
            "size_mcse": np.sqrt(rate * (1 - rate) / len(rejected)),
            "adj_size": adj_rate, "adj_size_lo": adj_lo, "adj_size_hi": adj_hi,
            "adj_size_mcse": np.sqrt(adj_rate * (1 - adj_rate) / len(rejected)),
            "bias": float(estimate.mean()),
            "rmse": float(np.sqrt(np.mean(estimate ** 2))),
            "cover": float((np.abs(estimate) <= nominal_crit * se).mean()),
            "adj_cover": float((np.abs(estimate) <= crit * se).mean()),
            "crit": crit, "nominal_crit": nominal_crit,
            "reps": len(rejected), "cal_reps": len(cal_estimate),
            "target": f"X{target + 1}", "coordinate": f"A{target + 1}",
            "null_truth": null_truth[method], "signal_loading": loading[method],
            "scope": "Conditional common-response projection",
            "estimate_units": "Common original-input effect per within-month SD",
            "calibration": "Oracle null simulation under the known error DGP",
        })
        for delta in CFG["effects"]:
            alternative, alternative_se, _, _ = statistics(evaluation[method], method, delta)
            t_alternative = alternative / alternative_se
            hit = np.abs(t_alternative) > crit
            nominal_hit = np.abs(t_alternative) > nominal_crit
            plo, phi = wilson(int(hit.sum()), len(hit), CFG["alpha"])
            nlo, nhi = wilson(int(nominal_hit.sum()), len(hit), CFG["alpha"])
            p, nominal_p = float(hit.mean()), float(nominal_hit.mean())
            error = alternative - delta
            power_rows.append({
                "case": tag, "method": method, "effect": delta,
                "power": p, "lo": plo, "hi": phi,
                "mcse": np.sqrt(p * (1 - p) / len(hit)),
                "nominal_power": nominal_p, "nominal_lo": nlo, "nominal_hi": nhi,
                "bias": float(error.mean()), "rmse": float(np.sqrt(np.mean(error ** 2))),
                "cover": float((np.abs(error) <= nominal_crit * alternative_se).mean()),
                "adj_cover": float((np.abs(error) <= crit * alternative_se).mean()),
                "crit": crit, "nominal_crit": nominal_crit, "reps": len(hit),
                "null_truth": null_truth[method], "signal_loading": loading[method],
                "target": f"X{target + 1}", "coordinate": f"A{target + 1}",
                "scope": "Common response and original-input effect",
            })
        for rep in range(len(estimate)):
            raw_rows.append({
                "case": tag, "method": method, "rep": rep,
                "estimate": estimate[rep], "se": se[rep], "t": t_null[rep],
                "reject": bool(rejected[rep]),
                "calibrated_reject": bool(calibrated_rejected[rep]),
                "coefficient_estimate": coefficient_mean[rep],
                "coefficient_se": coefficient_se[rep],
                "null_truth": null_truth[method], "signal_loading": loading[method],
                "crit": crit, "nominal_crit": nominal_crit,
            })
        for tidx, month in enumerate(months):
            design = designs[method][month]
            direct = design["weights"] @ y_null[tidx]
            for asset in range(y_null.shape[1]):
                sample_rows.append({
                    "case": tag, "method": method, "date": month, "id": asset,
                    "source_row": int(index[tidx, asset]),
                    "y_null": float(y_null[tidx, asset]),
                    "signal": float(signal[tidx, asset]),
                    "nuisance_mean": float(nuisance_mean[tidx, asset]),
                    "epsilon": float(eps_one[tidx, asset]),
                    "beta_hat": float(direct[target + 1]),
                    "null_truth_month": float(null_monthly[method][tidx]),
                    "signal_loading_month": float(effect_monthly[method][tidx]),
                    "null_truth": null_truth[method], "signal_loading": loading[method],
                })
    return (pd.DataFrame(summary_rows), pd.DataFrame(power_rows),
            pd.DataFrame(raw_rows), validity, pd.DataFrame(sample_rows))


def stationary_indices(n_months, n_reps, rng, mean_block=None):
    """Politis-Romano stationary bootstrap of complete month indices."""
    length = (max(2, int(round(n_months ** (1 / 3))))
              if mean_block is None else int(mean_block))
    length = min(max(length, 1), n_months)
    index = np.empty((n_reps, n_months), dtype=int)
    index[:, 0] = rng.integers(0, n_months, n_reps)
    for j in range(1, n_months):
        restart = rng.random(n_reps) < 1.0 / length
        fresh = rng.integers(0, n_months, n_reps)
        index[:, j] = np.where(restart, fresh, (index[:, j - 1] + 1) % n_months)
    return index, length


def percentile_bounds(values):
    tail = (1 - BS["level"]) / 2
    # Order statistics also handle an infinite condition number explicitly.
    return np.quantile(values, [tail, 1 - tail], method="inverted_cdf")


def seed_bootstrap(frame, groups, metrics, name):
    """Resample complete paired run seeds within the supplied grouping keys."""
    seed_ids = sorted(CFG["seeds"])
    rng = np.random.default_rng(np.random.SeedSequence([CFG["seed"], 8800]))
    index = rng.integers(0, len(seed_ids), (BS["reps"], len(seed_ids)))
    records, distributions = [], []
    for group_key, block in frame.groupby(groups, sort=True, observed=True):
        key = group_key if isinstance(group_key, tuple) else (group_key,)
        labels = dict(zip(groups, key))
        values = block.set_index("seed").reindex(seed_ids)[metrics].to_numpy(float)
        if np.isnan(values).any():
            raise ValueError(f"Missing seed metrics in {labels}; inspect per-seed outputs.")
        sampled = values[index].mean(axis=1)
        for j, metric in enumerate(metrics):
            lo, hi = percentile_bounds(sampled[:, j])
            records.append({**labels, "metric": metric,
                            "mean": float(values[:, j].mean()),
                            "sd": (float(values[:, j].std(ddof=1))
                                   if np.isfinite(values[:, j]).all() else np.nan),
                            "lo": float(lo), "hi": float(hi),
                            "seeds": len(seed_ids), "boot": BS["reps"],
                            "unit": "Seed"})
        if BS["save_draws"]:
            draw_table = pd.DataFrame(sampled, columns=metrics)
            draw_table.insert(0, "rep", np.arange(BS["reps"]))
            for label, value in labels.items():
                draw_table[label] = value
            distributions.append(draw_table)
    if distributions:
        save_csv(pd.concat(distributions, ignore_index=True), f"{name}_draws")
    result = pd.DataFrame(records)
    save_csv(result, name)
    return result


def longest_month_span(months):
    """Select a contiguous calendar span for a time-series bootstrap."""
    ordered = sorted(set(str(month) for month in months))
    if not ordered:
        return []
    ordinals = np.array([pd.Period(month, freq="M").ordinal for month in ordered])
    cuts = np.flatnonzero(np.diff(ordinals) != 1) + 1
    chunks = np.split(np.arange(len(ordered)), cuts)
    largest = max(chunks, key=len)
    return [ordered[i] for i in largest]


def empirical_fmb(attrs, dates, y, run_seed):
    """Save monthly coefficients for later joint time-block resampling."""
    designs, _, validity = prepare_designs(attrs, dates)
    validity["seed"] = run_seed
    rows = []
    for method in METHODS:
        for month, design in designs[method].items():
            coefficient = design["weights"] @ y[design["ix"]]
            for j in range(attrs[method].shape[1]):
                rows.append({"seed": run_seed, "method": method, "date": str(month),
                             "feature": f"A{j + 1}", "coef": float(coefficient[j + 1])})
    return pd.DataFrame(rows, columns=["seed", "method", "date", "feature", "coef"]), validity


def bootstrap_empirical(results):
    """Joint time resamples across models/seeds; summarize each model separately."""
    fidelity = pd.concat([r["fidelity"] for r in results], ignore_index=True)
    monthly = pd.concat([r["monthly"] for r in results], ignore_index=True)
    coefs = pd.concat([r["coefs"] for r in results], ignore_index=True)
    seed_ids = sorted(CFG["seeds"])
    available = fidelity.groupby("date")[["model", "seed", "method"]].apply(
        lambda b: b.drop_duplicates().shape[0])
    expected = len(CFG["models"]) * len(seed_ids) * len(METHODS)
    months = longest_month_span(available[available == expected].index)
    if len(months) < BS["min_months"]:
        raise ValueError("Too few shared consecutive months for empirical bootstrap.")
    rng = np.random.default_rng(np.random.SeedSequence([CFG["seed"], 8900]))
    index, length = stationary_indices(len(months), BS["reps"], rng, BS["block"])
    sums = fidelity.groupby(["model", "seed", "method", "date"])[
        ["err", "ref", "prefix_err", "prefix_ref"]].sum()
    kap = monthly.set_index(["model", "seed", "method", "date"])["kappa"]
    rows, distributions = [], []
    for kind in CFG["models"]:
        for method in METHODS:
            numerator = np.array([sums.loc[(kind, s, method)].reindex(months)["err"].to_numpy()
                                  for s in seed_ids])
            denominator = np.array([sums.loc[(kind, s, method)].reindex(months)["ref"].to_numpy()
                                    for s in seed_ids])
            prefix_numerator = np.array([
                sums.loc[(kind, s, method)].reindex(months)["prefix_err"].to_numpy()
                for s in seed_ids])
            prefix_denominator = np.array([
                sums.loc[(kind, s, method)].reindex(months)["prefix_ref"].to_numpy()
                for s in seed_ids])
            condition = np.array([kap.loc[(kind, s, method)].reindex(months).to_numpy()
                                  for s in seed_ids])
            # One set of month indices pairs every model/seed/method comparison.
            fid_draws = (numerator[:, index].sum(axis=2)
                         / denominator[:, index].sum(axis=2)).mean(axis=0)
            prefix_draws = (prefix_numerator[:, index].sum(axis=2)
                            / prefix_denominator[:, index].sum(axis=2)).mean(axis=0)
            kap_draws = np.median(condition[:, index], axis=2).mean(axis=0)
            fid_point = (numerator.sum(axis=1) / denominator.sum(axis=1)).mean()
            prefix_point = (prefix_numerator.sum(axis=1)
                            / prefix_denominator.sum(axis=1)).mean()
            kap_point = np.median(condition, axis=1).mean()
            for metric, point, sampled in [("infid", fid_point, fid_draws),
                                            ("prefix_infid", prefix_point, prefix_draws),
                                            ("kappa", kap_point, kap_draws)]:
                lo, hi = percentile_bounds(sampled)
                rows.append({"model": kind, "method": method, "metric": metric, "mean": point,
                             "lo": lo, "hi": hi, "boot": BS["reps"], "block": length,
                             "months": len(months), "seeds": len(seed_ids),
                             "unit": "Month", "scope": "Frozen models"})
                if BS["save_draws"]:
                    distributions.append(pd.DataFrame({"model": kind, "method": method,
                                                        "metric": metric,
                                                        "rep": np.arange(BS["reps"]),
                                                        "value": sampled}))
    save_csv(pd.DataFrame(rows), "appendix_real_boot_by_model")
    if distributions:
        save_csv(pd.concat(distributions, ignore_index=True), "real_boot_draws")
    if coefs.empty:
        save_csv(pd.DataFrame([{"status": "No full-rank months"}]), "real_fmb_status")
        return
    features = sorted(coefs["feature"].unique())
    wide = coefs.pivot(index="date", columns=["model", "seed", "method", "feature"], values="coef")
    required = pd.MultiIndex.from_product([CFG["models"], seed_ids, METHODS, features],
                                          names=["model", "seed", "method", "feature"])
    wide = wide.reindex(columns=required).dropna()
    fmb_months = longest_month_span(wide.index)
    if len(fmb_months) < BS["min_months"]:
        save_csv(pd.DataFrame([{"status": "Too few shared full-rank months",
                                "months": len(fmb_months)}]), "real_fmb_status")
        return
    wide = wide.reindex(fmb_months)
    fmb_rng = np.random.default_rng(np.random.SeedSequence([CFG["seed"], 8910]))
    fmb_index, fmb_length = stationary_indices(len(wide), BS["reps"], fmb_rng, BS["block"])
    fmb_rows, fmb_draws = [], []
    for kind in CFG["models"]:
        for method in METHODS:
            for feature in features:
                matrix = np.column_stack([wide[(kind, s, method, feature)].to_numpy()
                                          for s in seed_ids])
                # Average seeds within a prediction model before resampling months.
                series = matrix.mean(axis=1)
                boot = series[fmb_index].mean(axis=1)
                lo, hi = percentile_bounds(boot)
                fmb_rows.append({"model": kind, "method": method, "feature": feature,
                                 "mean": series.mean(), "boot_se": boot.std(ddof=1),
                                 "lo": lo, "hi": hi, "months": len(series),
                                 "seeds": len(seed_ids), "boot": BS["reps"],
                                 "block": fmb_length, "scope": "Frozen models"})
                if BS["save_draws"]:
                    fmb_draws.append(pd.DataFrame({"model": kind, "method": method,
                                                  "feature": feature,
                                                  "rep": np.arange(BS["reps"]), "value": boot}))
    save_csv(pd.DataFrame(fmb_rows), "appendix_real_fmb_boot_by_model")
    if fmb_draws:
        save_csv(pd.concat(fmb_draws, ignore_index=True), "real_fmb_boot_draws")
    save_csv(pd.DataFrame([{"status": "Complete", "months": len(wide),
                            "block": fmb_length, "start": fmb_months[0],
                            "end": fmb_months[-1], "models": len(CFG["models"])}]),
             "real_fmb_status")

# %% Cell 8: Run simulations
SIM = {key: [] for key in ["fit", "pred", "fidelity", "monthly", "aux",
                            "inference", "power", "draws", "validity", "sample"]}
SIM_STATUS = []
log("Scope", "Inference conditions on the fitted panels; all methods use one response DGP.")
log("Truth", "Shared y(delta) = nuisance_mean(X) + delta * standardized_X_target + eps.")
log("Test", "Report nominal HAC and independent known-DGP calibration together.")
log("Methods", "SHAP uses conditional Gaussian coalitions; COLA uses X1 to XK.")

SEED_MAP = []
case_specs = [(dgp, rho) for dgp in CFG["dgp"] for rho in CFG["rho"]]
for run_seed in tqdm(CFG["seeds"], desc="Seeds"):
    ACTIVE_SEED = run_seed
    log("Seed", f"Run seed={run_seed}")
    for case_id, (dgp, rho) in enumerate(tqdm(case_specs, desc="Data cases")):
        data_tag = f"{dgp}_rho{rho:.2f}_s{run_seed}"
        # Generate one panel and preprocess once, shared by all prediction models.
        frame = make_sim_panel(rho, dgp, seed_for(100))
        names = [f"X{j + 1}" for j in range(CFG["k"])]
        end_train = CFG["train_months"]
        end_valid = end_train + CFG["valid_months"]
        train = frame[frame["date"] < end_train].copy()
        valid = frame[(frame["date"] >= end_train) & (frame["date"] < end_valid)].copy()
        test = frame[frame["date"] >= end_valid].copy().reset_index(drop=True)
        scaler = StandardScaler().fit(train[names])
        xt, xv, xe = [scaler.transform(block[names]) for block in [train, valid, test]]
        x_ref = np.concatenate([xt, xv])
        y_train, y_valid, y_test = [block["y"].to_numpy() for block in [train, valid, test]]
        dates = test["date"].to_numpy()
        model_cases, valid_month_sets = [], []
        for kind in CFG["models"]:
            tag = f"{kind}_{data_tag}"
            case_dir = TABLE_DIR / tag
            case_dir.mkdir(exist_ok=True)
            started = time.perf_counter()
            log("Case", tag)
            fit_seed = seed_for(200, case_id, MODEL_CODES[kind])
            SEED_MAP.append({"case": tag, "seed": run_seed, "model": kind,
                             "data": seed_for(100), "fit": fit_seed,
                             "xai": seed_for(300, case_id), "diag": seed_for(400, case_id),
                             "infer": seed_for(500, case_id)})
            model, fit_table = fit_predictor(
                kind, xt, y_train, xv, y_valid, fit_seed, tag)
            for column, value in [("seed", run_seed), ("dgp", dgp), ("rho", rho)]:
                fit_table[column] = value
            SIM["fit"].append(fit_table)
            fit_table.to_csv(case_dir / "fit.csv", index=False)
            # Common integration streams and evaluation samples pair the models.
            attrs, bases, reference, pred, lime_score = explain_all(
                x_ref, xe, model, seed_for(300, case_id), names)
            SIM["pred"].append(pd.DataFrame([{
                "case": tag, "seed": run_seed, "dgp": dgp, "rho": rho, "model": kind,
                "n_train": len(train), "n_valid": len(valid), "n_test": len(test),
                "oos_r2": oos_r2(y_test, pred),
                "test_mse": mean_squared_error(y_test, pred),
                "lime_r2": float(np.nanmean(lime_score)),
            }]))
            fidelity, monthly, aux = diagnose_explanations(
                attrs, bases, reference, xe, pred, dates, seed_for(400, case_id), tag)
            _, valid_months, design_validity = prepare_designs(attrs, dates)
            design_validity["model"] = kind
            design_validity.to_csv(case_dir / "design_validity.csv", index=False)
            valid_month_sets.append(set(valid_months))
            save_predictor(model, case_dir / "model.joblib", scaler, names)
            model_cases.append({"kind": kind, "tag": tag, "case_dir": case_dir,
                                "attrs": attrs, "bases": bases, "pred": pred,
                                "fidelity": fidelity, "monthly": monthly, "aux": aux,
                                "fit_explain_seconds": time.perf_counter() - started})
            del reference, model
        # Use the same full-rank inference months for all 3 models and 4 XAI methods.
        common_months = sorted(set.intersection(*valid_month_sets))
        log("Inference", f"{data_tag}: {len(common_months)} shared full-rank months "
            f"across {len(CFG['models'])} models and {len(METHODS)} XAI methods.")
        for result in model_cases:
            infer_start = time.perf_counter()
            kind, tag, case_dir = result["kind"], result["tag"], result["case_dir"]
            inference, power, draws, validity, sample = simulate_fmb(
                result["attrs"], dates, xe, seed_for(500, case_id), tag, common_months)
            for key, table in [("fidelity", result["fidelity"]), ("monthly", result["monthly"]),
                                ("aux", result["aux"]), ("inference", inference),
                                ("power", power), ("draws", draws),
                                ("validity", validity), ("sample", sample)]:
                for column, value in [("seed", run_seed), ("model", kind),
                                      ("dgp", dgp), ("rho", rho)]:
                    table[column] = value
                SIM[key].append(table)
                table.to_csv(case_dir / f"{key}.csv", index=False)
            explained = explanation_frame(result["attrs"], result["bases"], result["pred"],
                                          test[["id", "date", "y"]], tag)
            explained["model"] = kind
            explained["seed"] = run_seed
            explained.to_csv(case_dir / "explanations.csv", index=False)
            row = {"case": tag, "model": kind, "seed": run_seed, "status": "Complete",
                   "seconds": result["fit_explain_seconds"] + time.perf_counter() - infer_start}
            SIM_STATUS.append(row)
            pd.DataFrame(SIM_STATUS).to_csv(TABLE_DIR / "sim_status.csv", index=False)
            log("Done", f"{tag}: {row['seconds']:.1f}s")
        del model_cases, result, attrs, bases, frame, test, train, valid, explained
        gc.collect()

ACTIVE_SEED = CFG["seed"]
save_csv(pd.DataFrame(SEED_MAP), "seed_map")

SIM_TABLES = {}
for key, parts in SIM.items():
    SIM_TABLES[key] = pd.concat(parts, ignore_index=True)
    save_csv(SIM_TABLES[key], f"sim_{key}")

fidelity_summary = (
    SIM_TABLES["fidelity"].groupby(["case", "model", "dgp", "rho", "seed", "method"], as_index=False)
    .agg(infid=("infid", "mean"), infid_sd=("infid", "std"),
         prefix_infid=("prefix_infid", "mean"), n_fid=("infid", "size"))
)
condition_summary = (
    SIM_TABLES["monthly"].groupby(["case", "method"], as_index=False)
    .agg(kappa=("kappa", "median"), months=("kappa", "size"))
)
bad_months = (
    SIM_TABLES["monthly"].assign(bad=lambda z: ~np.isfinite(z["kappa"]))
    .groupby(["case", "method"], as_index=False).agg(bad_months=("bad", "sum"))
)
condition_summary = condition_summary.merge(bad_months, on=["case", "method"])
summary = (
    fidelity_summary.merge(condition_summary, on=["case", "method"])
    .merge(SIM_TABLES["aux"][["case", "method", "recon_nrmse"]], on=["case", "method"])
    .merge(SIM_TABLES["inference"][["case", "method", "size", "adj_size",
                                   "cover", "adj_cover", "bias", "rmse",
                                   "null_truth", "signal_loading"]], on=["case", "method"])
)
display_effect = CFG["effects"][-2]
selected_power = SIM_TABLES["power"][np.isclose(SIM_TABLES["power"]["effect"], display_effect)]
summary = summary.merge(selected_power[["case", "method", "power", "nominal_power"]],
                        on=["case", "method"])
save_csv(summary, "sim_summary")
log("Bootstrap", f"Paired seed bootstrap: {BS['reps']} draws, {len(CFG['seeds'])} seeds.")
STAT_SUMMARY = seed_bootstrap(summary, ["model", "dgp", "rho", "method"],
                               ["infid", "prefix_infid", "recon_nrmse", "kappa", "size",
                                "adj_size", "cover", "adj_cover", "power", "nominal_power"], "seed_boot")
POWER_SUMMARY = seed_bootstrap(SIM_TABLES["power"], ["model", "dgp", "rho", "method", "effect"],
                                ["power", "nominal_power"], "power_boot")
main_stats = STAT_SUMMARY[STAT_SUMMARY["dgp"] == CFG["main_dgp"]]
main_table = main_stats.pivot(index=["model", "rho", "method"], columns="metric", values="mean")
main_table = main_table.reset_index()[["model", "rho", "method", "infid", "kappa",
                                            "size", "power", "prefix_infid",
                                            "recon_nrmse", "adj_size", "nominal_power"]]
main_table["model"] = pd.Categorical(main_table["model"], CFG["models"], ordered=True)
main_table["method"] = pd.Categorical(main_table["method"], METHODS, ordered=True)
main_table = main_table.sort_values(["model", "rho", "method"])
main_table.columns = ["Model", "Rho", "Method", "Infid", "Kappa", "Size", "Power",
                      "PrefixInfid", "Recon", "CalSize", "NominalPower"]
main_table.columns.name = None
log("Table", f"Per-model mean over {len(CFG['seeds'])} seeds; common effect={display_effect:.2f}.")
log("Table", "Size/NominalPower use nominal HAC; CalSize/Power use oracle calibration.")
save_csv(main_table, "appendix_main_by_model")
save_csv(main_stats, "appendix_main_ci_by_model")
prediction_summary = (
    SIM_TABLES["pred"].groupby(["model", "dgp", "rho"], as_index=False)
    .agg(R2=("oos_r2", "mean"), R2_SD=("oos_r2", "std"),
         MSE=("test_mse", "mean"), Seeds=("seed", "nunique"))
)
save_csv(prediction_summary, "appendix_prediction_by_model")

# Average fixed model specifications inside each independent simulation run.
# The paired run-seed bootstrap then resamples these aggregate run summaries.
aggregate_metrics = ["infid", "prefix_infid", "recon_nrmse", "kappa", "size",
                     "adj_size", "cover", "adj_cover", "power", "nominal_power"]
aggregate_runs = summary.groupby(["dgp", "rho", "method", "seed"], as_index=False)[aggregate_metrics].agg(
    lambda values: float(np.mean(values.to_numpy(float))))
aggregate_power_runs = SIM_TABLES["power"].groupby(
    ["dgp", "rho", "method", "effect", "seed"], as_index=False)[["power", "nominal_power"]].mean()
AGG_STAT_SUMMARY = seed_bootstrap(aggregate_runs, ["dgp", "rho", "method"],
                                 aggregate_metrics, "aggregate_seed_boot")
AGG_POWER_SUMMARY = seed_bootstrap(aggregate_power_runs, ["dgp", "rho", "method", "effect"],
                                  ["power", "nominal_power"], "aggregate_power_boot")
aggregate_main_stats = AGG_STAT_SUMMARY[AGG_STAT_SUMMARY["dgp"] == CFG["main_dgp"]]
aggregate_main = aggregate_main_stats.pivot(index=["rho", "method"], columns="metric", values="mean").reset_index()
aggregate_main["method"] = pd.Categorical(aggregate_main["method"], METHODS, ordered=True)
aggregate_main = aggregate_main.sort_values(["rho", "method"])
aggregate_main.columns.name = None
save_csv(aggregate_runs, "aggregate_per_seed")
save_csv(aggregate_main, "main", show=True)
save_csv(aggregate_main_stats, "main_ci")
aggregate_prediction_runs = SIM_TABLES["pred"].groupby(["dgp", "rho", "seed"], as_index=False)[
    ["oos_r2", "test_mse"]].mean()
aggregate_prediction = aggregate_prediction_runs.groupby(["dgp", "rho"], as_index=False).agg(
    R2=("oos_r2", "mean"), R2_SD=("oos_r2", "std"), MSE=("test_mse", "mean"), Seeds=("seed", "nunique"))
save_csv(aggregate_prediction, "prediction", show=True)

# %% Cell 9: Optional empirical panel
def parse_month(series, date_format=None):
    text = series.astype(str).str.replace(r"\.0$", "", regex=True)
    if date_format:
        parsed = pd.to_datetime(text, format=date_format, errors="raise")
    elif text.str.fullmatch(r"\d{6}").all():
        parsed = pd.to_datetime(text, format="%Y%m", errors="raise")
    else:
        parsed = pd.to_datetime(text, errors="raise")
    return parsed.dt.to_period("M")


def stable_cap(frame, cap, seed):
    if cap is None:
        return frame.copy()
    # Sampling depends on identifiers and month only, with a stable seed.
    return (frame.groupby("date", group_keys=False, sort=True)
            .apply(lambda block: block.sample(n=min(int(cap), len(block)),
                                              random_state=seed))
            .reset_index(drop=True))


def locate_real_panel():
    if not REAL["enabled"]:
        return None, "Disabled"
    path = Path(REAL["path"]).expanduser()
    if path.is_file():
        return path, "Local"
    if REAL["url"]:
        path.parent.mkdir(parents=True, exist_ok=True)
        log("Data", "Downloading the configured aligned panel.")
        urlretrieve(REAL["url"], path)
        return path, "URL"
    if REAL["upload"]:
        from google.colab import files
        log("Data", "Upload one aligned CSV or Parquet panel.")
        uploaded = files.upload()
        candidates = [name for name in uploaded
                      if Path(name).suffix.lower() in [".csv", ".parquet"]]
        if len(candidates) != 1:
            raise ValueError("Upload exactly one CSV or Parquet panel.")
        selected = BASE_DIR / Path(candidates[0]).name
        selected.write_bytes(uploaded[candidates[0]])
        return selected, "Upload"
    return None, "Missing input"


def load_real_panel(path):
    raw = pd.read_parquet(path) if path.suffix.lower() == ".parquet" else pd.read_csv(path)
    required = [REAL["id_col"], REAL["date_col"], REAL["target_col"]]
    missing = [name for name in required if name not in raw.columns]
    if missing:
        raise ValueError(f"Missing panel columns: {missing}")
    feature_names = REAL["features"]
    if feature_names is None:
        # Preserve the supplied schema order; use pre-test data for eligibility.
        feature_names = [name for name in raw.select_dtypes(include=np.number).columns
                         if name not in required]
    else:
        feature_names = list(feature_names)
    if not feature_names:
        raise ValueError("The panel needs numeric feature columns.")
    if set(feature_names) & set(required):
        raise ValueError("Feature columns must be distinct from id, date, and y.")
    feature_names = list(dict.fromkeys(feature_names))
    for name in feature_names:
        if name not in raw.columns:
            raise ValueError(f"Unknown feature: {name}")
    panel = raw[required + feature_names].copy()
    panel = panel.rename(columns={REAL["id_col"]: "id", REAL["date_col"]: "date",
                                   REAL["target_col"]: "y"})
    if panel[["id", "date"]].isna().any().any():
        raise ValueError("Panel identifiers and dates must be present.")
    panel["date"] = parse_month(panel["date"], REAL["date_format"])
    if panel.duplicated(["id", "date"]).any():
        raise ValueError("The panel contains duplicate id-month rows.")
    for name in ["y", *feature_names]:
        panel[name] = pd.to_numeric(panel[name], errors="raise")
    panel[["y", *feature_names]] = panel[["y", *feature_names]].replace(
        [np.inf, -np.inf], np.nan)
    panel = panel.dropna(subset=["y"]).sort_values(["date", "id"]).reset_index(drop=True)
    return panel, feature_names


def empirical_diagnostics(path, run_seed, kind, prepared=None):
    prefix = f"real_{kind}_s{run_seed}"
    panel, feature_names = load_real_panel(path) if prepared is None else prepared
    months = sorted(panel["date"].unique())
    purge = int(REAL["purge_months"])
    if REAL["train_end"] is not None or REAL["valid_end"] is not None:
        if REAL["train_end"] is None or REAL["valid_end"] is None:
            raise ValueError("Set both train_end and valid_end.")
        t_end = pd.Period(REAL["train_end"], freq="M")
        v_end = pd.Period(REAL["valid_end"], freq="M")
        tr_dates = [m for m in months if m <= t_end]
        va_dates = [m for m in months if t_end + purge < m <= v_end]
        te_dates = [m for m in months if m > v_end + purge]
    else:
        cut1 = int(len(months) * REAL["train_share"])
        cut2 = int(len(months) * (REAL["train_share"] + REAL["valid_share"]))
        tr_dates = months[:max(0, cut1 - purge)]
        va_dates = months[cut1:max(cut1, cut2 - purge)]
        te_dates = months[cut2:]
    if min(len(tr_dates), len(va_dates), len(te_dates)) < 3:
        raise ValueError("Each chronological split needs at least three months.")
    train = panel[panel["date"].isin(tr_dates)].copy()
    valid = panel[panel["date"].isin(va_dates)].copy()
    test = panel[panel["date"].isin(te_dates[:REAL["max_test_months"]])].copy()
    # Feature eligibility is determined exclusively from the training split.
    eligible = [name for name in feature_names
                if train[name].notna().sum() > 1
                and train[name].std(skipna=True) > 1e-12]
    selected = eligible[:int(REAL["max_features"])]
    if not 2 <= len(selected) <= 10:
        raise ValueError("The empirical benchmark requires 2 to 10 eligible features.")
    feature_map = pd.DataFrame({"Feature": [f"X{j + 1}" for j in range(len(selected))],
                                "Source": selected})
    save_csv(feature_map, f"{prefix}_features", show=False)
    log("Data", f"Empirical benchmark subset: {len(selected)} of {len(feature_names)} features.")
    train = stable_cap(train, REAL["max_train_per_month"], int(CFG["seed"] + 700))
    valid = stable_cap(valid, REAL["max_train_per_month"], int(CFG["seed"] + 701))
    test = stable_cap(test, REAL["max_test_per_month"], int(CFG["seed"] + 702))
    split_rows = []
    for name, block in [("Train", train), ("Valid", valid), ("Test", test)]:
        split_rows.append({"Split": name, "Rows": len(block),
                           "Months": block["date"].nunique(),
                           "Start": str(block["date"].min()),
                           "End": str(block["date"].max())})
    save_csv(pd.DataFrame(split_rows), f"{prefix}_split", show=False)
    imputer = SimpleImputer(strategy="median").fit(train[selected])
    xt = imputer.transform(train[selected])
    xv = imputer.transform(valid[selected])
    xe = imputer.transform(test[selected])
    if REAL["gaussianize"]:
        transformer = QuantileTransformer(n_quantiles=min(500, len(xt)),
                                          output_distribution="normal",
                                          random_state=int(CFG["seed"] + 703))
    else:
        transformer = StandardScaler()
    transformer.fit(xt)
    xt, xv, xe = [transformer.transform(a) for a in [xt, xv, xe]]
    y_train, y_valid, y_test = [b["y"].to_numpy() for b in [train, valid, test]]
    model, fit_table = fit_predictor(
        kind, xt, y_train, xv, y_valid, seed_for(704, MODEL_CODES[kind]), prefix)
    fit_table["seed"] = run_seed
    save_csv(fit_table, f"{prefix}_fit", show=False)
    attrs, bases, reference, pred, lime_score = explain_all(
        np.concatenate([xt, xv]), xe, model, seed_for(705), feature_map["Feature"].tolist())
    dates = test["date"].astype(str).to_numpy()
    fidelity, monthly, aux = diagnose_explanations(attrs, bases, reference, xe, pred,
                                                   dates, seed_for(706), prefix)
    for name, table in [("fidelity", fidelity), ("monthly", monthly), ("aux", aux)]:
        table["seed"] = run_seed
        table["model"] = kind
        save_csv(table, f"{prefix}_{name}")
    real_summary = (fidelity.groupby("method", as_index=False)
                    .agg(Infid=("infid", "mean"), PrefixInfid=("prefix_infid", "mean"))
                    .merge(monthly.groupby("method", as_index=False)
                           .agg(Kappa=("kappa", "median")), on="method")
                    .merge(aux[["method", "recon_nrmse"]], on="method"))
    real_summary["OOS R2"] = oos_r2(y_test, pred)
    real_summary = real_summary.rename(columns={"method": "Method", "recon_nrmse": "Recon"})
    real_summary["seed"] = run_seed
    real_summary.insert(0, "Model", kind)
    save_csv(real_summary, f"{prefix}_summary", show=False)
    meta = test[["id", "date", "y"]].copy()
    meta["date"] = meta["date"].astype(str)
    explained = explanation_frame(attrs, bases, pred, meta, prefix)
    explained["model"], explained["seed"] = kind, run_seed
    save_csv(explained, f"{prefix}_explanations")
    save_csv(pd.DataFrame([{"model": kind, "seed": run_seed, "oos_r2": oos_r2(y_test, pred),
                            "mse": mean_squared_error(y_test, pred),
                            "lime_r2": float(np.nanmean(lime_score)),
                            "features": len(selected), "n_test": len(test)}]), f"{prefix}_prediction")
    save_predictor(model, OUT_DIR / f"{prefix}_model.joblib", transformer, selected, imputer)
    coefs, validity = empirical_fmb(attrs, dates, y_test, run_seed)
    coefs["model"], validity["model"] = kind, kind
    save_csv(coefs, f"{prefix}_fmb")
    save_csv(validity, f"{prefix}_validity")
    return {
        "status": {"seed": run_seed, "model": kind, "status": "Complete", "source": str(path),
                   "rows": len(test), "features": len(selected)},
        "summary": real_summary, "fidelity": fidelity, "monthly": monthly,
        "coefs": coefs,
    }


REAL_RESULTS = []
REAL_RUN_STATUS = []
REAL_BOOT_STATUS = {"status": "Skipped"}
try:
    real_path, real_source = locate_real_panel()
    if real_path is None:
        REAL_STATUS = {"status": "Skipped", "source": real_source,
                       "detail": "Provide an aligned panel to enable empirical diagnostics."}
        log("Real", f"Skipped: {real_source}.")
    else:
        log("Real", f"Reading {real_path.name}")
        prepared_real = load_real_panel(real_path)
        for run_seed in tqdm(CFG["seeds"], desc="Real seeds"):
            ACTIVE_SEED = run_seed
            log("Real seed", str(run_seed))
            for kind in CFG["models"]:
                log("Real model", kind)
                result = empirical_diagnostics(real_path, run_seed, kind, prepared_real)
                REAL_RESULTS.append(result)
                REAL_RUN_STATUS.append(result["status"])
                save_csv(pd.DataFrame(REAL_RUN_STATUS), "real_seed_status")
        real_seed_summary = pd.concat([r["summary"] for r in REAL_RESULTS], ignore_index=True)
        save_csv(real_seed_summary, "real_per_seed")
        real_summary = (
            real_seed_summary.groupby(["Model", "Method"], as_index=False)
            .agg(Infid=("Infid", "mean"), Infid_SD=("Infid", "std"),
                 PrefixInfid=("PrefixInfid", "mean"),
                 PrefixInfid_SD=("PrefixInfid", "std"),
                 Kappa=("Kappa", "mean"), Kappa_SD=("Kappa", "std"),
                 Recon=("Recon", "mean"), R2=("OOS R2", "mean"))
        )
        save_csv(real_summary, "appendix_real_summary_by_model")
        real_macro_runs = real_seed_summary.groupby(["Method", "seed"], as_index=False)[
            ["Infid", "PrefixInfid", "Kappa", "Recon", "OOS R2"]].mean()
        real_macro_summary = real_macro_runs.groupby("Method", as_index=False).agg(
            Infid=("Infid", "mean"), PrefixInfid=("PrefixInfid", "mean"),
            Kappa=("Kappa", "mean"), Recon=("Recon", "mean"), R2=("OOS R2", "mean"))
        save_csv(real_macro_summary, "real_summary", show=True)
        REAL_STATUS = {"status": "Complete", "route": real_source,
                       "seeds": len(CFG["seeds"]), "models": CFG["models"],
                       "model_seed_runs": len(REAL_RESULTS), "source": str(real_path)}
        try:
            log("Bootstrap", f"Joint monthly stationary bootstrap: {BS['reps']} draws.")
            bootstrap_empirical(REAL_RESULTS)
            REAL_BOOT_STATUS = {"status": "Complete", "reps": BS["reps"],
                                "seeds": len(CFG["seeds"]), "models": CFG["models"],
                                "unit": "Month"}
        except Exception as exc:
            REAL_BOOT_STATUS = {"status": "Failed", "detail": str(exc)}
            (OUT_DIR / "real_boot_error.txt").write_text(traceback.format_exc(), encoding="utf-8")
            log("Bootstrap", f"Empirical bootstrap failed: {exc}")
        log("Real", "Empirical seed repetitions complete.")
except Exception as exc:
    REAL_STATUS = {"status": "Failed", "detail": str(exc), "complete_model_seed_runs": len(REAL_RESULTS)}
    (OUT_DIR / "real_error.txt").write_text(traceback.format_exc(), encoding="utf-8")
    log("Real", f"Failed: {exc}")
ACTIVE_SEED = CFG["seed"]
save_csv(pd.DataFrame([REAL_STATUS]), "real_status", show=True)
save_csv(pd.DataFrame([REAL_BOOT_STATUS]), "real_boot_status", show=True)

# %% Cell 10: One aggregate four-panel figure and optional appendix figures

FIGURE_LAYOUTS = {}


def place_legend_header(fig, axes, handles, ncol=3, hspace=0.50, wspace=0.38):
    """Preserve the physical panel canvas and add a measured legend header."""
    # Layout engines can override subplots_adjust or ignore figure legends.
    # Use one explicit physical layout for both saved files and inline figures.
    with mpl.rc_context({"figure.constrained_layout.use": False, "figure.autolayout": False}):
        fig.set_layout_engine(None)
    base_width, base_height = map(float, fig.get_size_inches())
    panel_axes = list(np.asarray(axes, dtype=object).ravel())
    side_pad, bottom_pad, top_pad, legend_gap = 0.12, 0.08, 0.12, 0.18
    fig.subplots_adjust(left=0.12, right=0.98, bottom=0.64 / base_height,
                        top=(base_height - 0.34) / base_height,
                        hspace=hspace, wspace=wspace)
    panel_rectangles = [
        (ax.get_position().x0 * base_width, ax.get_position().y0 * base_height,
         ax.get_position().width * base_width, ax.get_position().height * base_height)
        for ax in panel_axes
    ]
    columns = min(max(1, int(ncol)), len(handles))
    legend = None
    while True:
        if legend is not None:
            legend.remove()
        legend = fig.legend(
            handles=handles, loc="upper center", bbox_to_anchor=(0.5, 1.0),
            bbox_transform=fig.transFigure, ncol=columns, frameon=False,
            fontsize=8, borderaxespad=0.0, borderpad=0.20, labelspacing=0.45,
            columnspacing=1.10, handlelength=1.8, handletextpad=0.50,
        )
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        legend_box = legend.get_window_extent(renderer)
        legend_width, legend_height = legend_box.width / fig.dpi, legend_box.height / fig.dpi
        if legend_width <= base_width - 2 * side_pad or columns == 1:
            break
        columns -= 1
    panel_boxes = [ax.get_tightbbox(renderer) for ax in panel_axes]
    panel_boxes = [box for box in panel_boxes if box is not None]
    left_extra = max(0.0, side_pad - min(box.x0 / fig.dpi for box in panel_boxes))
    right_extra = max(0.0, max(box.x1 / fig.dpi for box in panel_boxes) - base_width + side_pad)
    bottom_extra = max(0.0, bottom_pad - min(box.y0 / fig.dpi for box in panel_boxes))
    panel_width = base_width + left_extra + right_extra
    final_width = max(panel_width, legend_width + 2 * side_pad)
    horizontal_offset = left_extra + (final_width - panel_width) / 2
    panel_ceiling = max(box.y1 / fig.dpi for box in panel_boxes) + bottom_extra
    header_bottom = max(base_height + bottom_extra, panel_ceiling) + legend_gap
    final_height = header_bottom + legend_height + top_pad

    def apply_canvas(height):
        fig.set_size_inches(final_width, height, forward=True)
        for ax, (left, bottom, width, panel_height) in zip(panel_axes, panel_rectangles):
            ax.set_position([(left + horizontal_offset) / final_width,
                             (bottom + bottom_extra) / height,
                             width / final_width, panel_height / height])
        legend.set_bbox_to_anchor((0.5, 1.0 - top_pad / height), transform=fig.transFigure)

    apply_canvas(final_height)
    # Font backends can differ; reserve the measured separation after resizing.
    for _ in range(3):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        current_top = max(ax.get_tightbbox(renderer).y1 / fig.dpi for ax in panel_axes)
        current_legend_bottom = legend.get_window_extent(renderer).y0 / fig.dpi
        missing = current_top + legend_gap - current_legend_bottom
        if missing <= 0.001:
            break
        final_height += missing + 0.02
        apply_canvas(final_height)
    fig.canvas.draw()
    return {
        "figure_inches": [float(final_width), float(final_height)],
        "panel_canvas_inches": [base_width, base_height],
        "legend_columns": columns,
        "legend_rows": int(math.ceil(len(handles) / columns)),
        "legend_height_inches": float(legend_height),
        "minimum_legend_gap_inches": legend_gap,
        "layout_engine": "none",
    }


plt.style.use(["science", "no-latex"])
mpl.rcParams.update(figsizes.icml2024_full(nrows=2, ncols=2, height_to_width_ratio=0.78))
mpl.rcParams.update({
    "font.family": "serif", "font.size": 9, "axes.labelsize": 9, "axes.titlesize": 10,
    "xtick.labelsize": 8, "ytick.labelsize": 8, "legend.fontsize": 8,
    "axes.spines.top": False, "axes.spines.right": False,
    "axes.grid": True, "grid.alpha": 0.16, "grid.linewidth": 0.4,
    "lines.linewidth": 1.2, "lines.markersize": 4,
    "pdf.fonttype": 42, "ps.fonttype": 42, "text.usetex": False,
    "figure.constrained_layout.use": False, "figure.autolayout": False, "savefig.bbox": None,
})


def plot_interval(ax, block, x_column, style):
    block = block.sort_values(x_column)
    x = block[x_column].to_numpy(float)
    y, lo, hi = [block[column].to_numpy(float) for column in ["mean", "lo", "hi"]]
    # Preserve unsupported positions as gaps; diagnostics remain in the tables.
    ax.plot(x, np.where(np.isfinite(y), y, np.nan), **style)
    band = np.isfinite(y) & np.isfinite(lo) & np.isfinite(hi)
    ax.fill_between(x, lo, hi, where=band, color=style["color"], alpha=0.12)


def plot_experiment(stats, powers, stem, title, show=False, combined_pdf=None):
    fig, axes = plt.subplots(2, 2, layout="none")

    selected = stats[stats["dgp"] == CFG["main_dgp"]]
    selected_power = powers[(powers["dgp"] == CFG["main_dgp"])
                            & np.isclose(powers["rho"], CFG["power_rho"])
                            & (powers["metric"] == "power")]
    for method in METHODS:
        style = {"color": COLORS[method], "marker": MARKERS[method]}
        block = selected[selected["method"] == method]
        plot_interval(axes[0, 0], block[block["metric"] == "infid"], "rho", style)
        plot_interval(axes[0, 1], block[block["metric"] == "kappa"], "rho", style)
        plot_interval(axes[1, 0], block[block["metric"] == "adj_size"], "rho", style)
        nominal = block[block["metric"] == "size"].sort_values("rho")
        axes[1, 0].plot(nominal["rho"], nominal["mean"], color=COLORS[method], ls="--", alpha=0.65)
        plot_interval(axes[1, 1], selected_power[selected_power["method"] == method], "effect", style)
    axes[0, 0].set(title="A  Subset deletion", xlabel="Rho", ylabel="Infidelity")
    axes[0, 1].set(title="B  Collinearity", xlabel="Rho", ylabel="Condition number", yscale="log")
    axes[1, 0].set(title="C  Test size", xlabel="Rho", ylabel="Rejection rate")
    axes[1, 0].axhline(CFG["alpha"], color="0.35", ls=":", lw=0.9)
    size_bounds = selected[selected["metric"].isin(["size", "adj_size"])]["hi"].to_numpy(float)
    finite_bounds = size_bounds[np.isfinite(size_bounds)]
    axes[1, 0].set_ylim(0, max(0.12, float(finite_bounds.max()) * 1.12) if len(finite_bounds) else 0.12)
    axes[1, 1].set(title="D  Calibrated power", xlabel="Common input effect", ylabel="Power", ylim=(0, 1.02))
    for ax in [axes[0, 0], axes[0, 1], axes[1, 0]]:
        ax.set_xticks(CFG["rho"])
    handles = [Line2D([], [], color=COLORS[m], marker=MARKERS[m], label=m) for m in METHODS]
    handles += [Line2D([], [], color="0.2", ls="-", label="Oracle-calibrated test"),
                Line2D([], [], color="0.2", ls="--", label="Nominal HAC test"),
                Line2D([], [], color="0.35", ls=":", label="Nominal level")]
    FIGURE_LAYOUTS[str(stem)] = place_legend_header(
        fig, axes, handles, ncol=4, hspace=0.5, wspace=0.36)
    path = FIG_DIR / stem
    path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(path.with_suffix(".pdf"), metadata={"Title": title, "Author": ""})
    fig.savefig(path.with_suffix(".png"), dpi=220)
    if combined_pdf is not None:
        combined_pdf.savefig(fig)
    if show:
        plt.show()
    plt.close(fig)


plot_experiment(AGG_STAT_SUMMARY, AGG_POWER_SUMMARY, "exp1", "Experiment 1: equal-weight model aggregate",
                show=CFG["show_figure"])
if CFG["save_appendix_figures"]:
    appendix_path = FIG_DIR / "appendix"
    appendix_path.mkdir(parents=True, exist_ok=True)
    with PdfPages(appendix_path / "exp1_by_model.pdf") as combined_pdf:
        for kind in CFG["models"]:
            plot_experiment(STAT_SUMMARY[STAT_SUMMARY["model"] == kind],
                            POWER_SUMMARY[POWER_SUMMARY["model"] == kind],
                            f"appendix/exp1_{kind}", f"Experiment 1: {kind}",
                            show=False, combined_pdf=combined_pdf)
log("Figure", "Saved one aggregate figure; specification details are retained for the appendix.")

# %% Cell 11: Metadata, archive, and download
README = f"""Experiment 1: LR, XGB, MLP, Local XAI, and Bootstrap

COMPUTATION SETTINGS
The configuration uses three run seeds, 1,000 bootstrap draws, all four rho values,
48 assets, 60 test months, and the specified inference simulation budgets.
It runs the main nonlinear DGP with 16 attribution integration draws,
256 LIME neighborhood samples, and a fidelity sampling budget of 120 rows.
Held-out fidelity integration remains at 128 draws.
The smaller attribution budgets can increase explanation approximation error.
The code saves bootstrap interval summaries while omitting raw bootstrap
draw tables. Per-seed metrics and inference draws remain available.
All three models use the same data panels, splits, features and preprocessing.
The training DGP, sample sizes, XAI definitions and computation budgets are preserved.
The inference response DGP and its explicitly recorded estimand are corrected.
Outputs include one aggregate four-panel figure, appendix detail tables, and a final ZIP archive.

MAIN OUTPUTS
tables/main.csv: equal-weight model means for all original metrics.
tables/appendix_main_by_model.csv: original model-specific summary columns.
The common-effect definition and each metric are preserved.
tables/main_ci.csv: seed SD and paired bootstrap confidence intervals.
tables/seed_boot.csv: metric intervals, including prefix fidelity, reconstruction,
nominal/calibrated size and coverage, and both power definitions.
tables/power_boot.csv: nominal and calibrated power intervals for all shared effects.
figures/exp1.pdf and exp1.png: one aggregate four-panel figure.
Model-specific figures are optional, disabled by default, and saved under figures/appendix/.
Raw and appendix tables retain model identifiers; main tables average models within each run seed.
The main Power column uses effect {display_effect:.2f}.
The figure's power panel uses rho {CFG['power_rho']:.2f}.
Every figure band is a {BS['level']:.0%} paired seed-bootstrap interval.
Raw per-case outputs, explanation panels, and fitted models are saved.

REPETITIONS
Independent run seeds: {CFG['seeds']}.
Bootstrap repetitions: {BS['reps']}.
Within each run and each DGP-rho case:
1. Generate a new feature panel and new noisy training returns.
2. Fit common preprocessing, then fit LR, XGB and MLP on identical observations.
3. Select XGB tree count and MLP epochs on validation; refit on pre-test data.
4. Estimate the common reference distribution and recompute four XAI per model.
5. Recompute subset deletion, prefix fidelity, reconstruction and conditioning.
6. Project a common original-input response and evaluate nominal/calibrated inference.
LR is OLS with an intercept; it is deterministic conditional on its training data.
It is refitted for every independently regenerated simulation run.
XGB uses row/column subsampling; MLP uses seeded initialization and Adam updates.
MLP architecture: {CFG['mlp_hidden']}; epoch candidates: {CFG['mlp_epochs']}.
MLP target scaling uses training y during selection and pre-test y at final refit.
All predictions and XAI values are returned to the original response units.
Within a seed, common feature innovations pair rho, DGP and model comparisons.
XAI integration streams, fidelity samples and inference errors are paired across models.
All four methods explain the same fitted predictor within each model case.
seed_map.csv records the stage-specific seeds for every simulation case.
Each stage uses reproducible independent streams derived from the run seed.
A fixed run seed provides reproducibility; separate run seeds provide repeats.
Seeds are predetermined and all planned runs enter the summaries.

SIMULATION BOOTSTRAP
The independent resampling unit is one complete seeded simulation run.
For each of {BS['reps']} draws, sample {len(CFG['seeds'])} run indices with replacement.
Apply the same sampled run indices to all models, methods, cases, and effect sizes.
Compute each model/method metric across sampled runs, retaining model groups.
Confidence limits are
empirical percentile order statistics. Seed SD is reported separately.
This paired seed bootstrap quantifies variability of aggregate diagnostics
across independently regenerated data, refitted models, and recomputed XAI.
The conditional test inside each run retains its explicitly defined target.
For Kappa, each run contributes its median monthly condition number.
The aggregate then averages these run-level medians.
An infinite condition number is recorded explicitly. Its confidence interval
can also have an infinite endpoint. The figure flags singular outcomes.
tables/seed_boot_draws.csv and tables/power_boot_draws.csv contain bootstrap
distributions when save_draws is enabled.
The number of run seeds controls the independent experiment count.
The bootstrap budget controls the numerical precision of resampling summaries.

DATA AND SPLITS
Simulation features have Gaussian equicorrelation rho and asset AR persistence.
The nonlinear DGP includes a sine, a square, and an interaction.
Each predictor is trained on the same noisy simulated returns. Validation selects
XGB tree count or MLP epoch count; LR has no tuned hyperparameter.
MLP uses partial_fit for full-dataset Adam epochs, with internal early stopping
and internal random validation holdouts disabled. Final fits use training + validation.
Scaling uses the training split. Reference fitting uses pre-test features.
All explanations use held-out test features, with the model frozen in that window.
Fidelity sampling covers every test month using a prespecified per-month cap.

METHODS
SHAP: conditional Shapley values with all 2^K coalitions. Coalition weights
are exact; conditional expectations use Monte Carlo integration under a
pre-test fitted Gaussian distribution with Ledoit-Wolf shrinkage.
LIME: the original continuous LimeTabularExplainer with local Gaussian
sampling around each instance, all K features, and a Ridge surrogate.
Contributions equal slopes times standardized feature values relative to
pre-test means. The local intercept is saved separately.
Ablation: f(x) minus f(x with feature j replaced by its pre-test mean).
The reference output is f(pre-test mean). Each feature is ablated separately.
COLA: successive conditional expectation increments in order X1 to XK.
The column for j measures its increment given all preceding features.
All models use the same Monte Carlo coalition algorithm and integration budgets,
including LR, so model expansion preserves the original XAI estimators.
SHAP and COLA share estimated coalition values within each model. Exact orthogonality concerns
exact expectations under one reference distribution. Finite integration,
estimated references, and monthly subsamples are evaluated empirically.
The feature order is fixed in advance.

FOUR MAIN METRICS
A: the original arbitrary-subset conditional deletion infidelity is retained.
For each proper nonempty retained set S, compare removed attribution sums to
f(x) - E[f(X) | X_S=x_S], using independent evaluation conditional draws.
Normalize squared error by mean squared conditional prediction change.
This task measures agreement with arbitrary-subset deletion. It does not define
all aspects of local explanation quality. A fixed-order increment can differ
from the deletion response for a non-prefix subset.
A separate prefix_infid uses the same fixed-order prefixes for every method.
The retained prefixes have lengths 0 through K-1; the empty prefix measures
full reconstruction relative to the saved baseline. Prefix evaluations use
independent conditional draws for nonempty proper prefixes. The baseline is
the common saved reference output, and the fully observed prediction is exact.
Both deletion tasks are saved in sim_fidelity.csv, sim_summary.csv, main.csv
and seed_boot.csv. Reconstruction NRMSE remains separate in sim_aux.csv and
is also summarized with paired seed-bootstrap intervals. These diagnostics
are reported together; the arbitrary-subset score has not been replaced.
B: monthly 2-norm condition number of centered, scaled explanation columns.
Rank-deficient and zero-variance designs have infinite condition numbers.
C: independent-evaluation Type I error for the common-response effect test.
Solid lines use a method/model-specific known-DGP null calibration. Dashed
lines show the original nominal Bartlett-HAC/Student-t procedure, with
{CFG['hac_lags']} lags. Both size definitions, Wilson intervals, Monte Carlo
standard errors, and nominal/calibrated coverage are exported. Overrejection
in the nominal diagnostic remains visible.
D: power uses the same calibrated test as C's solid curves. The effect is a
common original-input signal coefficient. The full table also retains nominal
HAC power. For each alternative, monthly projected slopes and their HAC
standard errors are recomputed; a constant shift of a fixed null t-statistic
would ignore month-varying projection loadings.
Calibration uses {CFG['cal_reps']} independent null errors; evaluation uses
{CFG['null_reps']} separate errors. Figure bands use the paired run-seed
bootstrap. A calibrated power curve at effect zero equals calibrated size.
Oracle calibration uses the known simulated error DGP and fixed observed
features. It provides a conditional benchmark, not a ready-to-use empirical
test or evidence of general inferential superiority. Monte Carlo integration
and calibration errors, and their variation across run seeds, remain visible.

CONDITIONAL INFERENCE ESTIMAND
Define U by within-month centering and scaling the common original input X.
All prediction models and explanation methods receive the same response:
y(delta) = h(X) + delta * g(X) + eps,
where g(X) = U_target, h(X) = {CFG['nuisance']} * sum(U_j, j != target),
and target = X{CFG['target'] + 1}. Underlying input panels, common valid
months and error realizations are shared across models and methods.
The regression still uses each method's monthly standardized explanation
matrix Z and all K columns jointly. Let W_t be the target coordinate's OLS
row, b_t = W_t h_t and l_t = W_t g_t. The coordinate is A{CFG['target'] + 1}.
Its exact finite-panel projection mean under the null is b_bar. Its average
response to the common source effect is l_bar. The reported common-effect
estimate is (mean(beta_hat_t) - b_bar) / l_bar, whose conditional expectation
is delta. Divide its HAC standard error by abs(l_bar). Monthly slopes are
b_t + delta*l_t + W_t*eps_t; b_t and l_t can vary with the month.
The exact projection truth and normalization use the known simulation DGP.
They are explicitly oracle quantities; empirical Fama-MacBeth results keep
their original explanation-coordinate estimands. Nonzero loadings identify
the common effect. Loadings with magnitude at most {CFG['effect_loading_tol']}
stop with a diagnostic; no target feature is changed after observing results.
The response equation and delta are common across methods. Coordinate null
truths and loadings differ and are exported in sim_inference.csv,
sim_power.csv, sim_validity.csv and sim_sample.csv. Bias and RMSE use the
common delta units. Raw coordinate estimates and standard errors remain in
sim_draws.csv. Calibration and evaluation errors are independent and paired
across all methods/models, with heteroskedasticity, asset serial correlation
and a common serially correlated factor. The nonlinear return-prediction DGP
and its fitted models are separate from this controlled inference response.
One identical null-response realization is saved for each method/model case,
including source-row identifiers, the common signal, nuisance mean, errors,
and monthly projection truths. Inference uses at least {CFG['min_months']}
consecutive months that are full rank for every method and model.
These diagnostics condition on the fitted explanation panels. Independent run
seeds also regenerate data, refit models and recompute explanations, providing
variation across those complete learning pipelines. Calibration quantifies a
specified conditional test; it does not turn low collinearity into a guarantee
of high power or establish unconditional generated-regressor inference.

EMPIRICAL RUNS
Empirical status: {REAL_STATUS['status']}.
Empirical bootstrap status: {REAL_BOOT_STATUS['status']}.
Supply a CSV/Parquet panel with id, date, y, and numeric features.
date is the information month; y is the already aligned next-month excess return.
Release lags, delistings, and return alignment belong in shared data preparation.
Input may be a local file, configured public URL, or Colab upload.
Use the same canonical panel and chronological split in all three experiments.
Original CPZ sources:
https://mpelger.people.stanford.edu/data-and-code
https://drive.google.com/drive/folders/1TrYzMUA_xLID5-gXOy_as8sH2ahLwz-l
https://github.com/LouisChen1992/Deep_Learning_Asset_Pricing

The empirical panel, feature subset, sample caps, imputation, quantile mapping,
and split boundaries are fixed across models and seeds. Each seed fits LR,
XGB and MLP, then recomputes every XAI method. LR predictions on this fixed
empirical panel are identical across seeds; Monte Carlo XAI estimates can vary. The benchmark uses up to {REAL['max_features']} features in
schema order, with training-only eligibility, for feasible exact coalition
enumeration. The predictor and all XAI methods use that same feature subset.
The Gaussian conditional reference is a working approximation.
Per-seed feature maps, splits, models, explanations, diagnostics, and monthly
Fama-MacBeth coefficients are saved under real_<MODEL>_s<seed> names.
tables/real_summary.csv reports empirical metric means and seed SD.
tables/real_per_seed.csv retains the individual runs.

EMPIRICAL STATIONARY BOOTSTRAP
The time-resampling unit is a whole month, retaining the joint cross-section.
Politis-Romano stationary bootstrap indices continue to the next month with
probability 1 - 1/L, or restart at a uniformly sampled month with probability
1/L. Circular wrap-around preserves sample length.
The same month index draws apply jointly to every prediction model, seed,
XAI method, and feature. Shared observed data remain paired across all seeds.
Subset and prefix fidelity are each recomputed as a ratio of resampled monthly
error and reference sums. Kappa is recomputed as a median of resampled monthly condition numbers.
Metrics are averaged across seeds within each prediction model, retaining model groups.
For Fama-MacBeth, monthly coefficients are first averaged across seeds within each model,
then the resulting joint time series is block-resampled.
The result targets the mean coefficient across the seed fits of that prediction model.
Full-rank, shared, consecutive calendar spans and their lengths are recorded.
At least {BS['min_months']} shared months are required for reported intervals.
B = {BS['reps']}; interval = empirical percentile, level = {BS['level']:.0%}.
The mean block length is configured by BS['block']; with None, the working
rule is max(2, round(T**(1/3))), capped at T. The actual length is saved.
This is a transparent starting rule for dependent data. Block-length
sensitivity belongs in the final robustness analysis.
Monthly resampling conditions on fitted predictors, reference estimates, and
explanation panels. Three seed fits and the conditional month-bootstrap intervals
are recorded separately. Full refitting for every bootstrap resample would
define a separate unconditional inferential procedure.
tables/real_boot.csv and tables/real_fmb_boot.csv contain bootstrap intervals;
their draws and completion status are also saved.

PLOTTING AND ARCHIVE
SciencePlots: science + no-latex.
TUEplots: icml2024_full, two rows and two columns, height ratio 0.78.
The preset panel canvas is preserved; a measured legend header expands the final figure height.
config.json records settings; packages.json records package versions.
events.csv records progress; manifest.csv records file hashes.
The final ZIP contains CSV tables, separate model PDFs, a combined PDF, models,
preprocessing and metadata. Each model.joblib saves a dictionary of standard
estimators, preprocessing and target scaling, avoiding custom-class pickle dependencies.
To predict raw features, apply imputer (if present), then preprocessor, then use
prediction = target_mean + target_scale * estimator.predict(transformed_X).
XGB also has a native model.json; MLP target inverse-scaling is included in joblib.
This revision retains LR, XGB and MLP and the original eleven-cell layout.
It changes diagnostics, the shared inference response, its common-effect
normalization, and the visibility of calibrated versus nominal inference.
COLA, feature order, model training and Experiments 2 and 3 are unchanged.
This source has been supplied without execution or validation.
Run this source in the target Colab environment to produce the research results.

METHOD AND REPORTING REFERENCES
Gu, Kelly, Xiu (2020): https://doi.org/10.1093/rfs/hhaa009
Politis, Romano (1994): https://doi.org/10.1080/01621459.1994.10476870
DiCiccio, Efron (1996): https://doi.org/10.1214/ss/1032280214
Morris, White, Crowther (2019): https://doi.org/10.1002/sim.8086
The three-seed and 1,000-bootstrap budgets are explicit free-Colab computation choices.
The code uses percentile intervals; DiCiccio-Efron discusses several interval
procedures and finite bootstrap simulation budgets.
https://arxiv.org/abs/1903.10464
https://lime-ml.readthedocs.io/en/latest/lime.html
https://captum.ai/api/feature_ablation.html
https://arxiv.org/abs/1901.09392
https://tueplots.readthedocs.io/en/latest/
https://github.com/garrettj403/SciencePlots
"""
(OUT_DIR / "README.txt").write_text(README, encoding="utf-8")

ADDITIONAL_EXPERIMENTAL_DESIGN = f"""Additional Experimental Design

Computation profile: free Google Colab CPU.
Independent run seeds: {CFG['seeds']}.
Seed-bootstrap repetitions: {BS['reps']}.
Models: {', '.join(CFG['models'])}.
MLP epoch candidates: {CFG['mlp_epochs']}.
All original data dimensions, rho cases, XAI definitions and feature order are retained.
Conditional integration draws: {CFG['ce_draws']}; evaluation draws: {CFG['eval_draws']}.
LIME neighborhood samples: {CFG['lime_samples']}.
The number of independent simulation panels is the run-seed count. Models are
fixed specifications, not additional independent simulation replications.
Three run seeds provide limited between-run uncertainty resolution; the exact
budget is part of the reported experimental design.

Main results average model-specific diagnostics with equal weights inside each
run seed. The same resampled seed indices are then applied to these aggregate
run summaries. Model and bootstrap-interval endpoints are never treated as
independent samples or averaged to construct confidence intervals.
Infidelity and condition numbers are macro averages of the corresponding
specification statistics. Infinite condition numbers remain infinite.
Nominal and oracle-calibrated test sizes remain separate.

Main figure: figures/exp1.pdf and figures/exp1.png, one page.
Main tables: tables/main.csv, main_ci.csv, aggregate_per_seed.csv,
aggregate_seed_boot.csv, aggregate_power_boot.csv and prediction.csv.
Appendix tables: appendix_main_by_model.csv, appendix_main_ci_by_model.csv,
appendix_prediction_by_model.csv, seed_boot.csv, power_boot.csv and sim_*.csv.
Optional appendix figures are disabled by default and never displayed inline.
Every figure has one centered legend above its panels. Numerical labels,
unsupported-status labels and explanatory annotations are recorded in tables.
Figure layout: automatic layout engines are disabled. Legend dimensions are measured
with the active font renderer; a separate header expands the canvas while preserving
the physical panel area. figure_layouts records the final exported dimensions.
Source delivery: experiment training and inference are not executed during editing.
"""
(OUT_DIR / "additional_experimental_design.txt").write_text(ADDITIONAL_EXPERIMENTAL_DESIGN, encoding="utf-8")

metadata = {"simulation": CFG, "bootstrap": BS, "empirical": REAL,
            "models": CFG["models"], "model_codes": MODEL_CODES,
            "inference_response": "Shared original-input nuisance mean plus delta*signal plus error",
            "inference_target": "Common source effect using known finite-panel projection truth",
            "calibration_scope": "Known-DGP oracle benchmark; nominal HAC retained",
            "fidelity_tasks": ["Arbitrary-subset deletion", "Fixed-prefix deletion",
                               "Full prediction reconstruction"],
            "source_status": "Supplied without execution or validation",
            "figure_pages": 1, "figure_layouts": FIGURE_LAYOUTS, "appendix_figures": CFG["save_appendix_figures"],
            "aggregation": CFG["aggregate_weighting"],
            "figure_inches": FIGURE_LAYOUTS["exp1"]["figure_inches"],
            "empirical_status": REAL_STATUS, "empirical_bootstrap": REAL_BOOT_STATUS,
            "python": platform.python_version(), "created_utc": STAMP}
(OUT_DIR / "config.json").write_text(json.dumps(metadata, indent=2, default=str),
                                      encoding="utf-8")
package_names = ["numpy", "pandas", "scipy", "scikit-learn", "xgboost", "lime",
                 "matplotlib", "SciencePlots", "tueplots", "pyarrow", "tqdm", "joblib"]
package_versions = {}
for name in package_names:
    try:
        package_versions[name] = importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        package_versions[name] = "Unavailable"
(OUT_DIR / "packages.json").write_text(json.dumps(package_versions, indent=2),
                                        encoding="utf-8")
log("Export", "Saving model-specific tables, PDF figures, metadata, and progress log.")
save_csv(pd.DataFrame(EVENTS), "events")
manifest_rows = []
for path in sorted(OUT_DIR.rglob("*")):
    if path.is_file():
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        manifest_rows.append({"File": str(path.relative_to(OUT_DIR)),
                              "Bytes": path.stat().st_size, "SHA256": digest.hexdigest()})
save_csv(pd.DataFrame(manifest_rows), "manifest")
zip_path = OUT_DIR.with_suffix(".zip")
with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED,
                     compresslevel=6) as archive:
    for path in sorted(OUT_DIR.rglob("*")):
        if path.is_file():
            archive.write(path, arcname=str(path.relative_to(OUT_DIR)))
print(f"\nComplete: {zip_path.name}")
print(f"Archive: {zip_path.stat().st_size / 1024 ** 2:.2f} MB")
print(f"Models: {', '.join(CFG['models'])}; seeds: {len(CFG['seeds'])}; bootstrap: {BS['reps']}")
print(f"Empirical status: {REAL_STATUS['status']}")
print(f"Empirical bootstrap: {REAL_BOOT_STATUS['status']}")
display(FileLink(str(zip_path)))
if CFG["auto_download"]:
    try:
        from google.colab import files
        files.download(str(zip_path))
    except ImportError:
        print("Use the archive link above to download the results.")
    except Exception as exc:
        print(f"Automatic download: {exc}")
        print("Use the archive link above to download the results.")

"""# Exp 2"""

# -*- coding: utf-8 -*-
"""Experiment 2: Financial Signals and Future Returns — French 100 portfolios.

Copy the ENTIRE contents into ONE Google Colab code cell and run it.
The section order follows Experiment 1. All comments, labels and output are English.

Benchmark: French 100 Size-Book-to-Market portfolios, monthly value-weighted returns.
Auxiliary RF from the same French library defines next-month excess returns.
Inputs: Ret1, Mom3, Mom12_2, Vol12, DownVol12, Skew12, built from past returns only.
Use every available portfolio, with no random portfolio subsampling.
Training begins in 1967; out-of-sample return months are 1992–2016.
Models: LR (OLS), XGBoost and MLP; all use the same data and chronological splits.
Use annual expanding refits, three seeds, 16 conditional draws and 2,000 bootstrap draws.
Each model retains its own COLA panel and analyses; the main figure averages the model statistics.
The four panels remain FM, quantiles, sorts and High-minus-Low volatility effects.
"""

