def log(stage, message):
    row = {"time": datetime.now(timezone.utc).isoformat(), "stage": stage, "message": str(message)}
    EVENTS.append(row)
    print(f"[{stage}] {message}", flush=True)

def file_hash(path):
    value = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(8 * 1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()

def fingerprint(payload):
    return hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode()).hexdigest()

def write_json(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".partial")
    temporary.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
    temporary.replace(path)

def save_csv(frame, name, show=False):
    target = TABLE_DIR / f"{name}.csv"
    temporary = target.with_suffix(".csv.partial")
    frame.to_csv(temporary, index=False)
    temporary.replace(target)
    if show:
        print(f"\n{name}", flush=True)
        display(frame.round(5))

def save_npz(path, **arrays):
    path = Path(path)
    temporary = path.with_suffix(path.suffix + ".partial")
    with temporary.open("wb") as stream:
        np.savez_compressed(stream, **arrays)
    temporary.replace(path)

def seed_for(run_seed, *stages):
    return int(np.random.SeedSequence([int(run_seed), *map(int, stages)]).generate_state(1)[0])

def parse_month(series):
    if isinstance(series.dtype, pd.PeriodDtype):
        return series.astype("period[M]")
    text = series.astype(str).str.replace(r"\.0$", "", regex=True)
    if text.str.fullmatch(r"\d{6}").all():
        parsed = pd.to_datetime(text, format="%Y%m", errors="raise")
    elif text.str.fullmatch(r"\d{8}").all():
        parsed = pd.to_datetime(text, format="%Y%m%d", errors="raise")
    else:
        parsed = pd.to_datetime(text, errors="raise")
    return parsed.dt.to_period("M")

