# %% Cell 5: Predetermined market states
def market_states(market_path, initial_train_dates, months):
    source = pd.read_csv(market_path)
    proxy = pd.Series(source["market"].to_numpy(float), index=parse_month(source["return_date"]))
    if proxy.index.duplicated().any():
        raise ValueError("The French 100 market proxy has duplicate calendar months.")
    calendar = pd.period_range(proxy.index.min(), proxy.index.max(), freq="M")
    proxy = proxy.sort_index().reindex(calendar)
    # At row's realized-return month r, the state may use realized returns through r-1.
    vol = proxy.shift(1).rolling(CFG["vol_window"], min_periods=CFG["vol_min_history"]).std(ddof=1)
    train_vol = vol.reindex(initial_train_dates.unique()).dropna()
    if len(train_vol) < 60:
        raise ValueError("Initial training history is insufficient for a fixed state cutoff.")
    cut = float(train_vol.quantile(CFG["vol_cut_quantile"]))
    state = np.where(vol.isna(), np.nan, (vol > cut).astype(float))
    table = pd.DataFrame({"return_date": calendar.astype(str), "date": (calendar - 1).astype(str),
                          "vol": vol.to_numpy(), "state": state, "cut": cut})
    save_csv(source, "market_proxy")
    save_csv(table, "states")
    states = table.set_index("return_date").reindex(months)["state"].to_numpy(float)
    log("State", f"Fixed initial-training cutoff={cut:.6f}; High={np.sum(states == 1)}, Low={np.sum(states == 0)} months.")
    return states, cut

states, cutoff = market_states(market_path, return_dates[train0], months)

# %% Cell 6: Predictors, initial selection, and ordered local explanations
def fit_preprocessor(x, seed):
    # Empty columns in later expanding windows indicate a source/schema error.
    if np.any(np.isfinite(x).sum(axis=0) == 0):
        raise ValueError("An included characteristic is entirely missing in a fitting window.")
    imputer = SimpleImputer(strategy="median")
    filled = imputer.fit_transform(x)
    if DATA["gaussianize"]:
        transform = QuantileTransformer(n_quantiles=min(1000, len(x)),
            output_distribution="normal", subsample=min(DATA["quantile_subsample"], len(x)),
            random_state=seed)
    else:
        transform = StandardScaler()
    transformed = np.asarray(transform.fit_transform(filled), dtype=np.float32)
    return (imputer, transform), transformed

def transform_x(preprocessor, x):
    imputer, transform = preprocessor
    return np.asarray(transform.transform(imputer.transform(x)), dtype=np.float32)

class ReturnPredictor:
    """A common prediction API returning original monthly excess-return units."""

    def __init__(self, estimator, kind, target_mean=0.0, target_scale=1.0):
        self.estimator, self.kind = estimator, kind
        self.target_mean, self.target_scale = target_mean, target_scale

    def predict(self, x):
        x = np.ascontiguousarray(x, dtype=np.float32)
        if self.kind == "XGB":
            pred = self.estimator.get_booster().inplace_predict(x, validate_features=False)
        else:
            pred = self.estimator.predict(x)
        return self.target_mean + self.target_scale * np.asarray(pred, dtype=np.float64)

    def checkpoint(self):
        # Standard sklearn/XGB estimators remain loadable without this wrapper class.
        return {"estimator": self.estimator, "kind": self.kind,
                "target_mean": self.target_mean, "target_scale": self.target_scale}


def make_model(kind, parameter, seed, n_rows):
    if kind == "LR":
        return LinearRegression(fit_intercept=True)
    if kind == "XGB":
        return XGBRegressor(n_estimators=int(parameter), max_depth=CFG["depth"],
            learning_rate=CFG["learning_rate"], objective="reg:squarederror", tree_method="hist",
            device=CFG["device"], subsample=CFG["subsample"], colsample_bytree=CFG["colsample"],
            reg_lambda=1.0, random_state=seed, n_jobs=CFG["n_jobs"])
    if kind == "MLP":
        return MLPRegressor(hidden_layer_sizes=tuple(CFG["mlp_hidden"]), activation="relu",
            solver="adam", alpha=CFG["mlp_alpha"], learning_rate_init=CFG["mlp_learning_rate"],
            batch_size=min(int(CFG["mlp_batch_size"]), int(n_rows)), max_iter=1,
            early_stopping=False, shuffle=True, random_state=seed)
    raise ValueError(f"Unknown prediction model: {kind}")


def fit_with_parameter(kind, x, y, parameter, seed):
    y = np.asarray(y, dtype=np.float64)
    estimator = make_model(kind, parameter, seed, len(y))
    if kind == "MLP":
        location, scale = float(y.mean()), max(float(y.std()), 1e-12)
        scaled_y = (y - location) / scale
        for _ in range(int(parameter)):
            estimator.partial_fit(x, scaled_y)
        return ReturnPredictor(estimator, kind, location, scale)
    estimator.fit(x, y)
    return ReturnPredictor(estimator, kind)


def fit_candidate(xt, yt, xv, yv, run_seed, year, kind):
    """Validation selects trees/epochs; MLP target scaling uses training y only."""
    seed = seed_for(run_seed, 704, year, MODEL_CODES[kind])
    rows = []
    if kind == "MLP":
        epochs = sorted(set(int(value) for value in CFG["mlp_epochs"]))
        if not epochs or epochs[0] < 1:
            raise ValueError("MLP epoch candidates must be positive integers.")
        location, scale = float(np.mean(yt)), max(float(np.std(yt)), 1e-12)
        model = make_model(kind, epochs[-1], seed, len(yt))
        scaled_y = (yt - location) / scale
        for epoch in range(1, epochs[-1] + 1):
            model.partial_fit(xt, scaled_y)
            if epoch in epochs:
                prediction = location + scale * model.predict(xv)
                rows.append({"model": kind, "seed": run_seed, "year": year,
                             "parameter": "epochs", "value": epoch,
                             "valid_mse": float(mean_squared_error(yv, prediction))})
    else:
        candidates = [0] if kind == "LR" else CFG["trees"]
        for parameter in candidates:
            model = fit_with_parameter(kind, xt, yt, parameter, seed)
            rows.append({"model": kind, "seed": run_seed, "year": year,
                         "parameter": "none" if kind == "LR" else "trees",
                         "value": int(parameter),
                         "valid_mse": float(mean_squared_error(yv, model.predict(xv)))})
    best = min(range(len(rows)), key=lambda i: rows[i]["valid_mse"])
    for i, row in enumerate(rows):
        row["selected"] = i == best
    return rows[best]["value"], rows

class GaussianCOLA:
    """Same ordered conditional increments; cache each prefix factorization."""

    def __init__(self, x_ref, model, seed):
        fit = LedoitWolf().fit(x_ref)
        self.mean, self.cov = np.asarray(fit.location_, float), np.asarray(fit.covariance_, float)
        self.model, self.k = model, x_ref.shape[1]
        rng = np.random.default_rng(seed)
        background = np.asarray(rng.multivariate_normal(self.mean, self.cov, CFG["base_draws"]), np.float32)
        self.base = float(np.mean(self.predict(background), dtype=np.float64))
        self.prefixes = []
        for size in range(1, self.k):
            cross = self.cov[:size, size:]
            gain = np.linalg.solve(self.cov[:size, :size], cross)
            covariance = self.cov[size:, size:] - cross.T @ gain
            values, vectors = np.linalg.eigh((covariance + covariance.T) / 2)
            root = vectors @ np.diag(np.sqrt(np.maximum(values, 0)))
            self.prefixes.append((size, gain, root))

    def predict(self, x):
        return np.asarray(self.model.predict(x), dtype=np.float64)

    def explain(self, x, seed):
        rng = np.random.default_rng(seed)
        attr = np.empty((len(x), self.k), dtype=np.float64)
        previous = np.full(len(x), self.base)
        draws_n = int(CFG["ce_draws"])
        if draws_n < 2 or draws_n % 2:
            raise ValueError("ce_draws must be an even integer >= 2 for antithetic integration.")
        for size, gain, root in self.prefixes:
            z = rng.standard_normal((draws_n // 2, self.k - size))
            z = np.concatenate([z, -z], axis=0) @ root.T
            current = np.empty(len(x), dtype=np.float64)
            for start in range(0, len(x), CFG["ce_batch"]):
                stop = min(start + CFG["ce_batch"], len(x))
                xb = x[start:stop]
                center = self.mean[size:] + (xb[:, :size] - self.mean[:size]) @ gain
                filled = np.broadcast_to(xb[:, None, :], (len(xb), draws_n, self.k)).copy()
                filled[:, :, size:] = center[:, None, :] + z[None, :, :]
                current[start:stop] = self.predict(filled.reshape(-1, self.k)).reshape(len(xb), draws_n).mean(axis=1)
            attr[:, size - 1] = current - previous
            previous = current
        pred = self.predict(x)
        attr[:, -1] = pred - previous
        return attr, pred

def validation_sample(return_dates, valid_index):
    """Stratify the plotting-rank sample across initial validation months."""
    rng = np.random.default_rng(seed_for(CFG["seed"], 711))
    dates = return_dates[valid_index]
    months = dates.unique().sort_values()
    budget = min(int(CFG["importance_rows"]), len(valid_index))
    per_month, remainder = divmod(budget, len(months))
    picked = []
    for position, month in enumerate(months):
        eligible = valid_index[np.asarray(dates == month)]
        n = min(len(eligible), per_month + int(position < remainder))
        picked.extend(rng.choice(eligible, n, replace=False).tolist())
    return np.sort(picked)

def freeze_plot_selection(x, y, return_dates, first_year):
    """Choose shared display features using normalized validation importance across models."""
    target = CHECK_DIR / "selection.json"
    if target.is_file():
        record = json.loads(target.read_text(encoding="utf-8"))
        return record["indices"], record["rows"]
    train, valid, _, _ = annual_indices(return_dates, first_year)
    chosen = validation_sample(return_dates, valid)
    prep, xt = fit_preprocessor(x[train], seed_for(CFG["seed"], 703, first_year))
    xv, xs = transform_x(prep, x[valid]), transform_x(prep, x[chosen])
    rows = []
    for kind in CFG["models"]:
        for run_seed in tqdm(CFG["seeds"], desc=f"Initial validation selection: {kind}"):
            checkpoint = CHECK_DIR / f"selection_{kind}_s{run_seed}.json"
            if checkpoint.is_file():
                rows.extend(json.loads(checkpoint.read_text(encoding="utf-8"))["rows"])
                continue
            parameter, fit_rows = fit_candidate(xt, y[train], xv, y[valid], run_seed, first_year, kind)
            model = fit_with_parameter(kind, xt, y[train], parameter,
                                      seed_for(run_seed, 704, first_year, MODEL_CODES[kind]))
            reference = GaussianCOLA(xt, model, seed_for(run_seed, 710, first_year))
            attrs, _ = reference.explain(xs, seed_for(run_seed, 712, first_year))
            values = np.mean(np.abs(attrs), axis=0)
            relative = values / max(float(values.sum()), 1e-16)
            seed_rows = [{"model": kind, "seed": run_seed, "feature": f"X{j + 1}", "index": j,
                          "importance": float(value), "relative_importance": float(relative[j]),
                          "selection_rows": len(chosen)} for j, value in enumerate(values)]
            rows.extend(seed_rows)
            write_json(checkpoint, {"rows": seed_rows, "parameter": parameter, "fit": fit_rows})
            del model, reference, attrs
            gc.collect()
    rank = pd.DataFrame(rows).groupby("index")["relative_importance"].mean()
    ordered = sorted(rank.index.tolist(), key=lambda j: (-rank.loc[j], j))
    selected = list(map(int, ordered[:CFG["plot_features"]]))
    write_json(target, {"indices": selected, "rows": rows, "models": CFG["models"],
                        "rule": "Mean within-model normalized absolute COLA; equal model/seed weights",
                        "selection_end": str(return_dates[chosen].max()), "frozen_before_test": True})
    return selected, rows


def annual_fit(x, y, return_dates, year, run_seed, kind):
    directory = MODEL_DIR / kind
    directory.mkdir(parents=True, exist_ok=True)
    stem = directory / f"s{run_seed}_y{year}"
    model_path = stem.with_suffix(".model.joblib")
    prep_path = stem.with_suffix(".preprocessor.joblib")
    metadata_path = stem.with_suffix(".json")
    train, valid, pretest, target = annual_indices(return_dates, year)
    if all(p.is_file() for p in [model_path, prep_path, metadata_path]):
        payload = joblib.load(model_path)  # Only this run's own trusted checkpoints.
        model = ReturnPredictor(**payload)
        prep = joblib.load(prep_path)
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        return model, prep, pretest, target, metadata
    prep, xt = fit_preprocessor(x[train], seed_for(CFG["seed"], 703, year))
    xv = transform_x(prep, x[valid])
    parameter, fits = fit_candidate(xt, y[train], xv, y[valid], run_seed, year, kind)
    del xt, xv
    # Common preprocessing is refitted on pre-test features for every prediction model.
    prep, xp = fit_preprocessor(x[pretest], seed_for(CFG["seed"], 713, year))
    model = fit_with_parameter(kind, xp, y[pretest], parameter,
                               seed_for(run_seed, 704, year, MODEL_CODES[kind]))
    metadata = {"model": kind, "seed": run_seed, "year": year,
                "parameter": "none" if kind == "LR" else ("trees" if kind == "XGB" else "epochs"),
                "value": parameter, "fit": fits,
                "target_mean": model.target_mean, "target_scale": model.target_scale,
                "train_start": str(return_dates[train].min()), "train_end": str(return_dates[train].max()),
                "valid_start": str(return_dates[valid].min()), "valid_end": str(return_dates[valid].max()),
                "pretest_end": str(return_dates[pretest].max()), "test_start": str(return_dates[target].min()),
                "test_end": str(return_dates[target].max()), "n_train": len(train), "n_valid": len(valid),
                "n_pretest": len(pretest), "n_test": len(target)}
    temporary = model_path.with_suffix(".partial")
    joblib.dump(model.checkpoint(), temporary, compress=3)
    temporary.replace(model_path)
    if kind == "XGB":
        model.estimator.save_model(stem.with_suffix(".ubj"))
    temporary = prep_path.with_suffix(".partial")
    joblib.dump(prep, temporary, compress=3)
    temporary.replace(prep_path)
    write_json(metadata_path, metadata)
    del xp
    gc.collect()
    return model, prep, pretest, target, metadata


