# %% Cell 5: Frozen predictors and the controlled covariance intervention
class FrozenPredictor:
    def __init__(self, payload, kind, empirical=False):
        self.kind, self.empirical = kind, empirical
        self.estimator = payload["estimator"]
        self.location = float(payload.get("target_mean", 0.0))
        self.scale = float(payload.get("target_scale", 1.0))
        if kind == "XGB":
            self.estimator.set_params(n_jobs=CFG["n_jobs"])

    def predict(self, x):
        x = np.asarray(x, dtype=np.float32 if self.empirical else float)
        if self.kind == "XGB":
            value = self.estimator.get_booster().inplace_predict(np.ascontiguousarray(x), validate_features=False)
        else:
            value = self.estimator.predict(x)
        return self.location + self.scale * np.asarray(value, float)

    def affine_parameters(self):
        if self.kind != "LR":
            raise ValueError("Analytical affine parameters require an OLS predictor.")
        return np.asarray(self.estimator.coef_, float) * self.scale, self.location + self.scale * float(self.estimator.intercept_)


def psd_root(covariance):
    values, vectors = np.linalg.eigh((covariance + covariance.T) / 2)
    return vectors @ np.diag(np.sqrt(np.maximum(values, 0)))


def gaussian_geometry(mean, covariance):
    mean, covariance = np.asarray(mean, float), np.asarray(covariance, float)
    prefixes = []
    for size in range(1, len(mean)):
        cross = covariance[:size, size:]
        gain = np.linalg.solve(covariance[:size, :size], cross)
        conditional_covariance = covariance[size:, size:] - cross.T @ gain
        prefixes.append((size, gain, psd_root(conditional_covariance)))
    return {"mean": mean, "covariance": covariance, "prefixes": prefixes}


def reference_pair(x_reference):
    fitted = LedoitWolf().fit(x_reference)
    mean, covariance = fitted.location_.copy(), fitted.covariance_.copy()
    return {"Full": gaussian_geometry(mean, covariance),
            "Diagonal": gaussian_geometry(mean, np.diag(np.diag(covariance)))}


class OrderedGaussianCOLA:
    def __init__(self, geometry, predictor, base_draws, seed, analytical=False):
        self.geometry, self.predictor, self.analytical = geometry, predictor, analytical
        self.mean, self.k = geometry["mean"], len(geometry["mean"])
        if analytical:
            self.weight, self.intercept = predictor.affine_parameters()
            self.base = float(self.intercept + self.mean @ self.weight)
        else:
            rng = np.random.default_rng(seed)
            background = rng.multivariate_normal(self.mean, geometry["covariance"], int(base_draws))
            self.base = float(predictor.predict(background).mean())

    def values(self, x, draws, seed):
        x = np.asarray(x, dtype=np.float32 if self.predictor.empirical else float)
        if int(draws) < 2 or int(draws) % 2:
            raise ValueError("The antithetic conditional draw count must be even and at least two.")
        rng = np.random.default_rng(seed)
        values = np.empty((len(x), self.k + 1), float)
        values[:, 0], values[:, -1] = self.base, self.predictor.predict(x)
        for size, gain, root in self.geometry["prefixes"]:
            center = self.mean[size:] + (x[:, :size] - self.mean[:size]) @ gain
            if self.analytical:
                values[:, size] = self.intercept + x[:, :size] @ self.weight[:size] + center @ self.weight[size:]
                continue
            noise = rng.standard_normal((int(draws) // 2, self.k - size))
            noise = np.concatenate([noise, -noise], axis=0) @ root.T
            for start in range(0, len(x), CFG["prediction_batch"]):
                stop = min(start + CFG["prediction_batch"], len(x))
                filled = np.broadcast_to(x[start:stop, None, :], (stop - start, int(draws), self.k)).copy()
                filled[:, :, size:] = center[start:stop, None, :] + noise[None, :, :]
                values[start:stop, size] = self.predictor.predict(filled.reshape(-1, self.k)).reshape(stop - start, int(draws)).mean(axis=1)
        return values

    def explain(self, x, draws, seed):
        values = self.values(x, draws, seed)
        return np.diff(values, axis=1), values[:, -1]


def full_condition_number(attributions, intercept=False):
    attributions = np.asarray(attributions, float)
    if len(attributions) <= attributions.shape[1] or not np.isfinite(attributions).all():
        return np.inf
    scale = attributions.std(axis=0, ddof=0)
    if np.any(scale <= 1e-12):
        return np.inf
    design = (attributions - attributions.mean(axis=0)) / scale
    if intercept:
        design = np.column_stack([np.ones(len(design)), design])
    singular = np.linalg.svd(design, compute_uv=False)
    return float(singular[0] / singular[-1]) if singular[-1] > CFG["rank_tol"] * singular[0] else np.inf


def monthly_design(attributions):
    scales = attributions.std(axis=0, ddof=0)
    active = np.flatnonzero(scales > 1e-12)
    if len(attributions) < max(CFG["min_cross_section"], len(active) + 3) or not len(active):
        return None, active, "Insufficient cross-sectional variation"
    standardized = (attributions[:, active] - attributions[:, active].mean(axis=0)) / scales[active]
    design = np.column_stack([np.ones(len(standardized)), standardized])
    singular = np.linalg.svd(design, compute_uv=False)
    if singular[-1] <= CFG["rank_tol"] * singular[0]:
        return None, active, "Rank deficient"
    return design, active, "OK"


def quantile_fit(design, outcome, tau):
    scale = max(float(np.std(outcome)), 1e-4)
    fit = linprog(-outcome / scale, A_eq=sparse.csr_matrix(design.T),
                  b_eq=np.zeros(design.shape[1]), bounds=(tau - 1, tau), method="highs",
                  options={"presolve": True, "time_limit": CFG["qr_time_limit"],
                           "primal_feasibility_tolerance": 1e-8,
                           "dual_feasibility_tolerance": 1e-8})
    if not fit.success:
        return None, str(fit.message)
    beta = -np.asarray(fit.eqlin.marginals) * scale
    residual = outcome - design @ beta
    primal = float(np.maximum(tau * residual, (tau - 1) * residual).sum())
    dual = float(-fit.fun * scale)
    if not np.isfinite(beta).all() or abs(primal - dual) > 1e-5 * max(1.0, abs(primal), abs(dual)):
        return None, "Primal-dual objective gap"
    return beta, "OK"


def transform_inputs(preprocessor, x):
    imputer, transformer = preprocessor
    return np.asarray(transformer.transform(imputer.transform(x)), np.float32)


def save_joblib(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".partial")
    joblib.dump(payload, temporary, compress=3)
    temporary.replace(path)


def new_estimator(kind, parameter, seed, rows):
    if kind == "LR":
        return LinearRegression(fit_intercept=True)
    if kind == "XGB":
        return XGBRegressor(n_estimators=int(parameter), max_depth=CFG["depth"],
            learning_rate=CFG["learning_rate"], objective="reg:squarederror", tree_method="hist",
            device="cpu", subsample=CFG["subsample"], colsample_bytree=CFG["colsample"],
            reg_lambda=1.0, random_state=seed, n_jobs=CFG["n_jobs"])
    return MLPRegressor(hidden_layer_sizes=tuple(CFG["mlp_hidden"]), activation="relu",
        solver="adam", alpha=CFG["mlp_alpha"], learning_rate_init=CFG["mlp_learning_rate"],
        batch_size=min(CFG["mlp_batch_size"], rows), max_iter=1, shuffle=True,
        early_stopping=False, random_state=seed)


def fit_selected_payload(kind, x_train, y_train, x_valid, y_valid, x_pretest, y_pretest,
                         seed, empirical=False):
    """Run the main validation rule once, then freeze the selected predictor."""
    y_train, y_valid, y_pretest = [np.asarray(y, float) for y in [y_train, y_valid, y_pretest]]
    tuning = []
    if kind == "MLP":
        location, scale = float(y_train.mean()), max(float(y_train.std()), 1e-12)
        candidate = new_estimator(kind, None, seed, len(y_train))
        normalized_y = (y_train - location) / scale
        for epoch in range(1, max(CFG["mlp_epochs"]) + 1):
            candidate.partial_fit(x_train, normalized_y)
            if epoch in CFG["mlp_epochs"]:
                predicted = location + scale * candidate.predict(x_valid)
                tuning.append({"parameter": "epochs", "value": epoch,
                               "valid_mse": float(np.mean((y_valid - predicted) ** 2))})
    else:
        for parameter in ([0] if kind == "LR" else CFG["trees"]):
            candidate = new_estimator(kind, parameter, seed, len(y_train))
            candidate.fit(x_train, y_train)
            predicted = FrozenPredictor({"estimator": candidate}, kind, empirical).predict(x_valid)
            tuning.append({"parameter": "none" if kind == "LR" else "trees", "value": parameter,
                           "valid_mse": float(np.mean((y_valid - predicted) ** 2))})
    best = min(range(len(tuning)), key=lambda position: tuning[position]["valid_mse"])
    for position, row in enumerate(tuning):
        row["selected"] = position == best
    selected = tuning[best]["value"]
    estimator = new_estimator(kind, selected, seed, len(y_pretest))
    location, scale = 0.0, 1.0
    if kind == "MLP":
        location, scale = float(y_pretest.mean()), max(float(y_pretest.std()), 1e-12)
        normalized_y = (y_pretest - location) / scale
        for _ in range(int(selected)):
            estimator.partial_fit(x_pretest, normalized_y)
    else:
        estimator.fit(x_pretest, y_pretest)
    return {"estimator": estimator, "model": kind, "kind": kind,
            "target_mean": location, "target_scale": scale,
            "selected_parameter": selected, "tuning": tuning}


def simulation_scaler(raw, dates, rho, run_seed):
    if USE_MAIN1:
        for kind in CFG["models"]:
            member = f"tables/{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}/model.joblib"
            if MAIN1.has(member):
                return MAIN1.read_joblib(member)["preprocessor"]
    path = MODEL_CACHE_DIR / "synthetic" / f"rho{rho:.2f}_s{run_seed}.scaler.joblib"
    if path.is_file():
        return joblib.load(path)
    names = [f"X{j + 1}" for j in range(CFG["k"])]
    scaler = StandardScaler().fit(pd.DataFrame(raw[dates < CFG["train_months"]], columns=names))
    save_joblib(path, scaler)
    return scaler


def simulation_model(kind, rho, run_seed, case_id, transformed, response, dates, scaler):
    member = f"tables/{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}/model.joblib"
    if USE_MAIN1 and MAIN1.has(member):
        return MAIN1.read_joblib(member), member, "Reused main fitted model"
    path = MODEL_CACHE_DIR / "synthetic" / f"{kind}_rho{rho:.2f}_s{run_seed}.model.joblib"
    if path.is_file():
        return joblib.load(path), str(path), "Reused local fitted-model cache"
    tick = time.perf_counter()
    train = np.flatnonzero(dates < CFG["train_months"])
    valid = np.flatnonzero((dates >= CFG["train_months"])
                           & (dates < CFG["train_months"] + CFG["valid_months"]))
    pretest = np.r_[train, valid]
    payload = fit_selected_payload(kind, transformed[train], response[train], transformed[valid],
        response[valid], transformed[pretest], response[pretest],
        seed_for(run_seed, 200, case_id, MODEL_CODES[kind]))
    payload.update({"preprocessor": scaler, "features": [f"X{j + 1}" for j in range(CFG["k"])]})
    save_joblib(path, payload)
    log("Fit", f"Synthetic {kind}, rho={rho:.2f}, seed={run_seed}: {time.perf_counter() - tick:.1f}s; cached.")
    return payload, str(path), "Fitted main protocol once and cached"


def fit_empirical_preprocessor(x, seed):
    imputer = SimpleImputer(strategy="median")
    filled = imputer.fit_transform(x)
    transformer = QuantileTransformer(n_quantiles=min(1000, len(x)), output_distribution="normal",
        subsample=min(100000, len(x)), random_state=seed)
    transformer.fit(filled)
    return imputer, transformer


def empirical_fold(year, x_raw):
    pretest, test = annual_indices(year)
    anchor = pd.Period(f"{year}-01", freq="M")
    validation_start = anchor - CFG["validation_months"]
    cutoff = anchor - CFG["purge_months"]
    training_start = pd.Period(CFG["train_start"], freq="M")
    train = np.flatnonzero((FRENCH_DATES >= training_start) & (FRENCH_DATES < validation_start))
    valid = np.flatnonzero((FRENCH_DATES >= validation_start) & (FRENCH_DATES < cutoff))
    if not len(train) or not len(valid):
        raise ValueError(f"Training and validation observations are required for {year}.")
    stem = f"models/LR/s{CFG['seeds'][0]}_y{year}"
    reuse_main = False
    if USE_MAIN2 and MAIN2.has(stem + ".json") and MAIN2.has(stem + ".preprocessor.joblib"):
        metadata = MAIN2.read_json(stem + ".json")
        reuse_main = (int(metadata["n_pretest"]) == len(pretest)
                      and int(metadata["n_test"]) == len(test)
                      and metadata["pretest_end"] == str(FRENCH_DATES[pretest].max()))
    directory = MODEL_CACHE_DIR / "french" / str(year)
    final_path = directory / "final.preprocessor.joblib"
    if reuse_main:
        final = MAIN2.read_joblib(stem + ".preprocessor.joblib")
    elif final_path.is_file():
        final = joblib.load(final_path)
    else:
        final = fit_empirical_preprocessor(x_raw[pretest], seed_for(CFG["seed"], 713, year))
        save_joblib(final_path, final)
    return {"train": train, "valid": valid, "pretest": pretest, "test": test,
            "reuse_main": reuse_main, "final": final, "initial": None,
            "x_reference": transform_inputs(final, x_raw[pretest]),
            "x_test": transform_inputs(final, x_raw[test]), "directory": directory}


def empirical_model(kind, run_seed, year, x_raw, y, fold):
    member = f"models/{kind}/s{run_seed}_y{year}.model.joblib"
    if fold["reuse_main"] and MAIN2.has(member):
        return MAIN2.read_joblib(member), member, "Reused main fitted model"
    path = fold["directory"] / f"{kind}_s{run_seed}.model.joblib"
    if path.is_file():
        return joblib.load(path), str(path), "Reused local fitted-model cache"
    tick = time.perf_counter()
    if fold["initial"] is None:
        initial_path = fold["directory"] / "initial.preprocessor.joblib"
        if initial_path.is_file():
            fold["initial"] = joblib.load(initial_path)
        else:
            fold["initial"] = fit_empirical_preprocessor(x_raw[fold["train"]], seed_for(CFG["seed"], 703, year))
            save_joblib(initial_path, fold["initial"])
        fold["x_train"] = transform_inputs(fold["initial"], x_raw[fold["train"]])
        fold["x_valid"] = transform_inputs(fold["initial"], x_raw[fold["valid"]])
    payload = fit_selected_payload(kind, fold["x_train"], y[fold["train"]], fold["x_valid"],
        y[fold["valid"]], fold["x_reference"], y[fold["pretest"]],
        seed_for(run_seed, 704, year, MODEL_CODES[kind]), empirical=True)
    payload.update({"features": FEATURES, "year": int(year), "seed": int(run_seed),
                    "french_panel_signature": FRENCH_SIGNATURE})
    save_joblib(path, payload)
    log("Fit", f"French {kind}, seed={run_seed}, year={year}: {time.perf_counter() - tick:.1f}s; cached.")
    return payload, str(path), "Fitted main protocol once and cached"


# %% Cell 6: Synthetic conditional-reference ablation
def make_sim_panel(rho, run_seed):
    rng = np.random.default_rng(seed_for(run_seed, 100))
    nt = CFG["train_months"] + CFG["valid_months"] + CFG["test_months"]
    covariance = (1 - rho) * np.eye(CFG["k"]) + rho * np.ones((CFG["k"], CFG["k"]))
    innovations = rng.standard_normal((nt, CFG["n_assets"], CFG["k"])) @ np.linalg.cholesky(covariance).T
    x = np.empty_like(innovations)
    x[0] = innovations[0]
    for month in range(1, nt):
        x[month] = CFG["x_ar"] * x[month - 1] + np.sqrt(1 - CFG["x_ar"] ** 2) * innovations[month]
    flat = x.reshape(-1, CFG["k"])
    coefficient = np.array([0.7, -0.5, 0.35, 0.2, -0.15, 0.1])
    signal = flat @ coefficient + 0.45 * np.sin(flat[:, 0]) + 0.3 * (flat[:, 2] ** 2 - 1) + 0.35 * flat[:, 3] * flat[:, 4]
    response = signal + rng.standard_normal(len(flat)) * CFG["train_noise"] * (0.7 + 0.3 * np.abs(flat[:, 0]))
    dates = np.repeat(np.arange(nt), CFG["n_assets"])
    return flat, response, dates, covariance


def run_synthetic():
    metric_rows, condition_rows = [], []
    for run_seed in tqdm(CFG["seeds"], desc="Synthetic run seeds"):
        for case_id, rho in enumerate(CFG["rho"]):
            raw, response, dates, true_covariance = make_sim_panel(rho, run_seed)
            pretest_end = CFG["train_months"] + CFG["valid_months"]
            pretest_index = np.flatnonzero(dates < pretest_end)
            test_index = np.flatnonzero(dates >= pretest_end)
            scaler = simulation_scaler(raw, dates, rho, run_seed)
            names = [f"X{j + 1}" for j in range(CFG["k"])]
            transformed = scaler.transform(pd.DataFrame(raw, columns=names))
            x_reference, x_test = transformed[pretest_index], transformed[test_index]
            test_dates, test_response = dates[test_index], response[test_index]
            geometries = reference_pair(x_reference)
            true_mean = -np.asarray(scaler.mean_) / np.asarray(scaler.scale_)
            true_scaled_covariance = true_covariance / np.outer(scaler.scale_, scaler.scale_)
            true_geometry = gaussian_geometry(true_mean, true_scaled_covariance)
            rng = np.random.default_rng(seed_for(run_seed, 400, case_id))
            unique_months = np.unique(test_dates)
            per_month = max(1, CFG["fidelity_rows"] // len(unique_months))
            selected = np.sort(np.concatenate([
                rng.choice(np.flatnonzero(test_dates == month),
                           min(per_month, int(np.sum(test_dates == month))), replace=False)
                for month in unique_months
            ]))
            for kind in CFG["models"]:
                tag = f"{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}"
                path = CHECK_DIR / "synthetic" / f"{tag}.npz"
                source_member = f"tables/{tag}/model.joblib"
                if path.is_file():
                    with np.load(path, allow_pickle=False) as saved:
                        rows = json.loads(str(saved["metrics"]))
                        condition = saved["condition"]
                    source_member, fit_action = str(path), "Resumed saved ablation calculation"
                    log("Resume", f"Synthetic {tag}")
                else:
                    tick = time.perf_counter()
                    payload, source_member, fit_action = simulation_model(
                        kind, rho, run_seed, case_id, transformed, response, dates, scaler)
                    predictor = FrozenPredictor(payload, kind)
                    # Both variants are evaluated against the SAME true DGP distribution.
                    # OLS evaluation is analytical; nonlinear evaluation uses independent draws.
                    oracle = OrderedGaussianCOLA(true_geometry, predictor, CFG["oracle_base_draws"],
                        seed_for(run_seed, 940, case_id), analytical=kind == "LR")
                    oracle_values = oracle.values(x_test[selected], CFG["oracle_ce_draws"],
                                                  seed_for(run_seed, 941, case_id))
                    prediction = predictor.predict(x_test)
                    target_delta = prediction[selected, None] - oracle_values[:, :-1]
                    denominator = float(np.mean(np.square(target_delta)))
                    if denominator <= 1e-16:
                        raise ValueError(f"Insufficient prediction variation for {tag} fidelity evaluation.")
                    condition = np.empty((len(REFERENCES), len(unique_months)))
                    attributes, baselines, rows = [], [], []
                    for ri, reference_name in enumerate(REFERENCES):
                        explainer = OrderedGaussianCOLA(geometries[reference_name], predictor,
                            CFG["simulation_base_draws"], seed_for(run_seed, 300, case_id))
                        attr, reconstructed_prediction = explainer.explain(x_test, CFG["ce_draws"],
                            seed_for(run_seed, 942, case_id))
                        suffix = np.cumsum(attr[selected, ::-1], axis=1)[:, ::-1]
                        error = suffix - target_delta
                        for mi, month in enumerate(unique_months):
                            condition[ri, mi] = full_condition_number(attr[test_dates == month])
                        residual = prediction - explainer.base - attr.sum(axis=1)
                        scales = attr.reshape(CFG["test_months"], CFG["n_assets"], CFG["k"]).std(axis=1)
                        rows.append({"model": kind, "seed": run_seed, "rho": rho,
                            "reference": reference_name, "median_condition": float(np.median(condition[ri])),
                            "prefix_infid": float(np.mean(np.square(error)) / denominator),
                            "prefix_rmse": float(np.sqrt(np.mean(np.square(error)))),
                            "reconstruction_nrmse": float(np.sqrt(np.mean(residual ** 2)) / max(float(np.std(prediction)), 1e-12)),
                            "prediction_mse": float(np.mean((test_response - prediction) ** 2)),
                            "constant_months": int(np.any(scales <= 1e-12, axis=1).sum()),
                            "infinite_condition_months": int(np.isinf(condition[ri]).sum()),
                            "months": len(unique_months), "rows": len(x_test),
                            "fidelity_rows": len(selected), "ce_draws": CFG["ce_draws"],
                            "evaluation_draws": 0 if kind == "LR" else CFG["oracle_ce_draws"],
                            "evaluation_reference": "Known DGP Gaussian in training-standardized coordinates"})
                        attributes.append(attr)
                        baselines.append(explainer.base)
                    save_npz(path, metrics=np.array(json.dumps(rows)), condition=condition,
                             attribution=np.stack(attributes), prediction=prediction,
                             baseline=np.asarray(baselines), row_index=test_index,
                             test_date=test_dates, selected_rows=selected, oracle_values=oracle_values)
                    log("Synthetic", f"{tag}: two references, {len(x_test):,} rows; {time.perf_counter() - tick:.1f}s")
                    del predictor, oracle, explainer, attributes
                MODEL_ROWS.append({"scope": "Synthetic", "model": kind, "seed": run_seed,
                                   "rho": rho, "source": source_member, "action": fit_action})
                metric_rows.extend(rows)
                for ri, reference_name in enumerate(REFERENCES):
                    for mi, month in enumerate(unique_months):
                        condition_rows.append({"model": kind, "seed": run_seed, "rho": rho,
                            "reference": reference_name, "test_month": int(month - pretest_end),
                            "condition": float(condition[ri, mi])})
            gc.collect()
    return pd.DataFrame(metric_rows), pd.DataFrame(condition_rows)


with threadpool_limits(limits=CFG["n_jobs"]):
    SIM_METRICS, SIM_CONDITION = run_synthetic()
save_csv(SIM_METRICS, "simulation_per_model_seed")
save_csv(SIM_CONDITION, "simulation_monthly_conditioning")

# %% Cell 7: French 100 ablation with the same frozen annual models
def annual_indices(year):
    anchor = pd.Period(f"{year}-01", freq="M")
    valid_start = anchor - CFG["validation_months"]
    cutoff = anchor - CFG["purge_months"]
    history_start = pd.Period(CFG["train_start"], freq="M")
    pretest = np.flatnonzero((FRENCH_DATES >= history_start) & (FRENCH_DATES < cutoff))
    test = np.flatnonzero((FRENCH_DATES >= anchor) & (FRENCH_DATES <= anchor + 11)
                          & (FRENCH_DATES >= TEST_MONTHS[0]) & (FRENCH_DATES <= TEST_MONTHS[-1]))
    if not len(pretest) or not len(test):
        raise ValueError(f"Empty French chronological split for {year}.")
    return pretest, test


def run_french():
    model_count, seed_count, month_count, k = len(CFG["models"]), len(CFG["seeds"]), len(TEST_MONTHS), len(FEATURES)
    fm = {r: np.full((model_count, seed_count, month_count, k), np.nan) for r in REFERENCES}
    qr = {r: np.full((model_count, seed_count, month_count, len(CFG["quantiles"]), k), np.nan) for r in REFERENCES}
    conditions = {r: np.full((model_count, seed_count, month_count), np.inf) for r in REFERENCES}
    diagnostic_rows, split_rows, reconstruction_rows = [], [], []
    x_raw, y = FRENCH[FEATURES].to_numpy(np.float32), FRENCH["y"].to_numpy(float)
    calendar_map = {str(month): i for i, month in enumerate(TEST_MONTHS)}
    for year in tqdm(sorted(set(TEST_MONTHS.year)), desc="French annual vintages"):
        fold = empirical_fold(year, x_raw)
        pretest_index, test_index = fold["pretest"], fold["test"]
        x_reference, x_test = fold["x_reference"], fold["x_test"]
        geometries = reference_pair(x_reference)
        year_months = [month for month in TEST_MONTHS if month.year == year]
        target_dates = FRENCH_DATES[test_index]
        month_rows = [np.flatnonzero(target_dates == month) for month in year_months]
        global_months = [calendar_map[str(month)] for month in year_months]
        split_rows.append({"year": year, "pretest_start": str(FRENCH_DATES[pretest_index].min()),
                           "pretest_end": str(FRENCH_DATES[pretest_index].max()),
                           "pretest_rows": len(pretest_index), "test_rows": len(test_index),
                           "test_start": str(year_months[0]), "test_end": str(year_months[-1])})
        for mi, kind in enumerate(CFG["models"]):
            for si, run_seed in enumerate(CFG["seeds"]):
                tag = f"{kind}_s{run_seed}_y{year}"
                path = CHECK_DIR / "french" / f"{tag}.npz"
                member = f"models/{kind}/s{run_seed}_y{year}.model.joblib"
                if path.is_file():
                    with np.load(path, allow_pickle=False) as saved:
                        if not np.array_equal(saved["row_index"], test_index):
                            raise ValueError(f"Checkpoint row alignment differs for {tag}.")
                        local_fm, local_qr = saved["fm"], saved["qr"]
                        local_condition = saved["condition"]
                        local_diagnostics = json.loads(str(saved["diagnostics"]))
                        local_reconstruction = json.loads(str(saved["reconstruction"]))
                    member, fit_action = str(path), "Resumed saved ablation calculation"
                else:
                    tick = time.perf_counter()
                    payload, member, fit_action = empirical_model(kind, run_seed, year, x_raw, y, fold)
                    predictor = FrozenPredictor(payload, kind, empirical=True)
                    explainers = {r: OrderedGaussianCOLA(geometries[r], predictor, CFG["empirical_base_draws"],
                                  seed_for(run_seed, 705, year)) for r in REFERENCES}
                    local_fm = np.full((len(REFERENCES), len(year_months), k), np.nan)
                    local_qr = np.full((len(REFERENCES), len(year_months), len(CFG["quantiles"]), k), np.nan)
                    local_condition = np.full((len(REFERENCES), len(year_months)), np.inf)
                    all_attributions = np.empty((len(REFERENCES), len(test_index), k))
                    predictions = predictor.predict(x_test)
                    local_diagnostics, local_reconstruction = [], []
                    for ri, reference_name in enumerate(REFERENCES):
                        explainer = explainers[reference_name]
                        for ti, (month, positions) in enumerate(zip(year_months, month_rows)):
                            attr, prediction = explainer.explain(x_test[positions], CFG["ce_draws"],
                                seed_for(run_seed, 706, month.ordinal))
                            all_attributions[ri, positions] = attr
                            local_condition[ri, ti] = full_condition_number(attr, intercept=True)
                            design, active, status = monthly_design(attr)
                            common = {"model": kind, "seed": run_seed, "year": year,
                                      "return_date": str(month), "reference": reference_name,
                                      "rows": len(positions), "active_features": len(active)}
                            local_diagnostics.append({**common, "analysis": "FM", "tau": None, "status": status})
                            if design is not None:
                                beta = np.linalg.lstsq(design, y[test_index[positions]], rcond=CFG["rank_tol"])[0]
                                local_fm[ri, ti, active] = beta[1:]
                            for qi, tau in enumerate(CFG["quantiles"]):
                                if design is None:
                                    beta, result = None, status
                                else:
                                    beta, result = quantile_fit(design, y[test_index[positions]], tau)
                                local_diagnostics.append({**common, "analysis": "QR", "tau": tau, "status": result})
                                if beta is not None:
                                    local_qr[ri, ti, qi, active] = beta[1:]
                        residual = predictions - explainer.base - all_attributions[ri].sum(axis=1)
                        local_reconstruction.append({"model": kind, "seed": run_seed, "year": year,
                            "reference": reference_name, "rows": len(test_index),
                            "squared_error": float(np.sum(residual ** 2)),
                            "maximum_absolute_error": float(np.max(np.abs(residual)))})
                    save_npz(path, fm=local_fm, qr=local_qr, condition=local_condition,
                             attribution=all_attributions, prediction=predictions,
                             baseline=np.asarray([explainers[r].base for r in REFERENCES]),
                             row_index=test_index, return_date=np.asarray([str(m) for m in target_dates]),
                             diagnostics=np.array(json.dumps(local_diagnostics)),
                             reconstruction=np.array(json.dumps(local_reconstruction)))
                    log("French", f"{tag}: two references, {len(test_index):,} rows; {time.perf_counter() - tick:.1f}s")
                    del predictor, explainers, all_attributions
                MODEL_ROWS.append({"scope": "French100", "model": kind, "seed": run_seed,
                                   "year": year, "source": member, "action": fit_action})
                for ri, reference_name in enumerate(REFERENCES):
                    fm[reference_name][mi, si, global_months, :] = local_fm[ri]
                    qr[reference_name][mi, si, global_months, :, :] = local_qr[ri]
                    conditions[reference_name][mi, si, global_months] = local_condition[ri]
                diagnostic_rows.extend(local_diagnostics)
                reconstruction_rows.extend(local_reconstruction)
        save_csv(pd.DataFrame(split_rows), "french_annual_splits")
        save_csv(pd.DataFrame(EVENTS), "events")
        gc.collect()
    return fm, qr, conditions, pd.DataFrame(diagnostic_rows), pd.DataFrame(reconstruction_rows)


with threadpool_limits(limits=CFG["n_jobs"]):
    EMP_FM, EMP_QR, EMP_CONDITION, EMP_DIAGNOSTICS, EMP_RECONSTRUCTION = run_french()
save_csv(EMP_DIAGNOSTICS, "french_analysis_diagnostics")
save_csv(EMP_RECONSTRUCTION, "french_reconstruction_by_vintage")

# %% Cell 8: Paired summaries, confidence intervals and numerical tables
def percentile_bounds(values):
    tail = (1 - BS["level"]) / 2
    return np.quantile(values, [tail, 1 - tail], method="inverted_cdf")


run_ids = sorted(CFG["seeds"])
run_rng = np.random.default_rng(seed_for(CFG["seed"], 950))
RUN_INDEX = run_rng.integers(0, len(run_ids), size=(BS["simulation_reps"], len(run_ids)))
SIMULATION_METRICS = ["median_condition", "prefix_infid", "prefix_rmse", "reconstruction_nrmse"]
simulation_rows, simulation_differences, aggregate_runs = [], [], []
for rho in CFG["rho"]:
    for metric in SIMULATION_METRICS:
        paired = {}
        for reference_name in REFERENCES:
            values = []
            for seed in run_ids:
                block = SIM_METRICS[(SIM_METRICS["rho"] == rho) & (SIM_METRICS["seed"] == seed)
                                    & (SIM_METRICS["reference"] == reference_name)]
                if set(block["model"]) != set(CFG["models"]):
                    raise ValueError("Every simulation aggregate requires all three prediction models.")
                value = float(np.mean(block[metric].to_numpy(float)))
                values.append(value)
                aggregate_runs.append({"rho": rho, "seed": seed, "reference": reference_name,
                                       "metric": metric, "value": value})
            values = np.asarray(values)
            paired[reference_name] = values
            draws = values[RUN_INDEX].mean(axis=1)
            lo, hi = percentile_bounds(draws)
            simulation_rows.append({"rho": rho, "reference": reference_name, "metric": metric,
                "mean": float(values.mean()), "lo": float(lo), "hi": float(hi),
                "run_sd": float(values.std(ddof=1)) if np.isfinite(values).all() else np.nan,
                "runs": len(values), "models": len(CFG["models"]), "bootstrap_reps": len(draws)})
        with np.errstate(invalid="ignore"):
            difference = paired["Full"] - paired["Diagonal"]
        if np.isnan(difference).any():
            mean, lo, hi, status = np.nan, np.nan, np.nan, "Undefined nonfinite contrast"
        else:
            mean = float(difference.mean())
            lo, hi = map(float, percentile_bounds(difference[RUN_INDEX].mean(axis=1)))
            status = "OK"
        simulation_differences.append({"rho": rho, "metric": metric, "contrast": "Full minus Diagonal",
                                       "mean": mean, "lo": lo, "hi": hi, "status": status})
SIM_SUMMARY = pd.DataFrame(simulation_rows)
save_csv(SIM_SUMMARY, "simulation_summary")
save_csv(pd.DataFrame(aggregate_runs), "simulation_aggregate_per_seed")
save_csv(pd.DataFrame(simulation_differences), "simulation_paired_differences")
save_csv(SIM_METRICS.groupby(["model", "rho", "reference"], as_index=False)[SIMULATION_METRICS].agg(
    lambda values: float(np.mean(values.to_numpy(float)))), "simulation_summary_by_model")


def stationary_indices(months, repetitions, seed):
    length = max(2, int(round(months ** (1 / 3)))) if BS["block"] is None else int(BS["block"])
    length = min(max(1, length), months)
    rng = np.random.default_rng(seed)
    index = np.empty((repetitions, months), int)
    index[:, 0] = rng.integers(0, months, repetitions)
    for t in range(1, months):
        restart = rng.random(repetitions) < 1 / length
        index[:, t] = np.where(restart, rng.integers(0, months, repetitions), (index[:, t - 1] + 1) % months)
    return index, length


def summarize_monthly(series, resampling):
    series = np.asarray(series, float)
    count = int(np.isfinite(series).sum())
    output = {"mean": float(series[np.isfinite(series)].mean()) if count else np.nan,
              "se": np.nan, "lo": np.nan, "hi": np.nan, "p": np.nan,
              "months": count, "bootstrap_valid": 0, "status": "Few supported months"}
    if count < BS["min_months"]:
        return output
    samples = series[resampling]
    finite = np.isfinite(samples)
    denominator = finite.sum(axis=1)
    draws = np.full(len(samples), np.nan)
    np.divide(np.where(finite, samples, 0).sum(axis=1), denominator, out=draws,
              where=denominator >= max(3, BS["min_months"] // 2))
    draws = draws[np.isfinite(draws)]
    output["bootstrap_valid"] = len(draws)
    if len(draws) < BS["min_valid_share"] * len(resampling):
        output["status"] = "Sparse supported resamples"
        return output
    output["lo"], output["hi"] = map(float, percentile_bounds(draws))
    output["se"] = float(draws.std(ddof=1))
    exceedances = int(np.sum(np.abs(draws - output["mean"]) >= abs(output["mean"])))
    output["p"] = (1 + exceedances) / (1 + len(draws))
    output["status"] = "OK"
    return output


def holm_adjust(pvalues):
    values = np.asarray(pvalues, float)
    filled = np.where(np.isfinite(values), values, 1.0)
    order = np.argsort(filled, kind="stable")
    adjusted = np.minimum(1.0, np.maximum.accumulate(filled[order] * np.arange(len(values), 0, -1)))
    output = np.empty(len(values))
    output[order] = adjusted
    output[~np.isfinite(values)] = np.nan
    return output


def in_basis_points(frame):
    frame = frame.copy()
    for column in ["mean", "se", "lo", "hi"]:
        frame[column] *= CFG["bps"]
    return frame


BOOT_INDEX, BLOCK_LENGTH = stationary_indices(len(TEST_MONTHS), BS["empirical_reps"], seed_for(CFG["seed"], 960))
log("Inference", f"Paired stationary month bootstrap: {BS['empirical_reps']} draws; mean block={BLOCK_LENGTH}.")
analyses = [("FM", None)] + [("QR", tau) for tau in CFG["quantiles"]]
reference_rows, matched_rows, contrast_rows, model_rows, monthly_rows, condition_rows = [], [], [], [], [], []
for j, feature in enumerate(FEATURES):
    for analysis, tau in analyses:
        aggregate_series = {}
        for reference_name in REFERENCES:
            all_values = EMP_FM[reference_name][:, :, :, j] if analysis == "FM" else EMP_QR[reference_name][:, :, :, CFG["quantiles"].index(tau), j]
            # Fixed model/seed weights preserve the original aggregate estimand.
            series = np.mean(all_values, axis=(0, 1))
            aggregate_series[reference_name] = series
            common = {"reference": reference_name, "feature": feature, "analysis": analysis, "tau": tau}
            reference_rows.append({**common, **summarize_monthly(series, BOOT_INDEX)})
            for mi, kind in enumerate(CFG["models"]):
                model_series = all_values[mi].mean(axis=0)
                model_rows.append({**common, "model": kind, **summarize_monthly(model_series, BOOT_INDEX)})
            for ti, month in enumerate(TEST_MONTHS):
                monthly_rows.append({**common, "return_date": str(month), "coefficient": float(series[ti]),
                    "supported_model_seed_pairs": int(np.isfinite(all_values[:, :, ti]).sum()),
                    "expected_model_seed_pairs": len(CFG["models"]) * len(CFG["seeds"])})
        support = np.isfinite(aggregate_series["Full"]) & np.isfinite(aggregate_series["Diagonal"])
        for reference_name in REFERENCES:
            matched = np.where(support, aggregate_series[reference_name], np.nan)
            matched_rows.append({"reference": reference_name, "feature": feature, "analysis": analysis,
                                 "tau": tau, **summarize_monthly(matched, BOOT_INDEX)})
        difference = np.where(support, aggregate_series["Full"] - aggregate_series["Diagonal"], np.nan)
        contrast_rows.append({"feature": feature, "analysis": analysis, "tau": tau,
                             "contrast": "Full minus Diagonal", **summarize_monthly(difference, BOOT_INDEX)})

EMP_SUMMARY = pd.DataFrame(reference_rows)
EMP_SUMMARY["p_holm_48"] = holm_adjust(EMP_SUMMARY["p"].to_numpy())
EMP_MATCHED = pd.DataFrame(matched_rows)
EMP_DIFFERENCES = pd.DataFrame(contrast_rows)
EMP_DIFFERENCES["p_holm_24"] = holm_adjust(EMP_DIFFERENCES["p"].to_numpy())
EMP_DIFFERENCES["p_holm_focal_4"] = np.nan
focal_mask = EMP_DIFFERENCES["feature"].eq(CFG["focal_feature"])
EMP_DIFFERENCES.loc[focal_mask, "p_holm_focal_4"] = holm_adjust(EMP_DIFFERENCES.loc[focal_mask, "p"].to_numpy())
for reference_name in REFERENCES:
    for mi, kind in enumerate(CFG["models"]):
        for si, seed in enumerate(CFG["seeds"]):
            for ti, month in enumerate(TEST_MONTHS):
                value = float(EMP_CONDITION[reference_name][mi, si, ti])
                condition_rows.append({"reference": reference_name, "model": kind, "seed": seed,
                    "return_date": str(month), "condition": value,
                    "weight": 1 / (len(CFG["models"]) * len(CFG["seeds"]) * len(TEST_MONTHS))})
EMP_CONDITION_TABLE = pd.DataFrame(condition_rows)
save_csv(in_basis_points(EMP_SUMMARY), "french_reference_summary_bp")
save_csv(in_basis_points(EMP_MATCHED), "french_matched_reference_summary_bp")
save_csv(in_basis_points(EMP_DIFFERENCES), "french_paired_differences_bp")
save_csv(in_basis_points(pd.DataFrame(model_rows)), "french_summary_by_model_bp")
save_csv(pd.DataFrame(monthly_rows), "french_aggregate_monthly_coefficients")
save_csv(EMP_CONDITION_TABLE, "french_conditioning_distribution")
conditioning_summary = []
for (reference_name, kind), block in EMP_CONDITION_TABLE.groupby(["reference", "model"], sort=False):
    values = block["condition"].to_numpy(float)
    q25, median, q75 = np.quantile(values, [0.25, 0.5, 0.75], method="inverted_cdf")
    conditioning_summary.append({"reference": reference_name, "model": kind,
        "q25": q25, "median": median, "q75": q75, "requested_model_seed_months": len(values),
        "infinite_model_seed_months": int(np.isinf(values).sum())})
save_csv(pd.DataFrame(conditioning_summary), "french_conditioning_summary_by_model")
save_csv(pd.DataFrame(MODEL_ROWS), "fitted_model_sources")
save_csv(pd.DataFrame(SOURCE_ROWS), "main_output_sources")

# %% Cell 9: One four-panel figure with a shared top legend
def place_legend_header(fig, axes, handles, ncol=3, hspace=0.50, wspace=0.38):
    """Preserve the physical panel canvas and add a measured legend header."""
    # Layout engines can override subplots_adjust or ignore figure legends.
    # Use one explicit physical layout for both saved files and inline figures.
    with mpl.rc_context({"figure.constrained_layout.use": False, "figure.autolayout": False}):
        fig.set_layout_engine(None)
    base_width, base_height = map(float, fig.get_size_inches())
    panel_axes = list(np.asarray(axes, dtype=object).ravel())
    side_pad, bottom_pad, top_pad, legend_gap = 0.12, 0.08, 0.12, 0.18
    fig.subplots_adjust(left=0.12, right=0.98, bottom=0.64 / base_height,
                        top=(base_height - 0.34) / base_height,
                        hspace=hspace, wspace=wspace)
    panel_rectangles = [
        (ax.get_position().x0 * base_width, ax.get_position().y0 * base_height,
         ax.get_position().width * base_width, ax.get_position().height * base_height)
        for ax in panel_axes
    ]
    columns = min(max(1, int(ncol)), len(handles))
    legend = None
    while True:
        if legend is not None:
            legend.remove()
        legend = fig.legend(
            handles=handles, loc="upper center", bbox_to_anchor=(0.5, 1.0),
            bbox_transform=fig.transFigure, ncol=columns, frameon=False,
            fontsize=8, borderaxespad=0.0, borderpad=0.20, labelspacing=0.45,
            columnspacing=1.10, handlelength=1.8, handletextpad=0.50,
        )
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        legend_box = legend.get_window_extent(renderer)
        legend_width, legend_height = legend_box.width / fig.dpi, legend_box.height / fig.dpi
        if legend_width <= base_width - 2 * side_pad or columns == 1:
            break
        columns -= 1
    panel_boxes = [ax.get_tightbbox(renderer) for ax in panel_axes]
    panel_boxes = [box for box in panel_boxes if box is not None]
    left_extra = max(0.0, side_pad - min(box.x0 / fig.dpi for box in panel_boxes))
    right_extra = max(0.0, max(box.x1 / fig.dpi for box in panel_boxes) - base_width + side_pad)
    bottom_extra = max(0.0, bottom_pad - min(box.y0 / fig.dpi for box in panel_boxes))
    panel_width = base_width + left_extra + right_extra
    final_width = max(panel_width, legend_width + 2 * side_pad)
    horizontal_offset = left_extra + (final_width - panel_width) / 2
    panel_ceiling = max(box.y1 / fig.dpi for box in panel_boxes) + bottom_extra
    header_bottom = max(base_height + bottom_extra, panel_ceiling) + legend_gap
    final_height = header_bottom + legend_height + top_pad

    def apply_canvas(height):
        fig.set_size_inches(final_width, height, forward=True)
        for ax, (left, bottom, width, panel_height) in zip(panel_axes, panel_rectangles):
            ax.set_position([(left + horizontal_offset) / final_width,
                             (bottom + bottom_extra) / height,
                             width / final_width, panel_height / height])
        legend.set_bbox_to_anchor((0.5, 1.0 - top_pad / height), transform=fig.transFigure)

    apply_canvas(final_height)
    # Font backends can differ; reserve the measured separation after resizing.
    for _ in range(3):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        current_top = max(ax.get_tightbbox(renderer).y1 / fig.dpi for ax in panel_axes)
        current_legend_bottom = legend.get_window_extent(renderer).y0 / fig.dpi
        missing = current_top + legend_gap - current_legend_bottom
        if missing <= 0.001:
            break
        final_height += missing + 0.02
        apply_canvas(final_height)
    fig.canvas.draw()
    return {
        "figure_inches": [float(final_width), float(final_height)],
        "panel_canvas_inches": [base_width, base_height],
        "legend_columns": columns,
        "legend_rows": int(math.ceil(len(handles) / columns)),
        "legend_height_inches": float(legend_height),
        "minimum_legend_gap_inches": legend_gap,
        "layout_engine": "none",
    }


