def plot_simulation_metric(ax, metric):
    for reference_name in REFERENCES:
        block = SIM_SUMMARY[(SIM_SUMMARY["metric"] == metric) & (SIM_SUMMARY["reference"] == reference_name)].sort_values("rho")
        x, point, lo, hi = [block[name].to_numpy(float) for name in ["rho", "mean", "lo", "hi"]]
        point = np.where(np.isfinite(point), point, np.nan)
        ax.plot(x, point, color=COLORS[reference_name], marker=MARKERS[reference_name])
        valid = np.isfinite(lo) & np.isfinite(hi)
        ax.fill_between(x, lo, hi, where=valid, color=COLORS[reference_name], alpha=0.13, linewidth=0)
    ax.set_xticks(CFG["rho"])
    ax.set_xlabel(r"Input correlation $\rho$")


plot_simulation_metric(axes[0, 0], "median_condition")
axes[0, 0].set(title="A  Synthetic conditioning", ylabel="Condition number")
axes[0, 0].set_ylim(bottom=1.0)
plot_simulation_metric(axes[0, 1], "prefix_infid")
axes[0, 1].set(title="B  Common-reference fidelity", ylabel="Prefix infidelity", yscale="log")

finite_values = EMP_CONDITION_TABLE.loc[np.isfinite(EMP_CONDITION_TABLE["condition"]), "condition"]
condition_limit = max(1.1, float(finite_values.max()) * 1.05) if len(finite_values) else 10.0
for reference_name in REFERENCES:
    block = EMP_CONDITION_TABLE[EMP_CONDITION_TABLE["reference"] == reference_name]
    finite = block.loc[np.isfinite(block["condition"])].sort_values("condition")
    if len(finite):
        values = finite["condition"].to_numpy(float)
        shares = np.cumsum(finite["weight"].to_numpy(float))
        axes[1, 0].step(np.r_[1.0, values, condition_limit], np.r_[0.0, shares, shares[-1]],
                        where="post", color=COLORS[reference_name])
axes[1, 0].set(title="C  French 100 conditioning", xlabel="Condition number",
               ylabel="Weighted cumulative share", xscale="log", xlim=(1.0, condition_limit), ylim=(0, 1.02))

for reference_name in REFERENCES:
    block = EMP_MATCHED[(EMP_MATCHED["feature"] == CFG["focal_feature"])
                       & (EMP_MATCHED["analysis"] == "QR")
                       & (EMP_MATCHED["reference"] == reference_name)].sort_values("tau")
    x = block["tau"].to_numpy(float)
    point, lo, hi = [block[name].to_numpy(float) * CFG["bps"] for name in ["mean", "lo", "hi"]]
    axes[1, 1].plot(x, point, color=COLORS[reference_name], marker=MARKERS[reference_name])
    axes[1, 1].fill_between(x, lo, hi, where=np.isfinite(lo) & np.isfinite(hi),
                           color=COLORS[reference_name], alpha=0.13, linewidth=0)
axes[1, 1].axhline(0, color="#666666", linestyle="--", linewidth=0.9)
axes[1, 1].set(title=f"D  {CFG['focal_feature']} quantile slopes", xlabel="Quantile", ylabel="Slope per attribution SD (bp)")
axes[1, 1].set_xticks(CFG["quantiles"])

legend_handles = [Line2D([], [], color=COLORS[r], marker=MARKERS[r], label=REFERENCE_LABELS[r]) for r in REFERENCES]
legend_handles.append(Line2D([], [], color="#666666", linestyle="--", label="Zero reference"))
FIGURE_LAYOUT = place_legend_header(fig, axes, legend_handles, ncol=3, hspace=0.50, wspace=0.40)
