def plot_simulation_metric(ax, metric):
    for order_id in ORDER_IDS:
        block = SIM_SUMMARY[(SIM_SUMMARY["metric"] == metric)
                            & (SIM_SUMMARY["order"] == order_id)].sort_values("rho")
        x, point = block["rho"].to_numpy(float), block["mean"].to_numpy(float)
        point = np.where(np.isfinite(point), point, np.nan)
        if metric == "prefix_infid":
            point = np.where(point > 0, point, np.nan)
        ax.plot(x, point, color=COLORS[order_id], marker=MARKERS[order_id],
                linestyle=LINESTYLES[order_id], alpha=0.95)
    ax.set_xticks(CFG["rho"])
    ax.set_xlabel(r"Input correlation $\rho$")


plot_simulation_metric(axes[0, 0], "median_condition")
axes[0, 0].set(title="A  Synthetic conditioning", ylabel="Condition number", yscale="log")
axes[0, 0].set_ylim(bottom=1.0)
plot_simulation_metric(axes[0, 1], "prefix_infid")
axes[0, 1].set(title="B  Synthetic prefix fidelity", ylabel="Prefix infidelity", yscale="log")

finite_values = EMP_CONDITION_TABLE.loc[np.isfinite(EMP_CONDITION_TABLE["condition"]), "condition"]
condition_limit = max(1.1, float(finite_values.max()) * 1.05) if len(finite_values) else 10.0
for order_id in ORDER_IDS:
    block = EMP_CONDITION_TABLE[EMP_CONDITION_TABLE["order"] == order_id]
    finite = block.loc[np.isfinite(block["condition"])].sort_values("condition")
    if len(finite):
        values, shares = finite["condition"].to_numpy(float), np.cumsum(finite["weight"].to_numpy(float))
        axes[1, 0].step(np.r_[1.0, values, condition_limit], np.r_[0.0, shares, shares[-1]],
            where="post", color=COLORS[order_id], linestyle=LINESTYLES[order_id])
axes[1, 0].set(title="C  French 100 conditioning", xlabel="Condition number",
    ylabel="Weighted cumulative share", xscale="log", xlim=(1.0, condition_limit), ylim=(0, 1.02))

x_centers = np.arange(len(analyses), dtype=float)
offsets = np.linspace(-0.23, 0.23, len(ORDER_IDS))
for oi, order_id in enumerate(ORDER_IDS):
    means, lows, highs = [], [], []
    for analysis, tau in analyses:
        mask = (EMP_MATCHED["feature"].eq(CFG["focal_feature"])
                & EMP_MATCHED["analysis"].eq(analysis) & EMP_MATCHED["order"].eq(order_id))
        mask &= EMP_MATCHED["tau"].isna() if tau is None else EMP_MATCHED["tau"].eq(tau)
        row = EMP_MATCHED.loc[mask].iloc[0]
        means.append(float(row["mean"]) * CFG["bps"])
        lows.append(float(row["lo"]) * CFG["bps"])
        highs.append(float(row["hi"]) * CFG["bps"])
    x = x_centers + offsets[oi]
    point, lo, hi = np.asarray(means), np.asarray(lows), np.asarray(highs)
    finite = np.isfinite(point)
    axes[1, 1].scatter(x[finite], point[finite], color=COLORS[order_id], marker=MARKERS[order_id],
                       s=16, zorder=4)
    supported = finite & np.isfinite(lo) & np.isfinite(hi)
    axes[1, 1].vlines(x[supported], lo[supported], hi[supported], color=COLORS[order_id], linewidth=0.8)
    axes[1, 1].hlines(lo[supported], x[supported] - 0.025, x[supported] + 0.025,
                      color=COLORS[order_id], linewidth=0.8)
    axes[1, 1].hlines(hi[supported], x[supported] - 0.025, x[supported] + 0.025,
                      color=COLORS[order_id], linewidth=0.8)
axes[1, 1].axhline(0, color="#888888", linestyle=":", linewidth=0.7, zorder=1)
