def compatible_main_source(source, empirical=False):
    if source is None:
        return False
    try:
        if empirical:
            configuration = source.read_json("run_configuration.json")
            settings = configuration["settings"]
            data = configuration["data"]
            match = all(settings.get(key) == CFG[key] for key in MODEL_KEYS + ["seeds", "models", "quantiles"])
            match &= all(data.get(key) == CFG[key] for key in ["train_start", "test_start", "test_end", "validation_months", "purge_months"])
            return bool(match and data.get("gaussianize", False))
        settings = source.read_json("config.json")["simulation"]
        return all(settings.get(key) == CFG[key] for key in MODEL_KEYS + SIMULATION_KEYS)
    except (KeyError, ValueError, FileNotFoundError):
        return False


