def read_french_block(payload, expected_columns, value_weighted=False):
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        members = [n for n in archive.namelist() if n.lower().endswith(".csv") and "__MACOSX" not in n]
        if len(members) != 1:
            raise ValueError("Expected one French source CSV per ZIP.")
        content = archive.read(members[0]).decode("utf-8-sig", errors="replace")
    armed, header, dates, values = not value_weighted, None, [], []
    for line in content.splitlines():
        title = line.lower().replace("-", " ")
        if value_weighted and all(word in title for word in ["value", "weighted", "monthly"]):
            armed = True
            continue
        if not armed:
            continue
        fields = [s.strip() for s in next(csv.reader([line]))] if line.strip() else []
        while len(fields) > expected_columns + 1 and fields[-1] == "":
            fields.pop()
        first = fields[0] if fields else ""
        if len(first) == 6 and first.isdigit():
            if header is None or len(fields) != expected_columns + 1:
                raise ValueError("Unexpected row in the French monthly return table.")
            dates.append(first)
            values.append([float(v) if v else np.nan for v in fields[1:]])
        elif dates:
            break
        elif len(fields) == expected_columns + 1 and first.lower() in {"", "date"} and all(fields[1:]):
            header = fields[1:]
    if not dates or header is None:
        raise ValueError("The requested French monthly table was not found.")
    array = np.asarray(values, float)
    missing = np.isclose(array, -99.99, rtol=0, atol=1e-8) | np.isclose(array, -999, rtol=0, atol=1e-8)
    array[missing] = np.nan
    return pd.DataFrame(array / 100, index=pd.to_datetime(dates, format="%Y%m").to_period("M"), columns=header).sort_index()


def fetch_french_file(specification, expected_hash=None):
    candidates = [BASE_DIR / "ff100_cache" / "raw" / specification["file"], RAW_DIR / specification["file"]]
    existing = [path for path in candidates if path.is_file() and zipfile.is_zipfile(path)]
    matching = [path for path in existing if expected_hash and digest_file(path) == expected_hash]
    if matching or existing:
        path = (matching or existing)[0]
        log("Cache", f"Using {specification['file']}")
        return path
    path = RAW_DIR / specification["file"]
    temporary = path.with_suffix(".zip.partial")
    for attempt in range(1, 4):
        log("Download", f"{specification['file']}: attempt {attempt}")
        try:
            request = Request(specification["url"], headers={"User-Agent": "Mozilla/5.0", "Accept": "application/zip,*/*"})
            with urlopen(request, timeout=60) as response, temporary.open("wb") as target:
                while True:
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    target.write(chunk)
            if not zipfile.is_zipfile(temporary):
                raise ValueError("The French source response must be a CSV ZIP archive.")
            temporary.replace(path)
            return path
        except Exception:
            temporary.unlink(missing_ok=True)
            if attempt == 3:
                raise
            time.sleep(attempt)


def load_french_panel():
    expected_sources = []
    if MAIN2 and MAIN2.has("data_source.json"):
        expected_sources = MAIN2.read_json("data_source.json").get("sources", [])
    expected = {entry["url"]: entry["sha256"] for entry in expected_sources}
    actual_sources = []
    if MAIN3 and MAIN3.has("data/French100_monthly.parquet") and MAIN3.has("tables/data_sources.csv"):
        source_table = MAIN3.read_csv("tables/data_sources.csv")
        for specification in FRENCH_FILES:
            matching = source_table[source_table["url"].eq(specification["url"])]
            if matching.empty or matching["sha256"].nunique() != 1:
                raise ValueError("The cached French panel requires identifiable return and RF source hashes.")
            actual_sources.append({**specification, "sha256": str(matching["sha256"].iloc[0])})
        panel = pd.read_parquet(io.BytesIO(MAIN3.read_bytes("data/French100_monthly.parquet")))
        origin = "Existing local Experiment 3 French monthly panel"
    else:
        parsed = []
        for position, specification in enumerate(FRENCH_FILES):
            path = fetch_french_file(specification, expected.get(specification["url"]))
            actual_sources.append({**specification, "sha256": digest_file(path), "bytes": path.stat().st_size})
            parsed.append(read_french_block(path.read_bytes(), 100 if position == 0 else 4, value_weighted=position == 0))
        returns, factors = parsed
        calendar = pd.period_range(returns.index.min(), returns.index.max(), freq="M")
        returns = returns.reindex(calendar)
        rf = factors["RF"].reindex(calendar)
        gross = 1 + returns
        feature_values = {
            "Ret1": returns,
            "Mom3": gross.rolling(3, min_periods=3).apply(np.prod, raw=True) - 1,
            "Mom12_2": gross.shift(1).rolling(11, min_periods=11).apply(np.prod, raw=True) - 1,
            "Vol12": returns.rolling(12, min_periods=12).std(ddof=1),
            "DownVol12": np.sqrt(returns.clip(upper=0).pow(2).rolling(12, min_periods=12).mean()),
            "Skew12": returns.rolling(12, min_periods=12).skew(),
        }
        response, realized, frames = returns.sub(rf, axis=0).shift(-1), calendar + 1, []
        wanted = (realized >= pd.Period(CFG["train_start"])) & (realized <= pd.Period(CFG["test_end"]))
        for identifier in returns.columns:
            block = pd.DataFrame({name: feature_values[name][identifier].to_numpy() for name in FEATURES})
            block["id"], block["date"], block["return_date"] = str(identifier), calendar.astype(str), realized.astype(str)
            block["y"] = response[identifier].to_numpy()
            frames.append(block.loc[wanted])
        panel = pd.concat(frames, ignore_index=True).replace([np.inf, -np.inf], np.nan).dropna(subset=["y", *FEATURES])
        origin = "French Data Library monthly return sources; locally cached after direct download"
    panel = panel[["id", "date", "return_date", "y", *FEATURES]].copy()
    panel["id"] = panel["id"].astype(str)
    panel["date"], panel["return_date"] = month_index(panel["date"]).astype(str), month_index(panel["return_date"]).astype(str)
    wanted = panel["return_date"].between(CFG["train_start"], CFG["test_end"])
    panel = panel.loc[wanted].sort_values(["return_date", "id"], kind="stable").reset_index(drop=True)
    if panel.duplicated(["id", "return_date"]).any() or not np.isfinite(panel[["y", *FEATURES]].to_numpy(float)).all():
        raise ValueError("The monthly panel has duplicate keys or incomplete observations.")
    if not np.all(month_index(panel["date"]) + 1 == month_index(panel["return_date"])):
        raise ValueError("Feature and response months must be consecutive.")
    matches_main = bool(expected) and all(expected.get(entry["url"]) == entry["sha256"] for entry in actual_sources)
    provenance = {"origin": origin, "sources": actual_sources, "matches_main_model_sources": matches_main}
    return panel, provenance


FRENCH, FRENCH_PROVENANCE = load_french_panel()
USE_MAIN2 = MAIN2_CONFIG_COMPATIBLE and FRENCH_PROVENANCE["matches_main_model_sources"]
FRENCH_SIGNATURE = hashlib.sha256(pd.util.hash_pandas_object(FRENCH, index=True).values.tobytes()).hexdigest()
