# %% Cell 5: Frozen predictors, nested sampling and shared model cache
class FrozenPredictor:
    def __init__(self, payload, kind, empirical=False):
        self.kind, self.empirical = kind, empirical
        self.estimator = payload["estimator"]
        self.location = float(payload.get("target_mean", 0.0))
        self.scale = float(payload.get("target_scale", 1.0))
        if kind == "XGB":
            self.estimator.set_params(n_jobs=CFG["n_jobs"])

    def predict(self, x):
        x = np.asarray(x, dtype=np.float32 if self.empirical else float)
        if self.kind == "XGB":
            value = self.estimator.get_booster().inplace_predict(np.ascontiguousarray(x), validate_features=False)
        else:
            value = self.estimator.predict(x)
        return self.location + self.scale * np.asarray(value, float)

    def affine_parameters(self):
        if self.kind != "LR":
            raise ValueError("Analytical affine parameters require an OLS predictor.")
        return np.asarray(self.estimator.coef_, float) * self.scale, self.location + self.scale * float(self.estimator.intercept_)


def psd_root(covariance):
    values, vectors = np.linalg.eigh((covariance + covariance.T) / 2)
    return vectors @ np.diag(np.sqrt(np.maximum(values, 0)))


def gaussian_geometry(mean, covariance):
    mean, covariance = np.asarray(mean, float), np.asarray(covariance, float)
    prefixes = []
    for size in range(1, len(mean)):
        cross = covariance[:size, size:]
        gain = np.linalg.solve(covariance[:size, :size], cross)
        conditional_covariance = covariance[size:, size:] - cross.T @ gain
        prefixes.append((size, gain, psd_root(conditional_covariance)))
    return {"mean": mean, "covariance": covariance, "prefixes": prefixes}


def fitted_geometry(x_reference):
    fitted = LedoitWolf().fit(x_reference)
    return gaussian_geometry(fitted.location_.copy(), fitted.covariance_.copy())


def shared_baseline(geometry, predictor, draws, seed):
    rng = np.random.default_rng(seed)
    background = rng.multivariate_normal(geometry["mean"], geometry["covariance"], int(draws))
    return float(predictor.predict(background).mean())


class BudgetGaussianCOLA:
    """The same conditional integrals under two sampling rules and nested budgets."""

    def __init__(self, geometry, predictor, baseline, analytical=False):
        self.geometry, self.predictor = geometry, predictor
        self.mean, self.k, self.base = geometry["mean"], len(geometry["mean"]), float(baseline)
        self.analytical = bool(analytical)
        if self.analytical:
            self.weight, self.intercept = predictor.affine_parameters()

    def multi_values(self, x, budgets, seed, sampler):
        x = np.asarray(x, dtype=np.float32 if self.predictor.empirical else float)
        budgets = sorted(set(map(int, budgets)))
        if not budgets or any(draws < 2 or draws % 2 for draws in budgets):
            raise ValueError("All integration budgets must be even integers of at least two.")
        if sampler not in SAMPLERS:
            raise ValueError("Unknown conditional sampling rule.")
        maximum = max(budgets)
        prediction = self.predictor.predict(x)
        output = {draws: np.empty((len(x), self.k + 1), float) for draws in budgets}
        for values in output.values():
            values[:, 0], values[:, -1] = self.base, prediction
        for size, gain, root in self.geometry["prefixes"]:
            center = self.mean[size:] + (x[:, :size] - self.mean[:size]) @ gain
            if self.analytical:
                exact = self.intercept + x[:, :size] @ self.weight[:size] + center @ self.weight[size:]
                for values in output.values():
                    values[:, size] = exact
                continue
            # Prefix-specific streams keep a smaller budget nested in a larger one.
            rng = np.random.default_rng(seed_for(seed, 1600, size))
            normal_count = maximum // 2 if sampler == "Antithetic" else maximum
            normal = rng.standard_normal((normal_count, self.k - size))
            if sampler == "Antithetic":
                normal = np.stack([normal, -normal], axis=1).reshape(maximum, self.k - size)
            noise = normal @ root.T
            for start in range(0, len(x), CFG["prediction_batch"]):
                stop = min(start + CFG["prediction_batch"], len(x))
                filled = np.broadcast_to(x[start:stop, None, :],
                    (stop - start, maximum, self.k)).copy()
                filled[:, :, size:] = center[start:stop, None, :] + noise[None, :, :]
                predicted = self.predictor.predict(filled.reshape(-1, self.k)).reshape(stop - start, maximum)
                cumulative = np.cumsum(predicted, axis=1, dtype=float)
                for draws in budgets:
                    output[draws][start:stop, size] = cumulative[:, draws - 1] / draws
        return output

    def values(self, x, draws, seed, sampler):
        return self.multi_values(x, [draws], seed, sampler)[int(draws)]

    def explain(self, x, draws, seed, sampler):
        values = self.values(x, draws, seed, sampler)
        return np.diff(values, axis=1), values


def full_condition_number(attributions, intercept=False):
    attributions = np.asarray(attributions, float)
    if len(attributions) <= attributions.shape[1] or not np.isfinite(attributions).all():
        return np.inf
    scale = attributions.std(axis=0, ddof=0)
    if np.any(scale <= 1e-12):
        return np.inf
    design = (attributions - attributions.mean(axis=0)) / scale
    if intercept:
        design = np.column_stack([np.ones(len(design)), design])
    singular = np.linalg.svd(design, compute_uv=False)
    return float(singular[0] / singular[-1]) if singular[-1] > CFG["rank_tol"] * singular[0] else np.inf


def monthly_design(attributions):
    scales = attributions.std(axis=0, ddof=0)
    active = np.flatnonzero(scales > 1e-12)
    if len(attributions) < max(CFG["min_cross_section"], len(active) + 3) or not len(active):
        return None, active, "Insufficient cross-sectional variation"
    standardized = (attributions[:, active] - attributions[:, active].mean(axis=0)) / scales[active]
    design = np.column_stack([np.ones(len(standardized)), standardized])
    singular = np.linalg.svd(design, compute_uv=False)
    if singular[-1] <= CFG["rank_tol"] * singular[0]:
        return None, active, "Rank deficient"
    return design, active, "OK"


def quantile_fit(design, outcome, tau):
    scale = max(float(np.std(outcome)), 1e-4)
    fit = linprog(-outcome / scale, A_eq=sparse.csr_matrix(design.T),
                  b_eq=np.zeros(design.shape[1]), bounds=(tau - 1, tau), method="highs",
                  options={"presolve": True, "time_limit": CFG["qr_time_limit"],
                           "primal_feasibility_tolerance": 1e-8,
                           "dual_feasibility_tolerance": 1e-8})
    if not fit.success:
        return None, str(fit.message)
    beta = -np.asarray(fit.eqlin.marginals) * scale
    residual = outcome - design @ beta
    primal = float(np.maximum(tau * residual, (tau - 1) * residual).sum())
    dual = float(-fit.fun * scale)
    if not np.isfinite(beta).all() or abs(primal - dual) > 1e-5 * max(1.0, abs(primal), abs(dual)):
        return None, "Primal-dual objective gap"
    return beta, "OK"


def transform_inputs(preprocessor, x):
    imputer, transformer = preprocessor
    return np.asarray(transformer.transform(imputer.transform(x)), np.float32)


def save_joblib(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".partial")
    joblib.dump(payload, temporary, compress=3)
    temporary.replace(path)


def new_estimator(kind, parameter, seed, rows):
    if kind == "LR":
        return LinearRegression(fit_intercept=True)
    if kind == "XGB":
        return XGBRegressor(n_estimators=int(parameter), max_depth=CFG["depth"],
            learning_rate=CFG["learning_rate"], objective="reg:squarederror", tree_method="hist",
            device="cpu", subsample=CFG["subsample"], colsample_bytree=CFG["colsample"],
            reg_lambda=1.0, random_state=seed, n_jobs=CFG["n_jobs"])
    return MLPRegressor(hidden_layer_sizes=tuple(CFG["mlp_hidden"]), activation="relu",
        solver="adam", alpha=CFG["mlp_alpha"], learning_rate_init=CFG["mlp_learning_rate"],
        batch_size=min(CFG["mlp_batch_size"], rows), max_iter=1, shuffle=True,
        early_stopping=False, random_state=seed)


def fit_selected_payload(kind, x_train, y_train, x_valid, y_valid, x_pretest, y_pretest,
                         seed, empirical=False):
    """Run the main validation rule once, then freeze the selected predictor."""
    y_train, y_valid, y_pretest = [np.asarray(y, float) for y in [y_train, y_valid, y_pretest]]
    tuning = []
    if kind == "MLP":
        location, scale = float(y_train.mean()), max(float(y_train.std()), 1e-12)
        candidate = new_estimator(kind, None, seed, len(y_train))
        normalized_y = (y_train - location) / scale
        for epoch in range(1, max(CFG["mlp_epochs"]) + 1):
            candidate.partial_fit(x_train, normalized_y)
            if epoch in CFG["mlp_epochs"]:
                predicted = location + scale * candidate.predict(x_valid)
                tuning.append({"parameter": "epochs", "value": epoch,
                               "valid_mse": float(np.mean((y_valid - predicted) ** 2))})
    else:
        for parameter in ([0] if kind == "LR" else CFG["trees"]):
            candidate = new_estimator(kind, parameter, seed, len(y_train))
            candidate.fit(x_train, y_train)
            predicted = FrozenPredictor({"estimator": candidate}, kind, empirical).predict(x_valid)
            tuning.append({"parameter": "none" if kind == "LR" else "trees", "value": parameter,
                           "valid_mse": float(np.mean((y_valid - predicted) ** 2))})
    best = min(range(len(tuning)), key=lambda position: tuning[position]["valid_mse"])
    for position, row in enumerate(tuning):
        row["selected"] = position == best
    selected = tuning[best]["value"]
    estimator = new_estimator(kind, selected, seed, len(y_pretest))
    location, scale = 0.0, 1.0
    if kind == "MLP":
        location, scale = float(y_pretest.mean()), max(float(y_pretest.std()), 1e-12)
        normalized_y = (y_pretest - location) / scale
        for _ in range(int(selected)):
            estimator.partial_fit(x_pretest, normalized_y)
    else:
        estimator.fit(x_pretest, y_pretest)
    return {"estimator": estimator, "model": kind, "kind": kind,
            "target_mean": location, "target_scale": scale,
            "selected_parameter": selected, "tuning": tuning}


def simulation_scaler(raw, dates, rho, run_seed):
    if USE_MAIN1:
        for kind in CFG["models"]:
            member = f"tables/{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}/model.joblib"
            if MAIN1.has(member):
                return MAIN1.read_joblib(member)["preprocessor"]
    path = MODEL_CACHE_DIR / "synthetic" / f"rho{rho:.2f}_s{run_seed}.scaler.joblib"
    if path.is_file():
        return joblib.load(path)
    names = [f"X{j + 1}" for j in range(CFG["k"])]
    scaler = StandardScaler().fit(pd.DataFrame(raw[dates < CFG["train_months"]], columns=names))
    save_joblib(path, scaler)
    return scaler


def simulation_model(kind, rho, run_seed, case_id, transformed, response, dates, scaler):
    member = f"tables/{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}/model.joblib"
    if USE_MAIN1 and MAIN1.has(member):
        return MAIN1.read_joblib(member), member, "Reused main fitted model"
    path = MODEL_CACHE_DIR / "synthetic" / f"{kind}_rho{rho:.2f}_s{run_seed}.model.joblib"
    if path.is_file():
        return joblib.load(path), str(path), "Reused local fitted-model cache"
    tick = time.perf_counter()
    train = np.flatnonzero(dates < CFG["train_months"])
    valid = np.flatnonzero((dates >= CFG["train_months"])
                           & (dates < CFG["train_months"] + CFG["valid_months"]))
    pretest = np.r_[train, valid]
    payload = fit_selected_payload(kind, transformed[train], response[train], transformed[valid],
        response[valid], transformed[pretest], response[pretest],
        seed_for(run_seed, 200, case_id, MODEL_CODES[kind]))
    payload.update({"preprocessor": scaler, "features": [f"X{j + 1}" for j in range(CFG["k"])]})
    save_joblib(path, payload)
    log("Fit", f"Synthetic {kind}, rho={rho:.2f}, seed={run_seed}: {time.perf_counter() - tick:.1f}s; cached.")
    return payload, str(path), "Fitted main protocol once and cached"


def fit_empirical_preprocessor(x, seed):
    imputer = SimpleImputer(strategy="median")
    filled = imputer.fit_transform(x)
    transformer = QuantileTransformer(n_quantiles=min(1000, len(x)), output_distribution="normal",
        subsample=min(100000, len(x)), random_state=seed)
    transformer.fit(filled)
    return imputer, transformer


def empirical_fold(year, x_raw):
    pretest, test = annual_indices(year)
    anchor = pd.Period(f"{year}-01", freq="M")
    validation_start = anchor - CFG["validation_months"]
    cutoff = anchor - CFG["purge_months"]
    training_start = pd.Period(CFG["train_start"], freq="M")
    train = np.flatnonzero((FRENCH_DATES >= training_start) & (FRENCH_DATES < validation_start))
    valid = np.flatnonzero((FRENCH_DATES >= validation_start) & (FRENCH_DATES < cutoff))
    if not len(train) or not len(valid):
        raise ValueError(f"Training and validation observations are required for {year}.")
    stem = f"models/LR/s{CFG['seeds'][0]}_y{year}"
    reuse_main = False
    if USE_MAIN2 and MAIN2.has(stem + ".json") and MAIN2.has(stem + ".preprocessor.joblib"):
        metadata = MAIN2.read_json(stem + ".json")
        reuse_main = (int(metadata["n_pretest"]) == len(pretest)
                      and int(metadata["n_test"]) == len(test)
                      and metadata["pretest_end"] == str(FRENCH_DATES[pretest].max()))
    directory = MODEL_CACHE_DIR / "french" / str(year)
    final_path = directory / "final.preprocessor.joblib"
    if reuse_main:
        final = MAIN2.read_joblib(stem + ".preprocessor.joblib")
    elif final_path.is_file():
        final = joblib.load(final_path)
    else:
        final = fit_empirical_preprocessor(x_raw[pretest], seed_for(CFG["seed"], 713, year))
        save_joblib(final_path, final)
    return {"train": train, "valid": valid, "pretest": pretest, "test": test,
            "reuse_main": reuse_main, "final": final, "initial": None,
            "x_reference": transform_inputs(final, x_raw[pretest]),
            "x_test": transform_inputs(final, x_raw[test]), "directory": directory}


def empirical_model(kind, run_seed, year, x_raw, y, fold):
    member = f"models/{kind}/s{run_seed}_y{year}.model.joblib"
    if fold["reuse_main"] and MAIN2.has(member):
        return MAIN2.read_joblib(member), member, "Reused main fitted model"
    path = fold["directory"] / f"{kind}_s{run_seed}.model.joblib"
    if path.is_file():
        return joblib.load(path), str(path), "Reused local fitted-model cache"
    tick = time.perf_counter()
    if fold["initial"] is None:
        initial_path = fold["directory"] / "initial.preprocessor.joblib"
        if initial_path.is_file():
            fold["initial"] = joblib.load(initial_path)
        else:
            fold["initial"] = fit_empirical_preprocessor(x_raw[fold["train"]], seed_for(CFG["seed"], 703, year))
            save_joblib(initial_path, fold["initial"])
        fold["x_train"] = transform_inputs(fold["initial"], x_raw[fold["train"]])
        fold["x_valid"] = transform_inputs(fold["initial"], x_raw[fold["valid"]])
    payload = fit_selected_payload(kind, fold["x_train"], y[fold["train"]], fold["x_valid"],
        y[fold["valid"]], fold["x_reference"], y[fold["pretest"]],
        seed_for(run_seed, 704, year, MODEL_CODES[kind]), empirical=True)
    payload.update({"features": FEATURES, "year": int(year), "seed": int(run_seed),
                    "french_panel_signature": FRENCH_SIGNATURE})
    save_joblib(path, payload)
    log("Fit", f"French {kind}, seed={run_seed}, year={year}: {time.perf_counter() - tick:.1f}s; cached.")
    return payload, str(path), "Fitted main protocol once and cached"



# %% Cell 6: Synthetic data and integration diagnostics
def make_sim_panel(rho, run_seed):
    rng = np.random.default_rng(seed_for(run_seed, 100))
    nt = CFG["train_months"] + CFG["valid_months"] + CFG["test_months"]
    covariance = (1 - rho) * np.eye(CFG["k"]) + rho * np.ones((CFG["k"], CFG["k"]))
    innovations = rng.standard_normal((nt, CFG["n_assets"], CFG["k"])) @ np.linalg.cholesky(covariance).T
    x = np.empty_like(innovations)
    x[0] = innovations[0]
    for month in range(1, nt):
        x[month] = CFG["x_ar"] * x[month - 1] + np.sqrt(1 - CFG["x_ar"] ** 2) * innovations[month]
    flat = x.reshape(-1, CFG["k"])
    coefficient = np.array([0.7, -0.5, 0.35, 0.2, -0.15, 0.1])
    signal = flat @ coefficient + 0.45 * np.sin(flat[:, 0]) + 0.3 * (flat[:, 2] ** 2 - 1) + 0.35 * flat[:, 3] * flat[:, 4]
    response = signal + rng.standard_normal(len(flat)) * CFG["train_noise"] * (0.7 + 0.3 * np.abs(flat[:, 0]))
    dates = np.repeat(np.arange(nt), CFG["n_assets"])
    return flat, response, dates, covariance



def balanced_diagnostic_rows(dates, requested, seed):
    """Allocate a fixed observation budget across the complete test calendar."""
    dates = np.asarray(dates).astype(str)
    months = np.unique(dates)
    requested = min(int(requested), len(dates))
    rng = np.random.default_rng(seed)
    if requested < len(months):
        month_positions = np.rint(np.linspace(0, len(months) - 1, requested)).astype(int)
        selected = [int(rng.choice(np.flatnonzero(dates == months[i]))) for i in month_positions]
    else:
        counts = np.full(len(months), requested // len(months), int)
        counts[:requested % len(months)] += 1
        selected = []
        for month, count in zip(months, counts):
            available = np.flatnonzero(dates == month)
            selected.extend(rng.choice(available, min(int(count), len(available)), replace=False).tolist())
        if len(selected) < requested:
            remaining = np.setdiff1d(np.arange(len(dates)), selected)
            selected.extend(rng.choice(remaining, requested - len(selected), replace=False).tolist())
    return np.sort(np.asarray(selected, int))


def diagnostic_loss(values, reference):
    # Interior prefixes isolate conditional integration at the fixed baseline.
    error = values[:, 1:-1] - reference[:, 1:-1]
    delta = reference[:, -1, None] - reference[:, 1:-1]
    attribution, target = np.diff(values, axis=1), np.diff(reference, axis=1)
    error_sum = float(np.square(error).sum())
    delta_sum = float(np.square(delta).sum())
    attribution_error = float(np.square(attribution - target).sum())
    attribution_energy = float(np.square(target).sum())
    return {"rows": len(values), "prefix_cells": int(error.size),
        "prefix_squared_error_sum": error_sum, "reference_delta_squared_sum": delta_sum,
        "attribution_squared_error_sum": attribution_error,
        "reference_attribution_squared_sum": attribution_energy,
        "prefix_infid": error_sum / delta_sum if delta_sum > 1e-16 else np.nan,
        "prefix_rmse": float(np.sqrt(error_sum / error.size)) if error.size else np.nan,
        "attribution_nrmse": float(np.sqrt(attribution_error / attribution_energy))
                              if attribution_energy > 1e-16 else np.nan}


def integration_diagnostic(geometry, predictor, baseline, x, stream, reference_stream, repeat_stream):
    """Use independent reference draws and three paired integration repetitions."""
    estimated = BudgetGaussianCOLA(geometry, predictor, baseline)
    reference_explainer = BudgetGaussianCOLA(geometry, predictor, baseline, analytical=predictor.kind == "LR")
    tick = time.perf_counter()
    reference_values = reference_explainer.values(x, CFG["diagnostic_reference_draws"],
                                                 reference_stream, "Antithetic")
    timing = [{"stage": "Diagnostic reference", "sampler": "Analytical" if predictor.kind == "LR" else "Antithetic",
        "draws": 0 if predictor.kind == "LR" else CFG["diagnostic_reference_draws"],
        "repeat": None, "rows": len(x), "elapsed_seconds": time.perf_counter() - tick,
        "conditional_prediction_rows": 0 if predictor.kind == "LR" else len(x) * (len(FEATURES) - 1) * CFG["diagnostic_reference_draws"]}]
    rows, all_values = [], []
    for repeat in range(CFG["diagnostic_repetitions"]):
        current_stream = stream if repeat == 0 else seed_for(repeat_stream, repeat)
        repeated_values = []
        for sampler in SAMPLERS:
            tick = time.perf_counter()
            values = estimated.multi_values(x, CFG["diagnostic_budgets"], current_stream, sampler)
            timing.append({"stage": "Diagnostic nested estimates", "sampler": sampler,
                "draws": max(CFG["diagnostic_budgets"]), "repeat": repeat, "rows": len(x),
                "elapsed_seconds": time.perf_counter() - tick,
                "conditional_prediction_rows": len(x) * (len(FEATURES) - 1) * max(CFG["diagnostic_budgets"])})
            for budget in CFG["diagnostic_budgets"]:
                rows.append({"sampler": sampler, "draws": budget, "repeat": repeat,
                             **diagnostic_loss(values[budget], reference_values)})
            repeated_values.append(np.stack([values[budget] for budget in CFG["diagnostic_budgets"]]))
        all_values.append(np.stack(repeated_values))
    return rows, timing, reference_values, np.stack(all_values)


def comparison_with_main(attribution, main):
    output = []
    for j in range(attribution.shape[1]):
        current, baseline = attribution[:, j], main[:, j]
        baseline_sd, current_sd = float(baseline.std()), float(current.std())
        output.append({"feature_index_one_based": j + 1,
            "correlation_with_main": float(np.corrcoef(current, baseline)[0, 1])
                if min(baseline_sd, current_sd) > 1e-12 else np.nan,
            "nrmse_from_main": float(np.sqrt(np.mean((current - baseline) ** 2))) / baseline_sd
                if baseline_sd > 1e-12 else np.nan})
    return output



def run_synthetic():
    metric_rows, condition_rows, diagnostic_rows, timing_rows, sensitivity_rows = [], [], [], [], []
    for run_seed in tqdm(CFG["seeds"], desc="Synthetic run seeds"):
        for case_id, rho in enumerate(CFG["rho"]):
            raw, response, dates, _ = make_sim_panel(rho, run_seed)
            pretest_end = CFG["train_months"] + CFG["valid_months"]
            pretest_index, test_index = np.flatnonzero(dates < pretest_end), np.flatnonzero(dates >= pretest_end)
            scaler = simulation_scaler(raw, dates, rho, run_seed)
            names = [f"X{j + 1}" for j in range(CFG["k"])]
            transformed = scaler.transform(pd.DataFrame(raw, columns=names))
            x_reference, x_test = transformed[pretest_index], transformed[test_index]
            geometry = fitted_geometry(x_reference)
            test_dates, test_response = dates[test_index], response[test_index]
            unique_months = np.unique(test_dates)
            selected = balanced_diagnostic_rows(test_dates, CFG["diagnostic_rows"], seed_for(run_seed, 400, case_id))
            for kind in CFG["models"]:
                tag = f"{kind}_Nonlinear_rho{rho:.2f}_s{run_seed}"
                predictor, main_attribution, baseline = None, None, None
                model_source, model_action = None, None
                for variant, settings in VARIANTS.items():
                    sampler, budget = settings["sampler"], settings["draws"]
                    path = CHECK_DIR / "synthetic" / tag / f"{variant}.npz"
                    if path.is_file():
                        with np.load(path, allow_pickle=False) as saved:
                            if not np.array_equal(saved["row_index"], test_index):
                                raise ValueError(f"Checkpoint row alignment differs for {tag}, {variant}.")
                            row = json.loads(str(saved["metrics"]))
                            condition, attribution = saved["condition"], saved["attribution"]
                            stored_baseline = float(saved["baseline"])
                        baseline = stored_baseline
                    else:
                        if predictor is None:
                            payload, model_source, model_action = simulation_model(
                                kind, rho, run_seed, case_id, transformed, response, dates, scaler)
                            predictor = FrozenPredictor(payload, kind)
                            baseline = shared_baseline(geometry, predictor, CFG["simulation_base_draws"],
                                                       seed_for(run_seed, 300, case_id))
                        explainer = BudgetGaussianCOLA(geometry, predictor, baseline)
                        tick = time.perf_counter()
                        attribution, values = explainer.explain(x_test, budget, seed_for(run_seed, 942, case_id), sampler)
                        elapsed = time.perf_counter() - tick
                        prediction = values[:, -1]
                        condition = np.array([full_condition_number(attribution[test_dates == month]) for month in unique_months])
                        residual = prediction - baseline - attribution.sum(axis=1)
                        row = {"model": kind, "seed": run_seed, "rho": rho, "variant": variant,
                            "sampler": sampler, "draws": budget,
                            "median_condition": float(np.quantile(condition, 0.5, method="inverted_cdf")),
                            "reconstruction_nrmse": float(np.sqrt(np.mean(residual ** 2))) / max(float(prediction.std()), 1e-12),
                            "prediction_mse": float(np.mean((test_response - prediction) ** 2)),
                            "infinite_condition_months": int(np.isinf(condition).sum()),
                            "explanation_seconds": elapsed, "conditional_prediction_rows": len(x_test) * (CFG["k"] - 1) * budget,
                            "rows": len(x_test), "months": len(unique_months)}
                        save_npz(path, metrics=np.array(json.dumps(row)), condition=condition,
                            attribution=attribution, prediction=prediction, baseline=np.array(baseline),
                            row_index=test_index, test_date=test_dates)
                        log("Synthetic", f"{tag}, {variant}: {elapsed:.1f}s")
                    if variant == MAIN_VARIANT:
                        main_attribution = attribution.copy()
                    for comparison in comparison_with_main(attribution, main_attribution):
                        j = comparison["feature_index_one_based"] - 1
                        sensitivity_rows.append({"model": kind, "seed": run_seed, "rho": rho,
                            "variant": variant, "sampler": sampler, "draws": budget,
                            "feature": names[j], **comparison})
                    metric_rows.append(row)
                    for month, value in zip(unique_months, condition):
                        condition_rows.append({"model": kind, "seed": run_seed, "rho": rho,
                            "variant": variant, "sampler": sampler, "draws": budget,
                            "test_month": int(month - pretest_end), "condition": float(value)})
                diagnostic_path = CHECK_DIR / "synthetic" / tag / "integration_diagnostic.npz"
                if diagnostic_path.is_file():
                    with np.load(diagnostic_path, allow_pickle=False) as saved:
                        if not np.array_equal(saved["row_index"], test_index[selected]):
                            raise ValueError(f"Diagnostic row alignment differs for {tag}.")
                        local_diagnostics = json.loads(str(saved["metrics"]))
                        local_timing = json.loads(str(saved["timing"]))
                else:
                    if predictor is None:
                        payload, model_source, model_action = simulation_model(
                            kind, rho, run_seed, case_id, transformed, response, dates, scaler)
                        predictor = FrozenPredictor(payload, kind)
                        baseline = shared_baseline(geometry, predictor, CFG["simulation_base_draws"],
                                                   seed_for(run_seed, 300, case_id))
                    local_diagnostics, local_timing, reference_values, estimates = integration_diagnostic(
                        geometry, predictor, baseline, x_test[selected], seed_for(run_seed, 942, case_id),
                        seed_for(run_seed, 944, case_id), seed_for(run_seed, 945, case_id))
                    save_npz(diagnostic_path, metrics=np.array(json.dumps(local_diagnostics)),
                        timing=np.array(json.dumps(local_timing)), reference_values=reference_values,
                        estimates=estimates, row_index=test_index[selected], selected_rows=selected)
                common = {"model": kind, "seed": run_seed, "rho": rho}
                diagnostic_rows.extend([{**common, **row} for row in local_diagnostics])
                timing_rows.extend([{"scope": "Synthetic", **common, **row} for row in local_timing])
                MODEL_ROWS.append({"scope": "Synthetic", **common,
                    "source": model_source or str(CHECK_DIR / "synthetic" / tag),
                    "action": model_action or "Resumed saved integration calculations"})
                del predictor, main_attribution
            gc.collect()
    return tuple(pd.DataFrame(rows) for rows in [metric_rows, condition_rows, diagnostic_rows, timing_rows, sensitivity_rows])


with threadpool_limits(limits=CFG["n_jobs"]):
    SIM_METRICS, SIM_CONDITION, SIM_DIAGNOSTIC, SIM_TIMING, SIM_SENSITIVITY = run_synthetic()
save_csv(SIM_METRICS, "simulation_per_model_seed")
save_csv(SIM_CONDITION, "simulation_monthly_conditioning")
save_csv(SIM_DIAGNOSTIC, "simulation_integration_diagnostics")
save_csv(SIM_SENSITIVITY, "simulation_attribution_sensitivity")

# %% Cell 7: French 100 with frozen annual prediction models
def annual_indices(year):
    anchor = pd.Period(f"{year}-01", freq="M")
    valid_start = anchor - CFG["validation_months"]
    cutoff = anchor - CFG["purge_months"]
    history_start = pd.Period(CFG["train_start"], freq="M")
    pretest = np.flatnonzero((FRENCH_DATES >= history_start) & (FRENCH_DATES < cutoff))
    test = np.flatnonzero((FRENCH_DATES >= anchor) & (FRENCH_DATES <= anchor + 11)
                          & (FRENCH_DATES >= TEST_MONTHS[0]) & (FRENCH_DATES <= TEST_MONTHS[-1]))
    if not len(pretest) or not len(test):
        raise ValueError(f"Empty French chronological split for {year}.")
    return pretest, test



french_test_rows = np.flatnonzero((FRENCH_DATES >= TEST_MONTHS[0]) & (FRENCH_DATES <= TEST_MONTHS[-1]))
diagnostic_local = balanced_diagnostic_rows(FRENCH_DATES[french_test_rows], CFG["diagnostic_rows"], seed_for(CFG["seed"], 1700))
FRENCH_DIAGNOSTIC_ROWS = french_test_rows[diagnostic_local]
diagnostic_selection = FRENCH.loc[FRENCH_DIAGNOSTIC_ROWS, ["id", "date", "return_date"]].copy()
diagnostic_selection.insert(0, "panel_row_index", FRENCH_DIAGNOSTIC_ROWS)
save_csv(diagnostic_selection, "french_diagnostic_observations")


def run_french():
    model_count, seed_count, month_count, k = len(CFG["models"]), len(CFG["seeds"]), len(TEST_MONTHS), len(FEATURES)
    fm = {key: np.full((model_count, seed_count, month_count, k), np.nan) for key in VARIANT_IDS}
    qr = {key: np.full((model_count, seed_count, month_count, len(CFG["quantiles"]), k), np.nan) for key in VARIANT_IDS}
    conditions = {key: np.full((model_count, seed_count, month_count), np.inf) for key in VARIANT_IDS}
    diagnostic_rows, reconstruction_rows, sensitivity_rows, timing_rows, integration_rows, split_rows = [], [], [], [], [], []
    x_raw, y = FRENCH[FEATURES].to_numpy(np.float32), FRENCH["y"].to_numpy(float)
    calendar_map = {str(month): i for i, month in enumerate(TEST_MONTHS)}
    for year in tqdm(sorted(set(TEST_MONTHS.year)), desc="French annual vintages"):
        fold = empirical_fold(year, x_raw)
        pretest_index, test_index = fold["pretest"], fold["test"]
        x_reference, x_test = fold["x_reference"], fold["x_test"]
        geometry = fitted_geometry(x_reference)
        year_months = [month for month in TEST_MONTHS if month.year == year]
        target_dates = FRENCH_DATES[test_index]
        month_rows = [np.flatnonzero(target_dates == month) for month in year_months]
        global_months = [calendar_map[str(month)] for month in year_months]
        diagnostic_mask = np.isin(test_index, FRENCH_DIAGNOSTIC_ROWS)
        split_rows.append({"year": year, "pretest_start": str(FRENCH_DATES[pretest_index].min()),
            "pretest_end": str(FRENCH_DATES[pretest_index].max()), "pretest_rows": len(pretest_index),
            "test_rows": len(test_index), "diagnostic_rows": int(diagnostic_mask.sum())})
        for mi, kind in enumerate(CFG["models"]):
            for si, run_seed in enumerate(CFG["seeds"]):
                tag = f"{kind}_s{run_seed}_y{year}"
                predictor, main_attribution, baseline = None, None, None
                model_source, model_action = None, None
                for variant, settings in VARIANTS.items():
                    sampler, budget = settings["sampler"], settings["draws"]
                    path = CHECK_DIR / "french" / tag / f"{variant}.npz"
                    if path.is_file():
                        with np.load(path, allow_pickle=False) as saved:
                            if not np.array_equal(saved["row_index"], test_index):
                                raise ValueError(f"Checkpoint row alignment differs for {tag}, {variant}.")
                            local_fm, local_qr, local_condition = saved["fm"], saved["qr"], saved["condition"]
                            attribution, baseline = saved["attribution"], float(saved["baseline"])
                            local_diagnostics = json.loads(str(saved["diagnostics"]))
                            local_reconstruction = json.loads(str(saved["reconstruction"]))
                            local_timing = json.loads(str(saved["timing"]))
                    else:
                        if predictor is None:
                            payload, model_source, model_action = empirical_model(kind, run_seed, year, x_raw, y, fold)
                            predictor = FrozenPredictor(payload, kind, empirical=True)
                            baseline = shared_baseline(geometry, predictor, CFG["empirical_base_draws"], seed_for(run_seed, 705, year))
                            prediction = predictor.predict(x_test)
                        explainer = BudgetGaussianCOLA(geometry, predictor, baseline)
                        local_fm = np.full((len(year_months), k), np.nan)
                        local_qr = np.full((len(year_months), len(CFG["quantiles"]), k), np.nan)
                        local_condition, attribution = np.full(len(year_months), np.inf), np.empty((len(test_index), k))
                        local_diagnostics, explanation_seconds, regression_seconds = [], 0.0, 0.0
                        for ti, (month, positions) in enumerate(zip(year_months, month_rows)):
                            tick = time.perf_counter()
                            attr, values = explainer.explain(x_test[positions], budget, seed_for(run_seed, 706, month.ordinal), sampler)
                            explanation_seconds += time.perf_counter() - tick
                            attribution[positions] = attr
                            tick = time.perf_counter()
                            local_condition[ti] = full_condition_number(attr, intercept=True)
                            design, active, status = monthly_design(attr)
                            common = {"model": kind, "seed": run_seed, "year": year, "return_date": str(month),
                                "variant": variant, "sampler": sampler, "draws": budget,
                                "rows": len(positions), "active_features": len(active)}
                            local_diagnostics.append({**common, "analysis": "FM", "tau": None, "status": status})
                            if design is not None:
                                beta = np.linalg.lstsq(design, y[test_index[positions]], rcond=CFG["rank_tol"])[0]
                                local_fm[ti, active] = beta[1:]
                            for qi, tau in enumerate(CFG["quantiles"]):
                                beta, result = (None, status) if design is None else quantile_fit(design, y[test_index[positions]], tau)
                                local_diagnostics.append({**common, "analysis": "QR", "tau": tau, "status": result})
                                if beta is not None:
                                    local_qr[ti, qi, active] = beta[1:]
                            regression_seconds += time.perf_counter() - tick
                        residual = prediction - baseline - attribution.sum(axis=1)
                        local_reconstruction = {"model": kind, "seed": run_seed, "year": year,
                            "variant": variant, "sampler": sampler, "draws": budget, "rows": len(test_index),
                            "squared_error": float(np.square(residual).sum()), "maximum_absolute_error": float(np.abs(residual).max())}
                        local_timing = {"scope": "French100", "stage": "Full-panel explanations", "model": kind,
                            "seed": run_seed, "year": year, "variant": variant, "sampler": sampler, "draws": budget,
                            "rows": len(test_index), "elapsed_seconds": explanation_seconds,
                            "regression_seconds": regression_seconds, "conditional_prediction_rows": len(test_index) * (k - 1) * budget}
                        save_npz(path, fm=local_fm, qr=local_qr, condition=local_condition,
                            attribution=attribution, prediction=prediction, baseline=np.array(baseline), row_index=test_index,
                            diagnostics=np.array(json.dumps(local_diagnostics)), reconstruction=np.array(json.dumps(local_reconstruction)),
                            timing=np.array(json.dumps(local_timing)))
                        log("French", f"{tag}, {variant}: explain={explanation_seconds:.1f}s, regress={regression_seconds:.1f}s")
                    if variant == MAIN_VARIANT:
                        main_attribution = attribution.copy()
                    for month, positions in zip(year_months, month_rows):
                        for comparison in comparison_with_main(attribution[positions], main_attribution[positions]):
                            j = comparison["feature_index_one_based"] - 1
                            sensitivity_rows.append({"model": kind, "seed": run_seed, "variant": variant,
                                "sampler": sampler, "draws": budget, "return_date": str(month), "feature": FEATURES[j], **comparison})
                    fm[variant][mi, si, global_months, :] = local_fm
                    qr[variant][mi, si, global_months, :, :] = local_qr
                    conditions[variant][mi, si, global_months] = local_condition
                    diagnostic_rows.extend(local_diagnostics)
                    reconstruction_rows.append(local_reconstruction)
                    timing_rows.append(local_timing)
                for month, positions in zip(year_months, month_rows):
                    selected_positions = positions[diagnostic_mask[positions]]
                    if not len(selected_positions):
                        continue
                    diagnostic_path = CHECK_DIR / "french" / tag / f"diagnostic_{month}.npz"
                    if diagnostic_path.is_file():
                        with np.load(diagnostic_path, allow_pickle=False) as saved:
                            if not np.array_equal(saved["row_index"], test_index[selected_positions]):
                                raise ValueError(f"Diagnostic row alignment differs for {tag}, {month}.")
                            local_metrics = json.loads(str(saved["metrics"]))
                            local_diagnostic_timing = json.loads(str(saved["timing"]))
                    else:
                        if predictor is None:
                            payload, model_source, model_action = empirical_model(kind, run_seed, year, x_raw, y, fold)
                            predictor = FrozenPredictor(payload, kind, empirical=True)
                            baseline = shared_baseline(geometry, predictor, CFG["empirical_base_draws"], seed_for(run_seed, 705, year))
                        local_metrics, local_diagnostic_timing, reference_values, estimates = integration_diagnostic(
                            geometry, predictor, baseline, x_test[selected_positions], seed_for(run_seed, 706, month.ordinal),
                            seed_for(run_seed, 770, month.ordinal), seed_for(run_seed, 771, month.ordinal))
                        save_npz(diagnostic_path, metrics=np.array(json.dumps(local_metrics)),
                            timing=np.array(json.dumps(local_diagnostic_timing)), reference_values=reference_values,
                            estimates=estimates, row_index=test_index[selected_positions])
                    common = {"model": kind, "seed": run_seed, "year": year, "return_date": str(month)}
                    integration_rows.extend([{**common, **row} for row in local_metrics])
                    timing_rows.extend([{"scope": "French100", **common, **row} for row in local_diagnostic_timing])
                MODEL_ROWS.append({"scope": "French100", "model": kind, "seed": run_seed, "year": year,
                    "source": model_source or str(CHECK_DIR / "french" / tag),
                    "action": model_action or "Resumed saved integration calculations"})
                del predictor, main_attribution
        save_csv(pd.DataFrame(split_rows), "french_annual_splits")
        save_csv(pd.DataFrame(EVENTS), "events")
        gc.collect()
    return fm, qr, conditions, tuple(pd.DataFrame(rows) for rows in [diagnostic_rows, reconstruction_rows,
                                                                  sensitivity_rows, timing_rows, integration_rows])


with threadpool_limits(limits=CFG["n_jobs"]):
    EMP_FM, EMP_QR, EMP_CONDITION, french_frames = run_french()
EMP_DIAGNOSTICS, EMP_RECONSTRUCTION, EMP_SENSITIVITY, EMP_TIMING, EMP_INTEGRATION = french_frames
save_csv(EMP_DIAGNOSTICS, "french_analysis_diagnostics")
save_csv(EMP_RECONSTRUCTION, "french_reconstruction_by_vintage")
save_csv(EMP_SENSITIVITY, "french_attribution_sensitivity")
save_csv(EMP_INTEGRATION, "french_integration_diagnostics_by_month")

# %% Cell 8: Paired summaries, convergence diagnostics and inference
def percentile_bounds(values):
    tail = (1 - BS["level"]) / 2
    return np.quantile(values, [tail, 1 - tail], method="inverted_cdf")


run_ids = sorted(CFG["seeds"])
run_rng = np.random.default_rng(seed_for(CFG["seed"], 950))
RUN_INDEX = run_rng.integers(0, len(run_ids), size=(BS["simulation_reps"], len(run_ids)))
simulation_rows, simulation_contrasts = [], []
for rho in CFG["rho"]:
    for metric in ["median_condition", "reconstruction_nrmse", "explanation_seconds"]:
        paired = {}
        for variant, settings in VARIANTS.items():
            values = []
            for run_seed in run_ids:
                block = SIM_METRICS[SIM_METRICS["rho"].eq(rho) & SIM_METRICS["seed"].eq(run_seed) & SIM_METRICS["variant"].eq(variant)]
                if set(block["model"]) != set(CFG["models"]):
                    raise ValueError("Every synthetic aggregate requires all three prediction models.")
                values.append(float(block[metric].to_numpy(float).mean()))
            values = np.asarray(values)
            paired[variant] = values
            lo, hi = percentile_bounds(values[RUN_INDEX].mean(axis=1))
            simulation_rows.append({"rho": rho, "variant": variant, **settings, "metric": metric,
                "mean": float(values.mean()), "lo": float(lo), "hi": float(hi), "runs": len(values)})
        for variant in VARIANT_IDS:
            if variant == MAIN_VARIANT:
                continue
            with np.errstate(invalid="ignore"):
                difference = paired[variant] - paired[MAIN_VARIANT]
            if np.isnan(difference).any():
                mean, lo, hi = np.nan, np.nan, np.nan
            else:
                mean = float(difference.mean())
                lo, hi = map(float, percentile_bounds(difference[RUN_INDEX].mean(axis=1)))
            simulation_contrasts.append({"rho": rho, "metric": metric, "variant": variant,
                "comparison_variant": MAIN_VARIANT, "mean": mean, "lo": lo, "hi": hi})
SIM_SUMMARY = pd.DataFrame(simulation_rows)
save_csv(SIM_SUMMARY, "simulation_full_panel_summary")
save_csv(pd.DataFrame(simulation_contrasts), "simulation_paired_differences")


def pool_diagnostic(frame, keys):
    totals = ["rows", "prefix_cells", "prefix_squared_error_sum", "reference_delta_squared_sum",
              "attribution_squared_error_sum", "reference_attribution_squared_sum"]
    pooled = frame.groupby(keys, as_index=False)[totals].sum()
    pooled["prefix_infid"] = pooled["prefix_squared_error_sum"] / pooled["reference_delta_squared_sum"].where(
        pooled["reference_delta_squared_sum"] > 1e-16)
    pooled["prefix_rmse"] = np.sqrt(pooled["prefix_squared_error_sum"] / pooled["prefix_cells"])
    pooled["attribution_nrmse"] = np.sqrt(pooled["attribution_squared_error_sum"] / pooled["reference_attribution_squared_sum"].where(
        pooled["reference_attribution_squared_sum"] > 1e-16))
    return pooled


# Pool selected months within each fitted model/seed pipeline before averaging.
EMP_INTEGRATION_POOLED = pool_diagnostic(EMP_INTEGRATION, ["model", "seed", "sampler", "draws", "repeat"])
save_csv(EMP_INTEGRATION_POOLED, "french_integration_diagnostics")
CONVERGENCE_ROWS = []
for scope, frame in [("Synthetic", SIM_DIAGNOSTIC), ("French100", EMP_INTEGRATION_POOLED)]:
    for sampler in SAMPLERS:
        for budget in CFG["diagnostic_budgets"]:
            block = frame[frame["sampler"].eq(sampler) & frame["draws"].eq(budget)]
            for metric in ["prefix_infid", "prefix_rmse", "attribution_nrmse"]:
                # Integration repetitions are averaged inside each model/seed/case.
                grouping = ["seed", "model"] + (["rho"] if scope == "Synthetic" else [])
                pipeline = block.groupby(grouping, as_index=False)[metric].mean()
                seed_values = pipeline.groupby("seed")[metric].mean().reindex(run_ids).to_numpy(float)
                lo, hi = percentile_bounds(seed_values[RUN_INDEX].mean(axis=1))
                CONVERGENCE_ROWS.append({"scope": scope, "sampler": sampler, "draws": budget, "metric": metric,
                    "mean": float(seed_values.mean()), "lo": float(lo), "hi": float(hi),
                    "models": len(CFG["models"]), "runs": len(run_ids), "integration_repetitions": CFG["diagnostic_repetitions"],
                    "diagnostic_reference_draws": CFG["diagnostic_reference_draws"]})
CONVERGENCE = pd.DataFrame(CONVERGENCE_ROWS)
save_csv(CONVERGENCE, "integration_convergence_summary")
repeat_sensitivity = []
for scope, frame in [("Synthetic", SIM_DIAGNOSTIC), ("French100", EMP_INTEGRATION_POOLED)]:
    keys = ["model", "seed", "sampler", "draws"] + (["rho"] if scope == "Synthetic" else [])
    grouped = frame.groupby(keys, as_index=False).agg(
        mean_prefix_infid=("prefix_infid", "mean"), sd_prefix_infid=("prefix_infid", "std"),
        mean_attribution_nrmse=("attribution_nrmse", "mean"), sd_attribution_nrmse=("attribution_nrmse", "std"),
        repetitions=("repeat", "count"))
    grouped.insert(0, "scope", scope)
    repeat_sensitivity.append(grouped)
save_csv(pd.concat(repeat_sensitivity, ignore_index=True), "integration_repeat_sensitivity")
synthetic_full_timing = SIM_METRICS[["model", "seed", "rho", "variant", "sampler", "draws", "rows",
                                    "explanation_seconds", "conditional_prediction_rows"]].rename(columns={"explanation_seconds": "elapsed_seconds"})
synthetic_full_timing.insert(0, "scope", "Synthetic")
synthetic_full_timing["stage"] = "Full-panel explanations"
TIMING = pd.concat([synthetic_full_timing, SIM_TIMING, EMP_TIMING], ignore_index=True)
save_csv(TIMING, "observed_computation_times")

def stationary_indices(months, repetitions, seed):
    length = max(2, int(round(months ** (1 / 3)))) if BS["block"] is None else int(BS["block"])
    length = min(max(1, length), months)
    rng = np.random.default_rng(seed)
    index = np.empty((repetitions, months), int)
    index[:, 0] = rng.integers(0, months, repetitions)
    for t in range(1, months):
        restart = rng.random(repetitions) < 1 / length
        index[:, t] = np.where(restart, rng.integers(0, months, repetitions), (index[:, t - 1] + 1) % months)
    return index, length


def summarize_monthly(series, resampling):
    series = np.asarray(series, float)
    count = int(np.isfinite(series).sum())
    output = {"mean": float(series[np.isfinite(series)].mean()) if count else np.nan,
              "se": np.nan, "lo": np.nan, "hi": np.nan, "p": np.nan,
              "months": count, "bootstrap_valid": 0, "status": "Few supported months"}
    if count < BS["min_months"]:
        return output
    samples = series[resampling]
    finite = np.isfinite(samples)
    denominator = finite.sum(axis=1)
    draws = np.full(len(samples), np.nan)
    np.divide(np.where(finite, samples, 0).sum(axis=1), denominator, out=draws,
              where=denominator >= max(3, BS["min_months"] // 2))
    draws = draws[np.isfinite(draws)]
    output["bootstrap_valid"] = len(draws)
    if len(draws) < BS["min_valid_share"] * len(resampling):
        output["status"] = "Sparse supported resamples"
        return output
    output["lo"], output["hi"] = map(float, percentile_bounds(draws))
    output["se"] = float(draws.std(ddof=1))
    exceedances = int(np.sum(np.abs(draws - output["mean"]) >= abs(output["mean"])))
    output["p"] = (1 + exceedances) / (1 + len(draws))
    output["status"] = "OK"
    return output


def holm_adjust(pvalues):
    values = np.asarray(pvalues, float)
    filled = np.where(np.isfinite(values), values, 1.0)
    order = np.argsort(filled, kind="stable")
    adjusted = np.minimum(1.0, np.maximum.accumulate(filled[order] * np.arange(len(values), 0, -1)))
    output = np.empty(len(values))
    output[order] = adjusted
    output[~np.isfinite(values)] = np.nan
    return output


def in_basis_points(frame):
    frame = frame.copy()
    for column in ["mean", "se", "lo", "hi"]:
        frame[column] *= CFG["bps"]
    return frame



BOOT_INDEX, BLOCK_LENGTH = stationary_indices(len(TEST_MONTHS), BS["empirical_reps"], seed_for(CFG["seed"], 960))
log("Inference", f"Paired stationary month bootstrap: {BS['empirical_reps']} draws; mean block={BLOCK_LENGTH}.")
analyses = [("FM", None)] + [("QR", tau) for tau in CFG["quantiles"]]
variant_rows, matched_rows, contrast_rows, model_rows, monthly_rows, condition_rows = [], [], [], [], [], []
for j, feature in enumerate(FEATURES):
    for analysis, tau in analyses:
        aggregate_series = {}
        for variant, settings in VARIANTS.items():
            values = EMP_FM[variant][:, :, :, j] if analysis == "FM" else EMP_QR[variant][:, :, :, CFG["quantiles"].index(tau), j]
            series = np.mean(values, axis=(0, 1))
            aggregate_series[variant] = series
            common = {"variant": variant, **settings, "feature": feature, "analysis": analysis, "tau": tau}
            variant_rows.append({**common, **summarize_monthly(series, BOOT_INDEX)})
            for mi, kind in enumerate(CFG["models"]):
                model_rows.append({**common, "model": kind, **summarize_monthly(values[mi].mean(axis=0), BOOT_INDEX)})
            for ti, month in enumerate(TEST_MONTHS):
                monthly_rows.append({**common, "return_date": str(month), "coefficient": float(series[ti]),
                    "supported_model_seed_pairs": int(np.isfinite(values[:, :, ti]).sum()),
                    "expected_model_seed_pairs": len(CFG["models"]) * len(CFG["seeds"])})
        support = np.logical_and.reduce([np.isfinite(aggregate_series[key]) for key in VARIANT_IDS])
        for variant, settings in VARIANTS.items():
            matched_rows.append({"variant": variant, **settings, "feature": feature, "analysis": analysis,
                "tau": tau, **summarize_monthly(np.where(support, aggregate_series[variant], np.nan), BOOT_INDEX)})
        # Three contrasts with the main antithetic 16-draw configuration.
        # Two within-sampler budget contrasts isolate 64-minus-16 draw changes.
        comparisons = [(key, MAIN_VARIANT, "Versus main") for key in VARIANT_IDS if key != MAIN_VARIANT]
        comparisons += [(f"{sampler}_64", f"{sampler}_16", "Within-sampler budget") for sampler in SAMPLERS]
        for current, baseline, family in comparisons:
            difference = np.where(support, aggregate_series[current] - aggregate_series[baseline], np.nan)
            contrast_rows.append({"variant": current, "comparison_variant": baseline, "family": family,
                "feature": feature, "analysis": analysis, "tau": tau, **summarize_monthly(difference, BOOT_INDEX)})

EMP_SUMMARY = pd.DataFrame(variant_rows)
EMP_MATCHED = pd.DataFrame(matched_rows)
EMP_DIFFERENCES = pd.DataFrame(contrast_rows)
LEVEL_FAMILY = len(VARIANTS) * len(FEATURES) * len(analyses)
EMP_SUMMARY["p_holm_levels"] = holm_adjust(EMP_SUMMARY["p"].to_numpy())
EMP_MATCHED["p_holm_levels"] = holm_adjust(EMP_MATCHED["p"].to_numpy())
EMP_SUMMARY["holm_family_size"] = LEVEL_FAMILY
EMP_MATCHED["holm_family_size"] = LEVEL_FAMILY
EMP_DIFFERENCES["p_holm_family"] = np.nan
EMP_DIFFERENCES["p_holm_focal"] = np.nan
EMP_DIFFERENCES["holm_family_size"] = 0
for family in EMP_DIFFERENCES["family"].unique():
    mask = EMP_DIFFERENCES["family"].eq(family)
    EMP_DIFFERENCES.loc[mask, "p_holm_family"] = holm_adjust(EMP_DIFFERENCES.loc[mask, "p"].to_numpy())
    EMP_DIFFERENCES.loc[mask, "holm_family_size"] = int(mask.sum())
    focal = mask & EMP_DIFFERENCES["feature"].eq(CFG["focal_feature"])
    EMP_DIFFERENCES.loc[focal, "p_holm_focal"] = holm_adjust(EMP_DIFFERENCES.loc[focal, "p"].to_numpy())
for variant, settings in VARIANTS.items():
    for mi, kind in enumerate(CFG["models"]):
        for si, run_seed in enumerate(CFG["seeds"]):
            for ti, month in enumerate(TEST_MONTHS):
                condition_rows.append({"variant": variant, **settings, "model": kind, "seed": run_seed,
                    "return_date": str(month), "condition": float(EMP_CONDITION[variant][mi, si, ti]),
                    "weight": 1 / (len(CFG["models"]) * len(CFG["seeds"]) * len(TEST_MONTHS))})
EMP_CONDITION_TABLE = pd.DataFrame(condition_rows)
save_csv(in_basis_points(EMP_SUMMARY), "french_integration_summary_bp")
save_csv(in_basis_points(EMP_MATCHED), "french_matched_integration_summary_bp")
save_csv(in_basis_points(EMP_DIFFERENCES), "french_paired_integration_differences_bp")
save_csv(in_basis_points(pd.DataFrame(model_rows)), "french_summary_by_model_bp")
save_csv(pd.DataFrame(monthly_rows), "french_aggregate_monthly_coefficients")
save_csv(EMP_CONDITION_TABLE, "french_conditioning_distribution")
conditioning_summary = []
for (variant, kind), block in EMP_CONDITION_TABLE.groupby(["variant", "model"], sort=False):
    values = block["condition"].to_numpy(float)
    q25, median, q75 = np.quantile(values, [0.25, 0.5, 0.75], method="inverted_cdf")
    conditioning_summary.append({"variant": variant, "model": kind, "q25": q25, "median": median, "q75": q75,
        "requested_model_seed_months": len(values), "infinite_model_seed_months": int(np.isinf(values).sum())})
save_csv(pd.DataFrame(conditioning_summary), "french_conditioning_summary_by_model")
save_csv(pd.DataFrame(MODEL_ROWS), "fitted_model_sources")
save_csv(pd.DataFrame(SOURCE_ROWS), "main_output_sources")

# %% Cell 9: One four-panel figure with a shared top legend
def place_legend_header(fig, axes, handles, ncol=3, hspace=0.50, wspace=0.38):
    """Preserve the physical panel canvas and add a measured legend header."""
    # Layout engines can override subplots_adjust or ignore figure legends.
    # Use one explicit physical layout for both saved files and inline figures.
    with mpl.rc_context({"figure.constrained_layout.use": False, "figure.autolayout": False}):
        fig.set_layout_engine(None)
    base_width, base_height = map(float, fig.get_size_inches())
    panel_axes = list(np.asarray(axes, dtype=object).ravel())
    side_pad, bottom_pad, top_pad, legend_gap = 0.12, 0.08, 0.12, 0.18
    fig.subplots_adjust(left=0.12, right=0.98, bottom=0.64 / base_height,
                        top=(base_height - 0.34) / base_height,
                        hspace=hspace, wspace=wspace)
    panel_rectangles = [
        (ax.get_position().x0 * base_width, ax.get_position().y0 * base_height,
         ax.get_position().width * base_width, ax.get_position().height * base_height)
        for ax in panel_axes
    ]
    columns = min(max(1, int(ncol)), len(handles))
    legend = None
    while True:
        if legend is not None:
            legend.remove()
        legend = fig.legend(
            handles=handles, loc="upper center", bbox_to_anchor=(0.5, 1.0),
            bbox_transform=fig.transFigure, ncol=columns, frameon=False,
            fontsize=8, borderaxespad=0.0, borderpad=0.20, labelspacing=0.45,
            columnspacing=1.10, handlelength=1.8, handletextpad=0.50,
        )
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        legend_box = legend.get_window_extent(renderer)
        legend_width, legend_height = legend_box.width / fig.dpi, legend_box.height / fig.dpi
        if legend_width <= base_width - 2 * side_pad or columns == 1:
            break
        columns -= 1
    panel_boxes = [ax.get_tightbbox(renderer) for ax in panel_axes]
    panel_boxes = [box for box in panel_boxes if box is not None]
    left_extra = max(0.0, side_pad - min(box.x0 / fig.dpi for box in panel_boxes))
    right_extra = max(0.0, max(box.x1 / fig.dpi for box in panel_boxes) - base_width + side_pad)
    bottom_extra = max(0.0, bottom_pad - min(box.y0 / fig.dpi for box in panel_boxes))
    panel_width = base_width + left_extra + right_extra
    final_width = max(panel_width, legend_width + 2 * side_pad)
    horizontal_offset = left_extra + (final_width - panel_width) / 2
    panel_ceiling = max(box.y1 / fig.dpi for box in panel_boxes) + bottom_extra
    header_bottom = max(base_height + bottom_extra, panel_ceiling) + legend_gap
    final_height = header_bottom + legend_height + top_pad

    def apply_canvas(height):
        fig.set_size_inches(final_width, height, forward=True)
        for ax, (left, bottom, width, panel_height) in zip(panel_axes, panel_rectangles):
            ax.set_position([(left + horizontal_offset) / final_width,
                             (bottom + bottom_extra) / height,
                             width / final_width, panel_height / height])
        legend.set_bbox_to_anchor((0.5, 1.0 - top_pad / height), transform=fig.transFigure)

    apply_canvas(final_height)
    # Font backends can differ; reserve the measured separation after resizing.
    for _ in range(3):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        current_top = max(ax.get_tightbbox(renderer).y1 / fig.dpi for ax in panel_axes)
        current_legend_bottom = legend.get_window_extent(renderer).y0 / fig.dpi
        missing = current_top + legend_gap - current_legend_bottom
        if missing <= 0.001:
            break
        final_height += missing + 0.02
        apply_canvas(final_height)
    fig.canvas.draw()
    return {
        "figure_inches": [float(final_width), float(final_height)],
        "panel_canvas_inches": [base_width, base_height],
        "legend_columns": columns,
        "legend_rows": int(math.ceil(len(handles) / columns)),
        "legend_height_inches": float(legend_height),
        "minimum_legend_gap_inches": legend_gap,
        "layout_engine": "none",
    }



