def log(stage, message):
    EVENTS.append({"time": datetime.now(timezone.utc).isoformat(),
                   "stage": str(stage), "message": str(message)})
    print(f"[{stage}] {message}", flush=True)


def fingerprint(payload):
    return hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode()).hexdigest()


def digest_file(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(8 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def seed_for(run_seed, *stages):
    return int(np.random.SeedSequence([int(run_seed), *map(int, stages)]).generate_state(1)[0])


def write_json(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".partial")
    temporary.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
    temporary.replace(path)


def save_npz(path, **arrays):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".partial")
    with temporary.open("wb") as target:
        np.savez_compressed(target, **arrays)
    temporary.replace(path)


def save_csv(frame, name):
    path = TABLE_DIR / f"{name}.csv"
    temporary = path.with_suffix(".csv.partial")
    frame.to_csv(temporary, index=False)
    temporary.replace(path)


def month_index(values):
    return pd.PeriodIndex(pd.Series(values).astype(str), freq="M")


class ArtifactSource:
    """Read the user's main-experiment outputs directly from ZIPs or folders."""

    def __init__(self, path, role):
        self.path, self.role = Path(path).expanduser().resolve(), role
        self.archive = zipfile.ZipFile(self.path) if self.path.is_file() else None
        if self.archive is not None:
            self.names = [n for n in self.archive.namelist() if not n.endswith("/")]
            self.signature = digest_file(self.path)
        else:
            self.names = [p.relative_to(self.path).as_posix()
                          for p in self.path.rglob("*") if p.is_file()]
            manifest = []
            for name in sorted(self.names):
                if name.endswith((".joblib", ".json", ".parquet")):
                    stat = (self.path / name).stat()
                    manifest.append((name, stat.st_size, stat.st_mtime_ns))
            self.signature = fingerprint(manifest)

        self.name_set = set(self.names)

    def member(self, relative):
        if relative in self.name_set:
            return relative
        matches = [name for name in self.names if name.endswith("/" + relative)]
        if len(matches) == 1:
            return matches[0]
        raise FileNotFoundError(f"{self.role}: required output {relative} was not found uniquely in {self.path.name}.")

    def has(self, relative):
        try:
            self.member(relative)
            return True
        except FileNotFoundError:
            return False

    def read_bytes(self, relative):
        member = self.member(relative)
        return self.archive.read(member) if self.archive else (self.path / member).read_bytes()

    def read_json(self, relative):
        return json.loads(self.read_bytes(relative).decode("utf-8"))

    def read_csv(self, relative):
        return pd.read_csv(io.BytesIO(self.read_bytes(relative)))

    def read_joblib(self, relative):
        return joblib.load(io.BytesIO(self.read_bytes(relative)))

    def describe(self):
        return {"role": self.role, "path": str(self.path), "signature": self.signature}

    def close(self):
        if self.archive:
            self.archive.close()



# Reuse completed numerical results directly when only the figure is changing.
def locate_saved_summary():
    if not PLOT["reuse_existing_summary"]:
        return None
    requested = PLOT["results_dir"] or RUN["output_dir"]
    if requested:
        candidates = [Path(requested).expanduser()]
    else:
        roots = list(dict.fromkeys([BASE_DIR, Path.cwd()]))
        candidates = list({folder.resolve() for root in roots for folder in root.glob("appendix_downstream_*")
                           if folder.is_dir()})
        candidates.sort(key=lambda folder: (folder.stat().st_mtime_ns, folder.name), reverse=True)
    ignored_settings = {"show_figure", "auto_download", "archive_checkpoints", "n_jobs"}
    expected = {key: value for key, value in CFG.items() if key not in ignored_settings}
    for folder in candidates:
        summary_path = folder / "tables" / "downstream_robustness_summary_bp.csv"
        configuration_path = folder / "run_configuration.json"
        if not (summary_path.is_file() and configuration_path.is_file()):
            continue
        configuration = json.loads(configuration_path.read_text(encoding="utf-8"))
        settings = {key: value for key, value in configuration.get("settings", {}).items() if key not in ignored_settings}
        if (settings != expected or configuration.get("bootstrap") != BS
                or configuration.get("feature_order") != FEATURES
                or configuration.get("downstream_specifications") != SPEC):
            if requested:
                raise ValueError("The configured results folder uses different numerical experiment settings.")
            continue
        summary = pd.read_csv(summary_path)
        required = {"group", "feature", "analysis", "parameter", "block_length", "mean", "se", "lo", "hi", "status"}
        if not required.issubset(summary.columns):
            if requested:
                raise ValueError("The saved summary requires the complete downstream result columns.")
            continue
        expected_rows = len(FEATURES) * len(SPEC["block_lengths"]) * (
            1 + len(SPEC["quantiles"]) + len(SPEC["sort_groups"]) + len(SPEC["state_cut_quantiles"]))
        if len(summary[summary["group"].eq("All")]) != expected_rows:
            if requested:
                raise ValueError("The configured results folder contains an incomplete aggregate summary.")
            continue
        return folder.resolve(), configuration, summary
    return None


