    README = f"""DOWNSTREAM SPECIFICATION ROBUSTNESS
    Version: {VERSION}

    RUNNING IN GOOGLE COLAB
    Paste the entire file into one Colab code cell.
    Existing main output folders and earlier appendix outputs are discovered
    automatically. INPUT and PANEL_INPUTS paths are optional. No upload dialog
    is used. Complete reusable panels are preferred in this order:
    1. Main Experiment 2 monthly explanation Parquet files.
    2. Conditional Reference Ablation Full-reference checkpoints.
    3. Feature-Order Sensitivity main-order checkpoints.
    4. Integration Budget and Sampling Antithetic-16 checkpoints.
    The dedicated fixed-panel cache is reused on subsequent runs. Each complete
    model-seed pipeline comes from one source. Data signatures, original feature
    identities and observation keys preserve alignment with the response panel.
    Archived French data preserve the exact vintage of the reusable panels.
    If a panel is missing, fit or reuse the main prediction protocol and construct
    that panel once. All downstream settings then reuse the same frozen panel.
    Raw French sources download directly in a fresh session. Source vintages
    for state construction and explanation panels are matched explicitly.

    FIXED PREDICTION AND EXPLANATION PIPELINE
    French 100 monthly portfolios; realized-return months {CFG['test_start']}
    through {CFG['test_end']}; all eligible portfolio-months. Three models and
    three seeds follow the main annual expanding estimation, 60-month validation
    window and one-month purge. Keep all six features in their main order,
    the full Ledoit-Wolf Gaussian, 16 antithetic conditional draws and the
    shared annual 1,024-draw baseline. Attributions retain original feature names.
    Cached integration-experiment panels retain their recorded nested-stream
    implementation. The selected panel is fixed across all downstream comparisons.

    SPECIFICATIONS
    Stationary-bootstrap mean block lengths: {SPEC['block_lengths']} months;
    7 months is the main automatic choice for a 300-month calendar.
    QR quantiles: {SPEC['quantiles']}; joint monthly standardized attribution
    design, including all six coordinates with cross-sectional variation.
    Portfolio groups: {SPEC['sort_groups']}; equal-weight group returns,
    minimum {SPEC['min_bin']} portfolios per bin, original quantile-cut rule.
    Tied cuts and undersized bins retain explicit support records. Sort effects
    are the highest-minus-lowest group return for the same named feature.
    State cutoff quantiles: {SPEC['state_cut_quantiles']}. At return month r,
    the state uses the preceding 12 months of the equal-weight source-portfolio
    excess-return proxy. The source proxy is formed before feature filtering.
    Each cutoff uses initial training history ending in
    {TEST_MONTHS[0] - CFG['validation_months'] - 1}, then stays fixed throughout
    the test calendar. State effects are High-minus-Low monthly FM slopes.
    TWFE: preserve entity and month fixed effects and compare entity, month
    and two-way clustered standard errors for each model/seed pipeline.
    Small-sample corrections use the exact absorbed fixed-effect rank and
    residual degrees of freedom. Student-t reference degrees of freedom are
    cluster counts minus one, using the smaller count for two-way clustering.

    AGGREGATION AND INFERENCE
    Average all three models and three seeds with fixed weights each month.
    A missing component propagates to the aggregate. Model-specific tables
    average the same three seeds. QR quantiles and sorting choices use common
    supported months for each feature. State labels and monthly coefficients
    are resampled together. Require at least {SPEC['min_regime_months']} observed
    months in each state and at least two sampled months per state per draw.
    Use {BS['empirical_reps']} complete-calendar stationary-bootstrap resamples
    per block length, with shared random uniforms across block choices.
    Pointwise percentile intervals have level {BS['level']:.0%}.
    P-values use centered deviations with the plus-one correction. Holm columns
    identify the full {TESTS_PER_BLOCK * len(SPEC['block_lengths'])}-test grid,
    the {TESTS_PER_BLOCK}-test family within each block and the focal-feature
    grid, separately for each model group. Unsupported tests retain their slots.
    Paired sorting contrasts compare 3/10 groups with the main five-group design.
    TWFE cluster results retain specification-level coefficients and inference.

    {FIGURE_NOTES}
    OUTPUTS
    figures/downstream_specification_robustness.pdf: the single four-panel figure.
    figures/downstream_specification_robustness.png: the same figure as a PNG.
    tables/downstream_robustness_summary_bp.csv: aggregate estimates and inference.
    tables/downstream_robustness_by_model_bp.csv: prediction-model-specific results.
    tables/paired_sort_specification_differences_bp.csv: matched sorting contrasts.
    tables/bootstrap_interval_width_sensitivity.csv: interval-width ratios to block 7.
    tables/twfe_cluster_sensitivity_by_model_seed_bp.csv: clustered TWFE comparisons.
    tables/aggregate_monthly_analysis_series.csv: reusable monthly analysis series.
    tables/monthly_analysis_support.csv: regression and sorting support records.
    tables/predetermined_state_specifications.csv: states and fixed training cutoffs.
    tables/market_proxy.csv: full source-universe excess-return proxy.
    tables/frozen_panel_sources.csv: panel provenance for all model/seed pipelines.
    tables/observed_downstream_computation_times.csv: observed analysis times.
    data/French100_monthly.parquet: the historical feature and response panel.
    checkpoints/downstream/: compact monthly statistics and TWFE summaries.
    The complete fixed explanation panels remain in {PANEL_CACHE_DIR}.
    Default archives omit checkpoint arrays and the shared panel/model caches.
    Saved computation times describe the calculation that produced each checkpoint.

    Preparation status: authored only; execution and validation deferred.
    """
    (OUT_DIR / "README.txt").write_text(README, encoding="utf-8")
    write_json(OUT_DIR / "figure_layout.json", FIGURE_LAYOUT)
    log("Export", f"Writing numerical tables, metadata and one figure; elapsed={elapsed_seconds / 60:.1f} min.")



